var LEARN = [{"id": "pow", "u": "A", "n": "Power rule and linearity", "nt": "กฎเลขยกกำลังและความเป็นเชิงเส้น", "thm": [{"en": "<b>Lemma.</b> If $G'(x)=0$ for every $x$ in an interval $I$, then $G$ is constant on $I$.", "th": "<b>บทตั้ง</b> ถ้า $G'(x)=0$ สำหรับทุก $x$ ในช่วง $I$ แล้ว $G$ เป็นค่าคงตัวบน $I$"}, {"en": "<b>Theorem (power rule).</b> Let $n\\neq-1$ be real and let $I$ be an interval on which $x^{n}$ is differentiable. Then the antiderivatives of $x^{n}$ on $I$ are exactly <span class=\"mdisp\">$\\displaystyle \\int x^{n}\\,dx=\\frac{x^{n+1}}{n+1}+C,\\qquad C\\in\\mathbb{R}.$</span>", "th": "<b>ทฤษฎีบท (กฎเลขยกกำลัง)</b> ให้ $n\\neq-1$ เป็นจำนวนจริง และ $I$ เป็นช่วงที่ $x^{n}$ หาอนุพันธ์ได้ แล้วปฏิยานุพันธ์ทั้งหมดของ $x^{n}$ บน $I$ คือ <span class=\"mdisp\">$\\displaystyle \\int x^{n}\\,dx=\\frac{x^{n+1}}{n+1}+C,\\qquad C\\in\\mathbb{R}$</span>"}, {"en": "<b>Theorem (linearity).</b> If $F'=f$ and $G'=g$ on $I$, and $a,b\\in\\mathbb{R}$, then <span class=\"mdisp\">$\\displaystyle \\int\\big(af+bg\\big)\\,dx=a\\int f\\,dx+b\\int g\\,dx.$</span>", "th": "<b>ทฤษฎีบท (ความเป็นเชิงเส้น)</b> ถ้า $F'=f$ และ $G'=g$ บน $I$ และ $a,b\\in\\mathbb{R}$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int\\big(af+bg\\big)\\,dx=a\\int f\\,dx+b\\int g\\,dx$</span>"}, {"en": "The interval matters: on $\\mathbb{R}\\setminus\\{0\\}$ the constant may be different on each side of $0$.", "th": "ช่วงมีความสำคัญ: บน $\\mathbb{R}\\setminus\\{0\\}$ ค่าคงตัวทางซ้ายและขวาของ $0$ อาจต่างกันได้"}], "proof": [{"en": "Proof of the lemma. Take any $x&lt;y$ in $I$. $G$ is differentiable on $[x,y]$, so the mean value theorem gives a $c\\in(x,y)$ with", "th": "พิสูจน์บทตั้ง ให้ $x&lt;y$ ใด ๆ ใน $I$ เนื่องจาก $G$ หาอนุพันธ์ได้บน $[x,y]$ ทฤษฎีบทค่าเฉลี่ยให้ $c\\in(x,y)$ ที่", "m": "G(y)-G(x)=G'(c)\\,(y-x)=0\\cdot(y-x)=0."}, {"en": "So $G(x)=G(y)$ for all $x,y\\in I$: $G$ is constant.", "th": "ดังนั้น $G(x)=G(y)$ ทุก $x,y\\in I$ นั่นคือ $G$ เป็นค่าคงตัว", "m": ""}, {"en": "Power rule. Since $n+1\\neq0$, the derivative power rule gives, for every $x\\in I$,", "th": "กฎเลขยกกำลัง เนื่องจาก $n+1\\neq0$ กฎการหาอนุพันธ์ให้ว่าทุก $x\\in I$", "m": "\\frac{d}{dx}\\left(\\frac{x^{n+1}}{n+1}\\right)=\\frac{(n+1)x^{n}}{n+1}=x^{n}."}, {"en": "So $\\dfrac{x^{n+1}}{n+1}+C$ is an antiderivative. Conversely, let $H$ be any antiderivative of $x^{n}$ on $I$. Then", "th": "ดังนั้น $\\dfrac{x^{n+1}}{n+1}+C$ เป็นปฏิยานุพันธ์ ในทางกลับกัน ให้ $H$ เป็นปฏิยานุพันธ์ใด ๆ ของ $x^{n}$ บน $I$ จะได้", "m": "\\left(H(x)-\\frac{x^{n+1}}{n+1}\\right)'=x^{n}-x^{n}=0,"}, {"en": "and by the lemma $H(x)-\\dfrac{x^{n+1}}{n+1}$ is a constant $C$. This is every antiderivative.", "th": "และจากบทตั้ง $H(x)-\\dfrac{x^{n+1}}{n+1}$ เป็นค่าคงตัว $C$ จึงได้ปฏิยานุพันธ์ครบทุกตัว", "m": ""}, {"en": "Linearity. Differentiation is linear, so", "th": "ความเป็นเชิงเส้น การหาอนุพันธ์เป็นเชิงเส้น ดังนั้น", "m": "(aF+bG)'=aF'+bG'=af+bg,"}, {"en": "so $aF+bG$ is an antiderivative of $af+bg$; by the lemma every other one differs from it by a constant. $\\blacksquare$", "th": "ดังนั้น $aF+bG$ เป็นปฏิยานุพันธ์ของ $af+bg$ และจากบทตั้ง ตัวอื่นต่างจากนี้เพียงค่าคงตัว $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int\\left(4x^{3}-6x+2\\right)dx", "al": "x^{4}-3x^{2}+2x+C", "s": ["=4\\cdot\\frac{x^{4}}{4}-6\\cdot\\frac{x^{2}}{2}+2x+C", "=x^{4}-3x^{2}+2x+C"]}, {"q": "\\int_{1}^{4}\\sqrt{x}\\,(x+1)\\,dx", "al": "\\frac{256}{15}", "s": ["\\sqrt{x}(x+1)=x^{\\frac32}+x^{\\frac12}", "\\left[\\tfrac25x^{\\frac52}+\\tfrac23x^{\\frac32}\\right]_{1}^{4}", "=\\tfrac25(32-1)+\\tfrac23(8-1)=\\frac{62}{5}+\\frac{14}{3}=\\frac{256}{15}"]}], "pr": [{"q": "\\int\\left(5x^{4}+3x^{2}\\right)dx", "al": "x^{5}+x^{3}+C", "s": ["5\\cdot\\frac{x^{5}}{5}+3\\cdot\\frac{x^{3}}{3}+C", "=x^{5}+x^{3}+C"], "h": "Use the power rule on each term.", "ht": "ใช้กฎเลขยกกำลังทีละพจน์", "c": 1, "p": [[0.65, 1.85, 27.6109575], [0.845, 1.415, 7.471589968106249], [1.1, 1.655, 14.007813283284376]]}, {"q": "\\int_{1}^{2}\\left(6x^{2}-4x\\right)dx", "al": "8", "s": ["\\left[2x^{3}-2x^{2}\\right]_{1}^{2}", "=(16-8)-(2-2)=8"], "h": "Antiderivative first, then $F(2)-F(1)$.", "ht": "หาปฏิยานุพันธ์ก่อน แล้วคำนวณ $F(2)-F(1)$", "v": 8.0}, {"q": "\\int_{1}^{4}\\left(3\\sqrt{x}-\\frac{1}{x^{2}}\\right)dx", "al": "\\frac{53}{4}", "s": ["\\left[2x^{\\frac32}+\\frac1x\\right]_{1}^{4}", "=\\left(16+\\tfrac14\\right)-(2+1)=\\frac{53}{4}"], "h": "Write $\\sqrt{x}=x^{1/2}$ and $\\frac{1}{x^{2}}=x^{-2}$.", "ht": "เขียน $\\sqrt{x}=x^{1/2}$ และ $\\frac{1}{x^{2}}=x^{-2}$", "v": 13.25}, {"q": "\\int\\left(x^{2}+1\\right)^{2}dx", "al": "\\frac{x^{5}}{5}+\\frac{2x^{3}}{3}+x+C", "s": ["\\left(x^{2}+1\\right)^{2}=x^{4}+2x^{2}+1", "\\frac{x^{5}}{5}+\\frac{2x^{3}}{3}+x+C"], "h": "Expand the bracket first.", "ht": "กระจายวงเล็บก่อน", "c": 1, "p": [[0.65, 1.85, 9.5487915], [0.845, 1.415, 3.10489004362125], [1.1, 1.655, 4.850869631656876]]}, {"q": "\\int_{1}^{8}\\left(x^{\\frac13}+2\\right)dx", "al": "\\frac{101}{4}", "s": ["\\left[\\tfrac34x^{\\frac43}+2x\\right]_{1}^{8}", "=(12+16)-\\left(\\tfrac34+2\\right)=\\frac{101}{4}"], "h": "$x^{4/3}$ at $x=8$ is $16$.", "ht": "$x^{4/3}$ ที่ $x=8$ เท่ากับ $16$", "v": 25.25}]}, {"id": "exp", "u": "A", "n": "1/x and exponentials", "nt": "1/x และฟังก์ชันเลขชี้กำลัง", "thm": [{"en": "<b>Theorem.</b> (i) On any interval not containing $0$, <span class=\"mdisp\">$\\displaystyle \\int\\frac{1}{x}\\,dx=\\ln|x|+C.$</span> (ii) On $\\mathbb{R}$, $\\displaystyle\\int e^{x}\\,dx=e^{x}+C$, and for $a&gt;0$, $a\\neq1$: <span class=\"mdisp\">$\\displaystyle \\int a^{x}\\,dx=\\frac{a^{x}}{\\ln a}+C.$</span>", "th": "<b>ทฤษฎีบท</b> (i) บนช่วงใด ๆ ที่ไม่มี $0$ <span class=\"mdisp\">$\\displaystyle \\int\\frac{1}{x}\\,dx=\\ln|x|+C$</span> (ii) บน $\\mathbb{R}$ $\\displaystyle\\int e^{x}\\,dx=e^{x}+C$ และสำหรับ $a&gt;0$, $a\\neq1$: <span class=\"mdisp\">$\\displaystyle \\int a^{x}\\,dx=\\frac{a^{x}}{\\ln a}+C$</span>"}, {"en": "Warning: $\\displaystyle\\int_{-1}^{1}\\frac{dx}{x}$ does not exist, because $0$ is inside the interval and the improper integral diverges.", "th": "ข้อควรระวัง: $\\displaystyle\\int_{-1}^{1}\\frac{dx}{x}$ ไม่มีค่า เพราะ $0$ อยู่ในช่วงและอินทิกรัลไม่ตรงแบบลู่ออก"}], "proof": [{"en": "For $x&gt;0$: $\\ln|x|=\\ln x$ and", "th": "เมื่อ $x&gt;0$: $\\ln|x|=\\ln x$ และ", "m": "\\frac{d}{dx}\\ln x=\\frac1x."}, {"en": "For $x&lt;0$: $\\ln|x|=\\ln(-x)$, and by the chain rule", "th": "เมื่อ $x&lt;0$: $\\ln|x|=\\ln(-x)$ และจากกฎลูกโซ่", "m": "\\frac{d}{dx}\\ln(-x)=\\frac{1}{-x}\\cdot(-1)=\\frac1x."}, {"en": "So $\\ln|x|$ is an antiderivative of $\\frac1x$ on any interval avoiding $0$; by the lemma of lesson 1 all others are $\\ln|x|+C$ on that interval.", "th": "ดังนั้น $\\ln|x|$ เป็นปฏิยานุพันธ์ของ $\\frac1x$ บนช่วงที่ไม่มี $0$ และจากบทตั้งในบทที่ 1 ตัวอื่นทั้งหมดคือ $\\ln|x|+C$ บนช่วงนั้น", "m": ""}, {"en": "$(e^{x})'=e^{x}$, which gives the second result. For $a^{x}$, write $a^{x}=e^{x\\ln a}$; by the chain rule", "th": "$(e^{x})'=e^{x}$ ได้ผลข้อที่สอง สำหรับ $a^{x}$ เขียน $a^{x}=e^{x\\ln a}$ และจากกฎลูกโซ่", "m": "\\frac{d}{dx}a^{x}=\\ln a\\cdot e^{x\\ln a}=a^{x}\\ln a."}, {"en": "Since $a\\neq1$, $\\ln a\\neq0$, so we may divide: $\\left(\\dfrac{a^{x}}{\\ln a}\\right)'=a^{x}$. $\\blacksquare$", "th": "เนื่องจาก $a\\neq1$ จะได้ $\\ln a\\neq0$ จึงหารได้: $\\left(\\dfrac{a^{x}}{\\ln a}\\right)'=a^{x}$ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{-3}^{-1}\\frac{1}{x}\\,dx", "al": "-\\ln3", "s": ["\\text{The interval }[-3,-1]\\text{ avoids }0", "\\left[\\ln|x|\\right]_{-3}^{-1}=\\ln1-\\ln3=-\\ln3"]}, {"q": "\\int2^{x}\\,dx", "al": "\\frac{2^{x}}{\\ln2}+C", "s": ["a=2:\\ \\int a^{x}dx=\\frac{a^{x}}{\\ln a}+C", "=\\frac{2^{x}}{\\ln2}+C"]}], "pr": [{"q": "\\int_{1}^{e^{2}}\\frac{3}{x}\\,dx", "al": "6", "s": ["\\left[3\\ln x\\right]_{1}^{e^{2}}=3\\cdot2-0=6"], "h": "$\\ln(e^{2})=2$.", "ht": "$\\ln(e^{2})=2$", "v": 6.0}, {"q": "\\int_{0}^{1}\\left(e^{x}+1\\right)dx", "al": "e", "s": ["\\left[e^{x}+x\\right]_{0}^{1}=(e+1)-(1+0)=e"], "h": "Integrate each term.", "ht": "อินทิเกรตทีละพจน์", "v": 2.718281828459045}, {"q": "\\int_{-e}^{-1}\\frac{1}{x}\\,dx", "al": "-1", "s": ["\\left[\\ln|x|\\right]_{-e}^{-1}=\\ln1-\\ln e=-1"], "h": "Use $\\ln|x|$: the interval is negative.", "ht": "ใช้ $\\ln|x|$ เพราะช่วงเป็นค่าลบ", "v": -1.0}, {"q": "\\int3^{x}\\,dx", "al": "\\frac{3^{x}}{\\ln3}+C", "s": ["\\frac{3^{x}}{\\ln3}+C"], "h": "$\\int a^{x}dx=\\frac{a^{x}}{\\ln a}+C$.", "ht": "$\\int a^{x}dx=\\frac{a^{x}}{\\ln a}+C$", "c": 1, "p": [[0.2, 1.8, 5.442268558159916], [0.46, 1.22, 1.9685117687638771], [0.8, 1.54, 2.7501617673735725]]}, {"q": "\\int_{1}^{2}\\frac{(x+1)^{2}}{x}\\,dx", "al": "\\frac72+\\ln2", "s": ["\\frac{(x+1)^{2}}{x}=x+2+\\frac1x", "\\left[\\tfrac{x^{2}}{2}+2x+\\ln x\\right]_{1}^{2}", "=(2+4+\\ln2)-\\left(\\tfrac12+2\\right)=\\frac72+\\ln2"], "h": "Expand, then divide each term by $x$.", "ht": "กระจายแล้วหารแต่ละพจน์ด้วย $x$", "v": 4.193147180559945}]}, {"id": "trig", "u": "A", "n": "Standard trig integrals", "nt": "อินทิกรัลตรีโกณมาตรฐาน", "thm": [{"en": "<b>Theorem.</b> On every interval where the integrand is defined: <span class=\"mdisp\">$\\displaystyle \\int\\sin x\\,dx=-\\cos x+C,\\quad \\int\\cos x\\,dx=\\sin x+C,$</span> <span class=\"mdisp\">$\\displaystyle \\int\\sec^{2}x\\,dx=\\tan x+C,\\quad \\int\\csc^{2}x\\,dx=-\\cot x+C,$</span> <span class=\"mdisp\">$\\displaystyle \\int\\sec x\\tan x\\,dx=\\sec x+C,\\quad \\int\\csc x\\cot x\\,dx=-\\csc x+C,$</span> <span class=\"mdisp\">$\\displaystyle \\int\\tan x\\,dx=\\ln|\\sec x|+C,\\quad \\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|+C.$</span>", "th": "<b>ทฤษฎีบท</b> บนทุกช่วงที่ฟังก์ชันนิยาม: <span class=\"mdisp\">$\\displaystyle \\int\\sin x\\,dx=-\\cos x+C,\\quad \\int\\cos x\\,dx=\\sin x+C,$</span> <span class=\"mdisp\">$\\displaystyle \\int\\sec^{2}x\\,dx=\\tan x+C,\\quad \\int\\csc^{2}x\\,dx=-\\cot x+C,$</span> <span class=\"mdisp\">$\\displaystyle \\int\\sec x\\tan x\\,dx=\\sec x+C,\\quad \\int\\csc x\\cot x\\,dx=-\\csc x+C,$</span> <span class=\"mdisp\">$\\displaystyle \\int\\tan x\\,dx=\\ln|\\sec x|+C,\\quad \\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|+C$</span>"}, {"en": "We assume $(\\sin x)'=\\cos x$ and $(\\cos x)'=-\\sin x$ (these follow from $\\displaystyle\\lim_{h\\to0}\\frac{\\sin h}{h}=1$, with $x$ in radians).", "th": "เราใช้ $(\\sin x)'=\\cos x$ และ $(\\cos x)'=-\\sin x$ (ได้จาก $\\displaystyle\\lim_{h\\to0}\\frac{\\sin h}{h}=1$ โดย $x$ เป็นเรเดียน)"}], "proof": [{"en": "Each line follows by differentiating the right-hand side. The first two are the assumed derivatives.", "th": "แต่ละบรรทัดพิสูจน์ได้โดยหาอนุพันธ์ของด้านขวา สองบรรทัดแรกคืออนุพันธ์ที่สมมติไว้", "m": ""}, {"en": "Quotient rule, where $\\cos x\\neq0$:", "th": "กฎผลหาร เมื่อ $\\cos x\\neq0$:", "m": "(\\tan x)'=\\left(\\frac{\\sin x}{\\cos x}\\right)'=\\frac{\\cos^{2}x+\\sin^{2}x}{\\cos^{2}x}=\\sec^{2}x,\\qquad (\\sec x)'=\\frac{\\sin x}{\\cos^{2}x}=\\sec x\\tan x."}, {"en": "The same with $\\sin x\\neq0$ gives $(\\cot x)'=-\\csc^{2}x$ and $(\\csc x)'=-\\csc x\\cot x$.", "th": "ทำแบบเดียวกันเมื่อ $\\sin x\\neq0$ ได้ $(\\cot x)'=-\\csc^{2}x$ และ $(\\csc x)'=-\\csc x\\cot x$", "m": ""}, {"en": "For $\\tan$: by the chain rule, $(\\ln|g|)'=g'/g$ wherever $g\\neq0$ (lesson 2). With $g=\\sec x$:", "th": "สำหรับ $\\tan$: จากกฎลูกโซ่ $(\\ln|g|)'=g'/g$ เมื่อ $g\\neq0$ (บทที่ 2) ให้ $g=\\sec x$:", "m": "(\\ln|\\sec x|)'=\\frac{\\sec x\\tan x}{\\sec x}=\\tan x."}, {"en": "For $\\sec$: with $g=\\sec x+\\tan x$ (where $g\\neq0$):", "th": "สำหรับ $\\sec$: ให้ $g=\\sec x+\\tan x$ (เมื่อ $g\\neq0$):", "m": "(\\ln|\\sec x+\\tan x|)'=\\frac{\\sec x\\tan x+\\sec^{2}x}{\\sec x+\\tan x}=\\frac{\\sec x(\\tan x+\\sec x)}{\\sec x+\\tan x}=\\sec x.\\ \\blacksquare"}], "ex": [{"q": "\\int_{0}^{\\frac{\\pi}{3}}\\sec x\\tan x\\,dx", "al": "1", "s": ["\\left[\\sec x\\right]_{0}^{\\frac{\\pi}{3}}=2-1=1"]}, {"q": "\\int\\left(3\\cos x-2\\sec^{2}x\\right)dx", "al": "3\\sin x-2\\tan x+C", "s": ["3\\sin x-2\\tan x+C"]}], "pr": [{"q": "\\int_{0}^{\\frac{\\pi}{2}}\\left(\\sin x+\\cos x\\right)dx", "al": "2", "s": ["\\left[-\\cos x+\\sin x\\right]_{0}^{\\frac{\\pi}{2}}=(0+1)-(-1+0)=2"], "h": "$\\int\\sin=-\\cos$, $\\int\\cos=\\sin$.", "ht": "$\\int\\sin=-\\cos$, $\\int\\cos=\\sin$", "v": 2.0}, {"q": "\\int_{\\frac{\\pi}{6}}^{\\frac{\\pi}{2}}\\csc^{2}x\\,dx", "al": "\\sqrt3", "s": ["\\left[-\\cot x\\right]_{\\frac{\\pi}{6}}^{\\frac{\\pi}{2}}=0-\\left(-\\sqrt3\\right)=\\sqrt3"], "h": "$\\int\\csc^{2}x\\,dx=-\\cot x$.", "ht": "$\\int\\csc^{2}x\\,dx=-\\cot x$", "v": 1.7320508075688772}, {"q": "\\int_{0}^{\\frac{\\pi}{4}}\\tan x\\,dx", "al": "\\frac{\\ln2}{2}", "s": ["\\left[\\ln|\\sec x|\\right]_{0}^{\\frac{\\pi}{4}}=\\ln\\sqrt2-\\ln1=\\frac{\\ln2}{2}"], "h": "$\\int\\tan x\\,dx=\\ln|\\sec x|$.", "ht": "$\\int\\tan x\\,dx=\\ln|\\sec x|$", "v": 0.34657359027997264}, {"q": "\\int_{0}^{\\frac{\\pi}{4}}\\sec x\\,dx", "al": "\\ln\\left(1+\\sqrt2\\right)", "s": ["\\left[\\ln|\\sec x+\\tan x|\\right]_{0}^{\\frac{\\pi}{4}}=\\ln\\left(\\sqrt2+1\\right)-\\ln1"], "h": "$\\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|$.", "ht": "$\\int\\sec x\\,dx=\\ln|\\sec x+\\tan x|$", "v": 0.881373587019543}, {"q": "\\int\\left(2\\cos x-\\sec x\\tan x\\right)dx", "al": "2\\sin x-\\sec x+C", "s": ["2\\sin x-\\sec x+C"], "h": "$\\int\\sec x\\tan x\\,dx=\\sec x$.", "ht": "$\\int\\sec x\\tan x\\,dx=\\sec x$", "c": 1, "p": [[0.21000000000000002, 1.09, 0.21656602315694526], [0.353, 0.7709999999999999, 0.3737052165644706], [0.54, 0.947, 0.04898374112377684]]}]}, {"id": "ftc", "u": "A", "n": "The Fundamental Theorem of Calculus", "nt": "ทฤษฎีบทหลักมูลของแคลคูลัส", "thm": [{"en": "<b>Theorem (FTC).</b> Let $f$ be continuous on $[a,b]$. <br>(1) The function $A(x)=\\displaystyle\\int_{a}^{x}f(t)\\,dt$ is differentiable on $(a,b)$ and $A'(x)=f(x)$. <br>(2) If $F$ is continuous on $[a,b]$ with $F'=f$ on $(a,b)$, then <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f(x)\\,dx=F(b)-F(a).$</span>", "th": "<b>ทฤษฎีบท (FTC)</b> ให้ $f$ ต่อเนื่องบน $[a,b]$ <br>(1) ฟังก์ชัน $A(x)=\\displaystyle\\int_{a}^{x}f(t)\\,dt$ หาอนุพันธ์ได้บน $(a,b)$ และ $A'(x)=f(x)$ <br>(2) ถ้า $F$ ต่อเนื่องบน $[a,b]$ และ $F'=f$ บน $(a,b)$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f(x)\\,dx=F(b)-F(a)$</span>"}, {"en": "If $f\\ge g$ on $[a,b]$, the area between the curves is $\\displaystyle\\int_{a}^{b}\\big(f(x)-g(x)\\big)\\,dx$.", "th": "ถ้า $f\\ge g$ บน $[a,b]$ พื้นที่ระหว่างเส้นโค้งคือ $\\displaystyle\\int_{a}^{b}\\big(f(x)-g(x)\\big)\\,dx$"}], "proof": [{"en": "Mean value theorem for integrals. On $[x,x+h]$, $f$ is continuous, so by the extreme value theorem it has a minimum $m$ and maximum $M$; integrating $m\\le f\\le M$:", "th": "ทฤษฎีบทค่าเฉลี่ยสำหรับอินทิกรัล บน $[x,x+h]$ $f$ ต่อเนื่อง จึงมีค่าต่ำสุด $m$ และสูงสุด $M$ (ทฤษฎีบทค่าสุดขีด) อินทิเกรต $m\\le f\\le M$:", "m": "mh\\le\\int_{x}^{x+h}f(t)\\,dt\\le Mh."}, {"en": "By the intermediate value theorem, $f$ takes every value between $m$ and $M$, so there is $c_h\\in[x,x+h]$ with", "th": "จากทฤษฎีบทค่าระหว่างกลาง $f$ มีทุกค่าระหว่าง $m$ และ $M$ จึงมี $c_h\\in[x,x+h]$ ที่", "m": "\\int_{x}^{x+h}f(t)\\,dt=h\\,f(c_h)."}, {"en": "Part (1). By additivity of the integral, $A(x+h)-A(x)=\\int_{x}^{x+h}f$, so (the case $h&lt;0$ is the same on $[x+h,x]$)", "th": "ส่วน (1) จากสมบัติการบวกของอินทิกรัล $A(x+h)-A(x)=\\int_{x}^{x+h}f$ ดังนั้น (กรณี $h&lt;0$ ทำบน $[x+h,x]$ เช่นเดียวกัน)", "m": "\\frac{A(x+h)-A(x)}{h}=f(c_h)."}, {"en": "As $h\\to0$, $c_h\\to x$ (it is squeezed between $x$ and $x+h$), and $f$ is continuous, so $f(c_h)\\to f(x)$. Hence $A'(x)=f(x)$.", "th": "เมื่อ $h\\to0$ จะได้ $c_h\\to x$ (ถูกบีบระหว่าง $x$ และ $x+h$) และ $f$ ต่อเนื่อง ดังนั้น $f(c_h)\\to f(x)$ จึงได้ $A'(x)=f(x)$", "m": ""}, {"en": "Part (2). $F-A$ is continuous on $[a,b]$ with derivative $f-f=0$ on $(a,b)$. By the mean value theorem (as in lesson 1) it is constant, so", "th": "ส่วน (2) $F-A$ ต่อเนื่องบน $[a,b]$ และมีอนุพันธ์ $f-f=0$ บน $(a,b)$ จากทฤษฎีบทค่าเฉลี่ย (เหมือนบทที่ 1) จึงเป็นค่าคงตัว ดังนั้น", "m": "F(b)-A(b)=F(a)-A(a)=F(a)\\quad(\\text{since }A(a)=0)."}, {"en": "Therefore $\\displaystyle\\int_{a}^{b}f=A(b)=F(b)-F(a)$. $\\blacksquare$", "th": "ดังนั้น $\\displaystyle\\int_{a}^{b}f=A(b)=F(b)-F(a)$ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\text{Area between }y=x\\text{ and }y=x^{2}\\text{ for }0\\le x\\le1", "al": "\\frac16", "s": ["x\\ge x^{2}\\text{ on }[0,1]", "\\int_{0}^{1}\\left(x-x^{2}\\right)dx=\\frac12-\\frac13=\\frac16"]}, {"q": "\\int_{0}^{2}|x-1|\\,dx", "al": "1", "s": ["\\text{Split at }x=1:\\ \\int_{0}^{1}(1-x)\\,dx+\\int_{1}^{2}(x-1)\\,dx", "=\\frac12+\\frac12=1"]}], "pr": [{"q": "\\int_{-2}^{2}\\left(4-x^{2}\\right)dx", "al": "\\frac{32}{3}", "s": ["\\left[4x-\\tfrac{x^{3}}{3}\\right]_{-2}^{2}=\\left(8-\\tfrac83\\right)-\\left(-8+\\tfrac83\\right)=\\frac{32}{3}"], "h": "$F(2)-F(-2)$ with $F(x)=4x-\\frac{x^{3}}{3}$.", "ht": "$F(2)-F(-2)$ โดย $F(x)=4x-\\frac{x^{3}}{3}$", "v": 10.666666666666666}, {"q": "\\int_{0}^{3}|x-2|\\,dx", "al": "\\frac52", "s": ["\\int_{0}^{2}(2-x)\\,dx+\\int_{2}^{3}(x-2)\\,dx", "=2+\\frac12=\\frac52"], "h": "Split where $x-2$ changes sign.", "ht": "แยกช่วงที่ $x-2$ เปลี่ยนเครื่องหมาย", "v": 2.5}, {"q": "\\text{Area between }y=x\\text{ and }y=x^{3}\\text{ for }0\\le x\\le1", "al": "\\frac14", "s": ["x\\ge x^{3}\\text{ on }[0,1]", "\\int_{0}^{1}\\left(x-x^{3}\\right)dx=\\frac12-\\frac14=\\frac14"], "h": "Top curve minus bottom curve.", "ht": "เส้นโค้งบนลบเส้นโค้งล่าง", "v": 0.25}, {"q": "F(x)=\\int_{0}^{x}\\sqrt{1+t^{3}}\\,dt.\\ \\text{Find }F'(2).", "al": "3", "s": ["\\text{FTC part (1): }F'(x)=\\sqrt{1+x^{3}}", "F'(2)=\\sqrt{9}=3"], "h": "Part (1) of the FTC: no integrating needed.", "ht": "ใช้ FTC ส่วน (1) ไม่ต้องอินทิเกรต", "v": 3.0}, {"q": "\\int_{-1}^{2}\\left(3x^{2}-2x\\right)dx", "al": "6", "s": ["\\left[x^{3}-x^{2}\\right]_{-1}^{2}=(8-4)-(-1-1)=6"], "h": "Careful with $(-1)^{3}$.", "ht": "ระวัง $(-1)^{3}$", "v": 6.0}]}, {"id": "lin", "u": "B", "n": "Linear inside: f(ax+b)", "nt": "ฟังก์ชันเชิงเส้นข้างใน: f(ax+b)", "thm": [{"en": "<b>Theorem.</b> Let $F'=f$ on an interval $J$, and let $a\\neq0$, $b$ be real. Then on the interval $\\{x: ax+b\\in J\\}$, <span class=\"mdisp\">$\\displaystyle \\int f(ax+b)\\,dx=\\frac{1}{a}F(ax+b)+C.$</span>", "th": "<b>ทฤษฎีบท</b> ให้ $F'=f$ บนช่วง $J$ และ $a\\neq0$, $b$ เป็นจำนวนจริง แล้วบนช่วง $\\{x: ax+b\\in J\\}$ <span class=\"mdisp\">$\\displaystyle \\int f(ax+b)\\,dx=\\frac{1}{a}F(ax+b)+C$</span>"}, {"en": "Examples of $F$: $\\int(ax+b)^{n}dx=\\dfrac{(ax+b)^{n+1}}{a(n+1)}$, $\\int e^{ax+b}dx=\\dfrac{e^{ax+b}}{a}$, $\\int\\cos(ax+b)\\,dx=\\dfrac{\\sin(ax+b)}{a}$, $\\int\\dfrac{dx}{ax+b}=\\dfrac{\\ln|ax+b|}{a}$.", "th": "ตัวอย่าง: $\\int(ax+b)^{n}dx=\\dfrac{(ax+b)^{n+1}}{a(n+1)}$, $\\int e^{ax+b}dx=\\dfrac{e^{ax+b}}{a}$, $\\int\\cos(ax+b)\\,dx=\\dfrac{\\sin(ax+b)}{a}$, $\\int\\dfrac{dx}{ax+b}=\\dfrac{\\ln|ax+b|}{a}$"}], "proof": [{"en": "The map $x\\mapsto ax+b$ is continuous and $a\\neq0$, so $\\{x:ax+b\\in J\\}$ is an interval. On it the chain rule gives", "th": "ฟังก์ชัน $x\\mapsto ax+b$ ต่อเนื่องและ $a\\neq0$ ดังนั้น $\\{x:ax+b\\in J\\}$ เป็นช่วง บนช่วงนี้กฎลูกโซ่ให้", "m": "\\frac{d}{dx}\\left[\\frac1aF(ax+b)\\right]=\\frac1a\\cdot F'(ax+b)\\cdot a=f(ax+b)."}, {"en": "So $\\frac1aF(ax+b)$ is an antiderivative, and by the lemma of lesson 1 every antiderivative is this plus a constant. $\\blacksquare$", "th": "ดังนั้น $\\frac1aF(ax+b)$ เป็นปฏิยานุพันธ์ และจากบทตั้งในบทที่ 1 ทุกตัวต่างจากนี้เพียงค่าคงตัว $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int(2x+1)^{5}\\,dx", "al": "\\frac{(2x+1)^{6}}{12}+C", "s": ["a=2,\\ F(u)=\\frac{u^{6}}{6}", "\\frac12\\cdot\\frac{(2x+1)^{6}}{6}+C=\\frac{(2x+1)^{6}}{12}+C"]}, {"q": "\\int_{0}^{\\frac{\\pi}{4}}\\cos2x\\,dx", "al": "\\frac12", "s": ["\\left[\\tfrac12\\sin2x\\right]_{0}^{\\frac{\\pi}{4}}=\\tfrac12\\cdot1-0=\\frac12"]}], "pr": [{"q": "\\int_{0}^{1}(3x+1)^{3}\\,dx", "al": "\\frac{85}{4}", "s": ["\\left[\\frac{(3x+1)^{4}}{12}\\right]_{0}^{1}=\\frac{256-1}{12}=\\frac{85}{4}"], "h": "Divide by $a=3$ as well as by the new power.", "ht": "หารด้วย $a=3$ และเลขชี้กำลังใหม่", "v": 21.25}, {"q": "\\int_{0}^{1}e^{2x+1}\\,dx", "al": "\\frac{e^{3}-e}{2}", "s": ["\\left[\\tfrac12e^{2x+1}\\right]_{0}^{1}=\\frac{e^{3}-e}{2}"], "h": "$\\int e^{ax+b}dx=\\frac{1}{a}e^{ax+b}$.", "ht": "$\\int e^{ax+b}dx=\\frac{1}{a}e^{ax+b}$", "v": 8.683627547364312}, {"q": "\\int_{0}^{\\frac{\\pi}{6}}\\sin3x\\,dx", "al": "\\frac13", "s": ["\\left[-\\tfrac13\\cos3x\\right]_{0}^{\\frac{\\pi}{6}}=0+\\frac13=\\frac13"], "h": "$\\cos\\frac{\\pi}{2}=0$.", "ht": "$\\cos\\frac{\\pi}{2}=0$", "v": 0.3333333333333333}, {"q": "\\int_{1}^{3}\\frac{1}{2x-1}\\,dx", "al": "\\frac{\\ln5}{2}", "s": ["\\left[\\tfrac12\\ln|2x-1|\\right]_{1}^{3}=\\tfrac12(\\ln5-\\ln1)=\\frac{\\ln5}{2}"], "h": "$\\int\\frac{dx}{ax+b}=\\frac{1}{a}\\ln|ax+b|$.", "ht": "$\\int\\frac{dx}{ax+b}=\\frac{1}{a}\\ln|ax+b|$", "v": 0.8047189562170501}, {"q": "\\int\\sec^{2}4x\\,dx", "al": "\\frac{\\tan4x}{4}+C", "s": ["\\frac14\\tan4x+C"], "h": "$\\int\\sec^{2}u\\,du=\\tan u$.", "ht": "$\\int\\sec^{2}u\\,du=\\tan u$", "c": 1, "p": [[0.03, 0.27, 0.4376595001716432], [0.069, 0.183, 0.15382430465563357], [0.12, 0.23099999999999998, 0.2009022783910432]]}]}, {"id": "flog", "u": "B", "n": "The f′/f rule", "nt": "กฎ f′/f", "thm": [{"en": "<b>Theorem.</b> Let $f$ be differentiable on an interval $I$ with $f'$ continuous and $f(x)\\neq0$ for all $x\\in I$. Then <span class=\"mdisp\">$\\displaystyle \\int\\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C\\quad\\text{on }I.$</span>", "th": "<b>ทฤษฎีบท</b> ให้ $f$ หาอนุพันธ์ได้บนช่วง $I$ โดย $f'$ ต่อเนื่องและ $f(x)\\neq0$ ทุก $x\\in I$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int\\frac{f'(x)}{f(x)}\\,dx=\\ln|f(x)|+C\\quad\\text{บน }I$</span>"}, {"en": "Spot it: the top is (a multiple of) the derivative of the bottom.", "th": "วิธีสังเกต: ตัวเศษเป็น (พหุคูณของ) อนุพันธ์ของตัวส่วน"}], "proof": [{"en": "$f$ is continuous and never $0$ on the interval $I$, so by the intermediate value theorem it cannot change sign: either $f&gt;0$ on all of $I$ or $f&lt;0$ on all of $I$.", "th": "$f$ ต่อเนื่องและไม่เป็น $0$ บนช่วง $I$ จากทฤษฎีบทค่าระหว่างกลางจึงเปลี่ยนเครื่องหมายไม่ได้: $f&gt;0$ ทั้งช่วง หรือ $f&lt;0$ ทั้งช่วง", "m": ""}, {"en": "If $f&gt;0$: by the chain rule", "th": "ถ้า $f&gt;0$: จากกฎลูกโซ่", "m": "\\frac{d}{dx}\\ln f(x)=\\frac{f'(x)}{f(x)}."}, {"en": "If $f&lt;0$: $\\ln|f|=\\ln(-f)$ and", "th": "ถ้า $f&lt;0$: $\\ln|f|=\\ln(-f)$ และ", "m": "\\frac{d}{dx}\\ln(-f(x))=\\frac{-f'(x)}{-f(x)}=\\frac{f'(x)}{f(x)}."}, {"en": "In both cases $\\ln|f|$ is an antiderivative; by the lemma of lesson 1 all others differ by a constant. $\\blacksquare$", "th": "ทั้งสองกรณี $\\ln|f|$ เป็นปฏิยานุพันธ์ และจากบทตั้งในบทที่ 1 ตัวอื่นต่างกันเพียงค่าคงตัว $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int\\frac{2x}{x^{2}+1}\\,dx", "al": "\\ln\\left(x^{2}+1\\right)+C", "s": ["f=x^{2}+1,\\ f'=2x", "\\ln\\left(x^{2}+1\\right)+C\\quad(f&gt;0)"]}, {"q": "\\int_{\\frac{\\pi}{6}}^{\\frac{\\pi}{2}}\\cot x\\,dx", "al": "\\ln2", "s": ["\\cot x=\\frac{\\cos x}{\\sin x}=\\frac{f'}{f},\\ f=\\sin x", "\\left[\\ln\\sin x\\right]_{\\frac{\\pi}{6}}^{\\frac{\\pi}{2}}=\\ln1-\\ln\\tfrac12=\\ln2"]}], "pr": [{"q": "\\int_{0}^{1}\\frac{3x^{2}}{x^{3}+1}\\,dx", "al": "\\ln2", "s": ["\\left[\\ln\\left(x^{3}+1\\right)\\right]_{0}^{1}=\\ln2"], "h": "The top is the derivative of the bottom.", "ht": "ตัวเศษเป็นอนุพันธ์ของตัวส่วน", "v": 0.6931471805599453}, {"q": "\\int_{0}^{\\frac{\\pi}{3}}\\frac{\\sin x}{2-\\cos x}\\,dx", "al": "\\ln\\frac32", "s": ["f=2-\\cos x,\\ f'=\\sin x", "\\left[\\ln(2-\\cos x)\\right]_{0}^{\\frac{\\pi}{3}}=\\ln\\tfrac32-\\ln1"], "h": "Differentiate $2-\\cos x$.", "ht": "หาอนุพันธ์ของ $2-\\cos x$", "v": 0.4054651081081644}, {"q": "\\int_{1}^{2}\\frac{2x+1}{x^{2}+x}\\,dx", "al": "\\ln3", "s": ["\\left[\\ln\\left(x^{2}+x\\right)\\right]_{1}^{2}=\\ln6-\\ln2=\\ln3"], "h": "$(x^{2}+x)'=2x+1$.", "ht": "$(x^{2}+x)'=2x+1$", "v": 1.0986122886681098}, {"q": "\\int_{0}^{1}\\frac{x}{x^{2}+3}\\,dx", "al": "\\frac12\\ln\\frac43", "s": ["\\frac{x}{x^{2}+3}=\\frac12\\cdot\\frac{2x}{x^{2}+3}", "\\left[\\tfrac12\\ln\\left(x^{2}+3\\right)\\right]_{0}^{1}=\\tfrac12\\ln\\tfrac43"], "h": "Make the top exactly $2x$ by multiplying and dividing by $2$.", "ht": "ทำตัวเศษให้เป็น $2x$ โดยคูณและหารด้วย $2$", "v": 0.14384103622589045}, {"q": "\\int\\frac{e^{x}}{e^{x}+5}\\,dx", "al": "\\ln\\left(e^{x}+5\\right)+C", "s": ["\\ln\\left(e^{x}+5\\right)+C"], "h": "$(e^{x}+5)'=e^{x}$.", "ht": "$(e^{x}+5)'=e^{x}$", "c": 1, "p": [[0.2, 1.8, 0.5744031186374151], [0.46, 1.22, 0.24205157123340698], [0.8, 1.54, 0.29084661850123406]]}]}, {"id": "fpow", "u": "B", "n": "Reverse chain rule: f′fⁿ and f′e^f", "nt": "กฎลูกโซ่ย้อนกลับ: f′fⁿ และ f′e^f", "thm": [{"en": "<b>Theorem.</b> Let $g$ be continuously differentiable on an interval $I$. Then <span class=\"mdisp\">$\\displaystyle \\int g'(x)\\,e^{g(x)}\\,dx=e^{g(x)}+C,$</span> and for real $n\\neq-1$ (with $g&gt;0$ on $I$ if $n$ is not an integer) <span class=\"mdisp\">$\\displaystyle \\int g'(x)\\,\\big[g(x)\\big]^{n}\\,dx=\\frac{\\big[g(x)\\big]^{n+1}}{n+1}+C.$</span>", "th": "<b>ทฤษฎีบท</b> ให้ $g$ หาอนุพันธ์ได้ต่อเนื่องบนช่วง $I$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int g'(x)\\,e^{g(x)}\\,dx=e^{g(x)}+C$</span> และสำหรับจำนวนจริง $n\\neq-1$ (โดย $g&gt;0$ บน $I$ ถ้า $n$ ไม่ใช่จำนวนเต็ม) <span class=\"mdisp\">$\\displaystyle \\int g'(x)\\,\\big[g(x)\\big]^{n}\\,dx=\\frac{\\big[g(x)\\big]^{n+1}}{n+1}+C$</span>"}], "proof": [{"en": "By the chain rule, on $I$:", "th": "จากกฎลูกโซ่ บน $I$:", "m": "\\frac{d}{dx}e^{g(x)}=e^{g(x)}g'(x),\\qquad \\frac{d}{dx}\\frac{[g(x)]^{n+1}}{n+1}=\\frac{(n+1)[g(x)]^{n}g'(x)}{n+1}=g'(x)[g(x)]^{n}."}, {"en": "The condition $g&gt;0$ makes $[g(x)]^{n}$ defined and differentiable for non-integer $n$. By the lemma of lesson 1 these are all the antiderivatives. $\\blacksquare$", "th": "เงื่อนไข $g&gt;0$ ทำให้ $[g(x)]^{n}$ นิยามและหาอนุพันธ์ได้เมื่อ $n$ ไม่ใช่จำนวนเต็ม และจากบทตั้งในบทที่ 1 นี่คือปฏิยานุพันธ์ทั้งหมด $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int x\\left(x^{2}+1\\right)^{4}dx", "al": "\\frac{\\left(x^{2}+1\\right)^{5}}{10}+C", "s": ["g=x^{2}+1,\\ g'=2x:\\ x=\\tfrac12g'", "\\tfrac12\\cdot\\frac{g^{5}}{5}=\\frac{\\left(x^{2}+1\\right)^{5}}{10}+C"]}, {"q": "\\int2xe^{x^{2}}\\,dx", "al": "e^{x^{2}}+C", "s": ["g=x^{2},\\ g'=2x", "e^{x^{2}}+C"]}], "pr": [{"q": "\\int_{0}^{1}x\\left(x^{2}+1\\right)^{3}dx", "al": "\\frac{15}{8}", "s": ["\\left[\\frac{\\left(x^{2}+1\\right)^{4}}{8}\\right]_{0}^{1}=\\frac{16-1}{8}=\\frac{15}{8}"], "h": "$g=x^{2}+1$, so $x=\\tfrac12g'$.", "ht": "$g=x^{2}+1$ ดังนั้น $x=\\tfrac12g'$", "v": 1.875}, {"q": "\\int_{0}^{\\frac{\\pi}{2}}\\cos x\\sin^{3}x\\,dx", "al": "\\frac14", "s": ["g=\\sin x:\\ \\left[\\tfrac14\\sin^{4}x\\right]_{0}^{\\frac{\\pi}{2}}=\\frac14"], "h": "$g=\\sin x$, $g'=\\cos x$.", "ht": "$g=\\sin x$, $g'=\\cos x$", "v": 0.25}, {"q": "\\int_{0}^{1}xe^{x^{2}}\\,dx", "al": "\\frac{e-1}{2}", "s": ["\\left[\\tfrac12e^{x^{2}}\\right]_{0}^{1}=\\frac{e-1}{2}"], "h": "$g=x^{2}$; you need a factor $\\tfrac12$.", "ht": "$g=x^{2}$ ต้องมีตัวคูณ $\\tfrac12$", "v": 0.8591409142295227}, {"q": "\\int_{0}^{\\frac{\\pi}{2}}\\sin x\\,e^{\\cos x}\\,dx", "al": "e-1", "s": ["g=\\cos x,\\ g'=-\\sin x", "\\left[-e^{\\cos x}\\right]_{0}^{\\frac{\\pi}{2}}=-1+e"], "h": "$g=\\cos x$ and watch the minus sign.", "ht": "$g=\\cos x$ และระวังเครื่องหมายลบ", "v": 1.7182818284590453}, {"q": "\\int_{0}^{1}x^{2}\\sqrt{x^{3}+1}\\,dx", "al": "\\frac29\\left(2\\sqrt2-1\\right)", "s": ["g=x^{3}+1,\\ x^{2}=\\tfrac13g'", "\\left[\\tfrac13\\cdot\\tfrac23\\left(x^{3}+1\\right)^{\\frac32}\\right]_{0}^{1}=\\tfrac29\\left(2^{\\frac32}-1\\right)"], "h": "$n=\\tfrac12$: the answer has $(x^{3}+1)^{3/2}$.", "ht": "$n=\\tfrac12$ คำตอบมี $(x^{3}+1)^{3/2}$", "v": 0.4063171388324867}]}, {"id": "ident", "u": "C", "n": "Using trig identities", "nt": "การใช้เอกลักษณ์ตรีโกณ", "thm": [{"en": "<b>Theorem.</b> For all real $x$, $A$, $B$: <span class=\"mdisp\">$\\displaystyle \\sin^{2}x=\\tfrac12(1-\\cos2x),\\quad \\cos^{2}x=\\tfrac12(1+\\cos2x),\\quad \\tan^{2}x=\\sec^{2}x-1\\ (\\cos x\\neq0),$</span> <span class=\"mdisp\">$\\displaystyle \\sin A\\cos B=\\tfrac12\\big[\\sin(A+B)+\\sin(A-B)\\big],$</span> <span class=\"mdisp\">$\\displaystyle \\cos A\\cos B=\\tfrac12\\big[\\cos(A-B)+\\cos(A+B)\\big],\\quad \\sin A\\sin B=\\tfrac12\\big[\\cos(A-B)-\\cos(A+B)\\big].$</span>", "th": "<b>ทฤษฎีบท</b> สำหรับจำนวนจริง $x$, $A$, $B$ ทุกตัว: <span class=\"mdisp\">$\\displaystyle \\sin^{2}x=\\tfrac12(1-\\cos2x),\\quad \\cos^{2}x=\\tfrac12(1+\\cos2x),\\quad \\tan^{2}x=\\sec^{2}x-1\\ (\\cos x\\neq0),$</span> <span class=\"mdisp\">$\\displaystyle \\sin A\\cos B=\\tfrac12\\big[\\sin(A+B)+\\sin(A-B)\\big],$</span> <span class=\"mdisp\">$\\displaystyle \\cos A\\cos B=\\tfrac12\\big[\\cos(A-B)+\\cos(A+B)\\big],\\quad \\sin A\\sin B=\\tfrac12\\big[\\cos(A-B)-\\cos(A+B)\\big]$</span>"}, {"en": "<b>Corollary.</b> $\\int\\sin^{2}x\\,dx=\\dfrac{x}{2}-\\dfrac{\\sin2x}{4}+C$, and for an integer $k\\ge0$, $\\int\\sin^{2k+1}x\\,dx$ is a polynomial in $\\cos x$ (plus $C$); the same holds with $\\sin$ and $\\cos$ swapped.", "th": "<b>บทแทรก</b> $\\int\\sin^{2}x\\,dx=\\dfrac{x}{2}-\\dfrac{\\sin2x}{4}+C$ และสำหรับจำนวนเต็ม $k\\ge0$ $\\int\\sin^{2k+1}x\\,dx$ เป็นพหุนามใน $\\cos x$ (บวก $C$) และสลับ $\\sin$ กับ $\\cos$ ได้เช่นกัน"}], "proof": [{"en": "Start from the compound-angle formulas (taken as known):", "th": "เริ่มจากสูตรมุมประกอบ (ถือว่าทราบแล้ว):", "m": "\\cos(A\\pm B)=\\cos A\\cos B\\mp\\sin A\\sin B,\\qquad \\sin(A\\pm B)=\\sin A\\cos B\\pm\\cos A\\sin B."}, {"en": "Put $A=B=x$ in the cosine formula and use $\\sin^{2}x+\\cos^{2}x=1$:", "th": "แทน $A=B=x$ ในสูตร cos และใช้ $\\sin^{2}x+\\cos^{2}x=1$:", "m": "\\cos2x=\\cos^{2}x-\\sin^{2}x=1-2\\sin^{2}x=2\\cos^{2}x-1,"}, {"en": "which rearranges to the first two identities. Dividing $\\sin^{2}x+\\cos^{2}x=1$ by $\\cos^{2}x\\neq0$ gives $\\tan^{2}x+1=\\sec^{2}x$.", "th": "จัดรูปได้สองเอกลักษณ์แรก หาร $\\sin^{2}x+\\cos^{2}x=1$ ด้วย $\\cos^{2}x\\neq0$ ได้ $\\tan^{2}x+1=\\sec^{2}x$", "m": ""}, {"en": "Adding $\\sin(A+B)$ and $\\sin(A-B)$ cancels the $\\cos A\\sin B$ terms; adding or subtracting the two cosine formulas gives the other two:", "th": "บวก $\\sin(A+B)$ กับ $\\sin(A-B)$ พจน์ $\\cos A\\sin B$ หักล้างกัน และบวกหรือลบสูตร cos สองสูตรได้อีกสองเอกลักษณ์:", "m": "\\sin(A+B)+\\sin(A-B)=2\\sin A\\cos B."}, {"en": "Corollary: integrate $\\tfrac12-\\tfrac12\\cos2x$ using lesson 5. For odd powers write", "th": "บทแทรก: อินทิเกรต $\\tfrac12-\\tfrac12\\cos2x$ ด้วยบทที่ 5 สำหรับกำลังคี่เขียน", "m": "\\sin^{2k+1}x=\\left(1-\\cos^{2}x\\right)^{k}\\sin x=\\sum_{j=0}^{k}\\binom{k}{j}(-1)^{j}\\cos^{2j}x\\,\\sin x,"}, {"en": "and each term integrates by lesson 7 (with $g=\\cos x$, $g'=-\\sin x$):", "th": "และแต่ละพจน์อินทิเกรตด้วยบทที่ 7 (ให้ $g=\\cos x$, $g'=-\\sin x$):", "m": "\\int\\cos^{2j}x\\sin x\\,dx=-\\frac{\\cos^{2j+1}x}{2j+1}+C.\\ \\blacksquare"}], "ex": [{"q": "\\int_{0}^{\\pi}\\cos^{2}x\\,dx", "al": "\\frac{\\pi}{2}", "s": ["\\cos^{2}x=\\tfrac12(1+\\cos2x)", "\\left[\\tfrac{x}{2}+\\tfrac{\\sin2x}{4}\\right]_{0}^{\\pi}=\\frac{\\pi}{2}"]}, {"q": "\\int\\sin^{3}x\\,dx", "al": "-\\cos x+\\frac{\\cos^{3}x}{3}+C", "s": ["\\sin^{3}x=\\left(1-\\cos^{2}x\\right)\\sin x", "=-\\cos x+\\frac{\\cos^{3}x}{3}+C"]}], "pr": [{"q": "\\int_{0}^{\\frac{\\pi}{4}}\\cos^{2}x\\,dx", "al": "\\frac{\\pi}{8}+\\frac14", "s": ["\\left[\\tfrac{x}{2}+\\tfrac{\\sin2x}{4}\\right]_{0}^{\\frac{\\pi}{4}}=\\frac{\\pi}{8}+\\frac14"], "h": "Use $\\cos^{2}x=\\tfrac12(1+\\cos2x)$.", "ht": "ใช้ $\\cos^{2}x=\\tfrac12(1+\\cos2x)$", "v": 0.6426990816987241}, {"q": "\\int_{0}^{\\frac{\\pi}{2}}\\sin3x\\cos x\\,dx", "al": "\\frac12", "s": ["\\sin3x\\cos x=\\tfrac12\\left(\\sin4x+\\sin2x\\right)", "\\tfrac12\\left[-\\tfrac{\\cos4x}{4}-\\tfrac{\\cos2x}{2}\\right]_{0}^{\\frac{\\pi}{2}}=\\tfrac12\\left(0+1\\right)=\\frac12"], "h": "Product to sum: $\\sin A\\cos B$.", "ht": "ผลคูณเป็นผลบวก: $\\sin A\\cos B$", "v": 0.5}, {"q": "\\int_{0}^{\\frac{\\pi}{2}}\\cos^{3}x\\,dx", "al": "\\frac23", "s": ["\\cos^{3}x=\\left(1-\\sin^{2}x\\right)\\cos x", "\\left[\\sin x-\\tfrac{\\sin^{3}x}{3}\\right]_{0}^{\\frac{\\pi}{2}}=\\frac23"], "h": "Odd power: keep one $\\cos x$.", "ht": "กำลังคี่: เก็บ $\\cos x$ ไว้หนึ่งตัว", "v": 0.6666666666666666}, {"q": "\\int_{0}^{\\frac{\\pi}{3}}\\tan^{2}x\\,dx", "al": "\\sqrt3-\\frac{\\pi}{3}", "s": ["\\tan^{2}x=\\sec^{2}x-1", "\\left[\\tan x-x\\right]_{0}^{\\frac{\\pi}{3}}=\\sqrt3-\\frac{\\pi}{3}"], "h": "$\\tan^{2}x=\\sec^{2}x-1$.", "ht": "$\\tan^{2}x=\\sec^{2}x-1$", "v": 0.6848532563722796}, {"q": "\\int\\sin^{2}x\\cos^{2}x\\,dx", "al": "\\frac{x}{8}-\\frac{\\sin4x}{32}+C", "s": ["\\sin^{2}x\\cos^{2}x=\\tfrac14\\sin^{2}2x=\\tfrac18(1-\\cos4x)", "\\frac{x}{8}-\\frac{\\sin4x}{32}+C"], "h": "$\\sin x\\cos x=\\tfrac12\\sin2x$.", "ht": "$\\sin x\\cos x=\\tfrac12\\sin2x$", "c": 1, "p": [[0.24000000000000002, 1.36, 0.18893615566152533], [0.42200000000000004, 0.954, 0.11704918832816263], [0.66, 1.178, 0.11102570435424311]]}]}, {"id": "sub", "u": "C", "n": "Integration by substitution", "nt": "การอินทิเกรตโดยการแทนค่า", "thm": [{"en": "<b>Theorem (substitution).</b> Let $g:[a,b]\\to\\mathbb{R}$ be continuously differentiable, and $f$ continuous on an interval $J$ containing $g([a,b])$. Then <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f\\big(g(x)\\big)\\,g'(x)\\,dx=\\int_{g(a)}^{g(b)}f(u)\\,du.$</span>", "th": "<b>ทฤษฎีบท (การแทนค่า)</b> ให้ $g:[a,b]\\to\\mathbb{R}$ หาอนุพันธ์ได้ต่อเนื่อง และ $f$ ต่อเนื่องบนช่วง $J$ ที่มี $g([a,b])$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f\\big(g(x)\\big)\\,g'(x)\\,dx=\\int_{g(a)}^{g(b)}f(u)\\,du$</span>"}, {"en": "Read right to left it is the <b>inverse substitution</b> $x=\\varphi(t)$: $\\int_{\\varphi(\\alpha)}^{\\varphi(\\beta)}f(x)\\,dx=\\int_{\\alpha}^{\\beta}f(\\varphi(t))\\varphi'(t)\\,dt$. Note that $g$ need not be one-to-one.", "th": "อ่านจากขวาไปซ้ายคือ <b>การแทนค่าผกผัน</b> $x=\\varphi(t)$: $\\int_{\\varphi(\\alpha)}^{\\varphi(\\beta)}f(x)\\,dx=\\int_{\\alpha}^{\\beta}f(\\varphi(t))\\varphi'(t)\\,dt$ สังเกตว่า $g$ ไม่จำเป็นต้องเป็นหนึ่งต่อหนึ่ง"}], "proof": [{"en": "$f$ is continuous on the interval $J$, so by FTC (1) (lesson 4) it has an antiderivative $F$ on $J$, e.g. $F(u)=\\int_{c}^{u}f$ for a fixed $c\\in J$.", "th": "$f$ ต่อเนื่องบนช่วง $J$ จาก FTC (1) (บทที่ 4) จึงมีปฏิยานุพันธ์ $F$ บน $J$ เช่น $F(u)=\\int_{c}^{u}f$ สำหรับ $c\\in J$ คงที่", "m": ""}, {"en": "By the chain rule, for $x\\in[a,b]$,", "th": "จากกฎลูกโซ่ สำหรับ $x\\in[a,b]$", "m": "\\frac{d}{dx}F\\big(g(x)\\big)=f\\big(g(x)\\big)\\,g'(x),"}, {"en": "which is continuous (a product of continuous functions). So by FTC (2), applied once on each side:", "th": "ซึ่งต่อเนื่อง (ผลคูณของฟังก์ชันต่อเนื่อง) ดังนั้นใช้ FTC (2) ทั้งสองข้าง:", "m": "\\int_{a}^{b}f(g(x))g'(x)\\,dx=F(g(b))-F(g(a))=\\int_{g(a)}^{g(b)}f(u)\\,du.\\ \\blacksquare"}], "ex": [{"q": "\\int_{1}^{2}x(x-1)^{5}\\,dx", "al": "\\frac{13}{42}", "s": ["u=x-1,\\ du=dx,\\ x=u+1;\\ x:1\\to2\\Rightarrow u:0\\to1", "\\int_{0}^{1}(u+1)u^{5}\\,du=\\frac17+\\frac16=\\frac{13}{42}"]}, {"q": "\\int_{0}^{3}\\frac{x}{\\sqrt{x+1}}\\,dx", "al": "\\frac83", "s": ["u=x+1:\\ \\int_{1}^{4}\\frac{u-1}{\\sqrt u}\\,du", "=\\left[\\tfrac23u^{\\frac32}-2u^{\\frac12}\\right]_{1}^{4}=\\left(\\tfrac{16}{3}-4\\right)-\\left(\\tfrac23-2\\right)=\\frac83"]}], "pr": [{"q": "\\int_{0}^{1}x(1-x)^{4}\\,dx", "al": "\\frac{1}{30}", "s": ["u=1-x:\\ \\int_{0}^{1}(1-u)u^{4}\\,du", "=\\frac15-\\frac16=\\frac{1}{30}"], "h": "Let $u=1-x$; the limits swap and $du=-dx$.", "ht": "ให้ $u=1-x$ ขอบเขตสลับกันและ $du=-dx$", "v": 0.03333333333333333}, {"q": "\\int_{0}^{4}x\\sqrt{2x+1}\\,dx", "al": "\\frac{298}{15}", "s": ["u=2x+1,\\ x=\\tfrac{u-1}{2},\\ dx=\\tfrac{du}{2}", "\\tfrac14\\int_{1}^{9}\\left(u^{\\frac32}-u^{\\frac12}\\right)du=\\tfrac14\\left[\\tfrac25u^{\\frac52}-\\tfrac23u^{\\frac32}\\right]_{1}^{9}", "=\\tfrac14\\left(\\tfrac{396}{5}+\\tfrac{4}{15}\\right)=\\frac{298}{15}"], "h": "Let $u=2x+1$ and change the limits to $1$ and $9$.", "ht": "ให้ $u=2x+1$ และเปลี่ยนขอบเขตเป็น $1$ และ $9$", "v": 19.866666666666667}, {"q": "\\int_{1}^{e}\\frac{(\\ln x)^{2}}{x}\\,dx", "al": "\\frac13", "s": ["u=\\ln x,\\ du=\\tfrac{dx}{x}", "\\int_{0}^{1}u^{2}\\,du=\\frac13"], "h": "Let $u=\\ln x$.", "ht": "ให้ $u=\\ln x$", "v": 0.3333333333333333}, {"q": "\\int_{0}^{1}\\frac{1}{1+\\sqrt x}\\,dx", "al": "2-2\\ln2", "s": ["x=u^{2},\\ dx=2u\\,du", "\\int_{0}^{1}\\frac{2u}{1+u}\\,du=2\\left[u-\\ln(1+u)\\right]_{0}^{1}=2-2\\ln2"], "h": "Let $x=u^{2}$ (inverse substitution) to remove the root.", "ht": "ให้ $x=u^{2}$ (แทนค่าผกผัน) เพื่อกำจัดราก", "v": 0.6137056388801094}, {"q": "\\int_{2}^{5}\\frac{x}{\\sqrt{x-1}}\\,dx", "al": "\\frac{20}{3}", "s": ["u=x-1:\\ \\int_{1}^{4}\\frac{u+1}{\\sqrt u}\\,du", "=\\left[\\tfrac23u^{\\frac32}+2u^{\\frac12}\\right]_{1}^{4}=\\left(\\tfrac{16}{3}+4\\right)-\\left(\\tfrac23+2\\right)=\\frac{20}{3}"], "h": "Let $u=x-1$, so $x=u+1$.", "ht": "ให้ $u=x-1$ ดังนั้น $x=u+1$", "v": 6.666666666666667}]}, {"id": "parts", "u": "C", "n": "Integration by parts", "nt": "การอินทิเกรตทีละส่วน", "thm": [{"en": "<b>Theorem (integration by parts).</b> Let $u$ and $v$ be continuously differentiable on $[a,b]$. Then <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}u\\,v'\\,dx=\\Big[uv\\Big]_{a}^{b}-\\int_{a}^{b}u'\\,v\\,dx,$</span> and on any interval $\\int uv'\\,dx=uv-\\int u'v\\,dx$.", "th": "<b>ทฤษฎีบท (การอินทิเกรตทีละส่วน)</b> ให้ $u$ และ $v$ หาอนุพันธ์ได้ต่อเนื่องบน $[a,b]$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}u\\,v'\\,dx=\\Big[uv\\Big]_{a}^{b}-\\int_{a}^{b}u'\\,v\\,dx$</span> และบนช่วงใด ๆ $\\int uv'\\,dx=uv-\\int u'v\\,dx$"}, {"en": "Choosing $u$: take the factor that gets simpler when differentiated (L-I-A-T-E: logs, inverse trig, algebraic, trig, exponential). <b>Cyclic case:</b> if parts twice gives $I=A-kI$ with $k\\neq-1$, then $I=\\dfrac{A}{1+k}$.", "th": "การเลือก $u$: เลือกตัวที่ง่ายขึ้นเมื่อหาอนุพันธ์ (L-I-A-T-E: ลอการิทึม, ตรีโกณผกผัน, พีชคณิต, ตรีโกณ, เลขชี้กำลัง) <b>กรณีวนกลับ:</b> ถ้าทำสองครั้งแล้วได้ $I=A-kI$ โดย $k\\neq-1$ จะได้ $I=\\dfrac{A}{1+k}$"}], "proof": [{"en": "By the product rule,", "th": "จากกฎผลคูณ", "m": "(uv)'=u'v+uv',"}, {"en": "and both $u'v$ and $uv'$ are continuous on $[a,b]$, so they are integrable and FTC (2) applies to $uv$:", "th": "และ $u'v$, $uv'$ ต่อเนื่องบน $[a,b]$ จึงอินทิเกรตได้ และใช้ FTC (2) กับ $uv$ ได้:", "m": "\\Big[uv\\Big]_{a}^{b}=\\int_{a}^{b}(uv)'\\,dx=\\int_{a}^{b}u'v\\,dx+\\int_{a}^{b}uv'\\,dx."}, {"en": "Rearrange (linearity). The indefinite form is the same identity for antiderivatives. For the cyclic case, $I=A-kI$ gives $(1+k)I=A$ and we divide because $1+k\\neq0$. $\\blacksquare$", "th": "จัดรูป (ความเป็นเชิงเส้น) รูปไม่จำกัดเขตคือเอกลักษณ์เดียวกันสำหรับปฏิยานุพันธ์ กรณีวนกลับ $I=A-kI$ ให้ $(1+k)I=A$ และหารได้เพราะ $1+k\\neq0$ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int x\\cos x\\,dx", "al": "x\\sin x+\\cos x+C", "s": ["u=x,\\ v'=\\cos x:\\ u'=1,\\ v=\\sin x", "x\\sin x-\\int\\sin x\\,dx=x\\sin x+\\cos x+C"]}, {"q": "\\int e^{x}\\sin x\\,dx", "al": "\\frac{e^{x}(\\sin x-\\cos x)}{2}+C", "s": ["I=e^{x}\\sin x-\\int e^{x}\\cos x\\,dx", "=e^{x}\\sin x-\\left(e^{x}\\cos x+\\int e^{x}\\sin x\\,dx\\right)", "I=e^{x}(\\sin x-\\cos x)-I\\Rightarrow I=\\frac{e^{x}(\\sin x-\\cos x)}{2}+C"]}], "pr": [{"q": "\\int_{0}^{1}xe^{2x}\\,dx", "al": "\\frac{e^{2}+1}{4}", "s": ["u=x,\\ v=\\tfrac12e^{2x}", "\\left[\\tfrac{x}{2}e^{2x}-\\tfrac14e^{2x}\\right]_{0}^{1}=\\frac{e^{2}}{4}+\\frac14"], "h": "$u=x$, $v'=e^{2x}$.", "ht": "$u=x$, $v'=e^{2x}$", "v": 2.0972640247326626}, {"q": "\\int_{1}^{e}x^{2}\\ln x\\,dx", "al": "\\frac{2e^{3}+1}{9}", "s": ["u=\\ln x,\\ v=\\tfrac{x^{3}}{3}", "\\left[\\tfrac{x^{3}}{3}\\ln x-\\tfrac{x^{3}}{9}\\right]_{1}^{e}=\\frac{e^{3}}{3}-\\frac{e^{3}}{9}+\\frac19"], "h": "Logs first: $u=\\ln x$.", "ht": "เลือกลอการิทึมเป็น $u=\\ln x$", "v": 4.5745637607083705}, {"q": "\\int_{0}^{\\frac{\\pi}{2}}x\\cos x\\,dx", "al": "\\frac{\\pi}{2}-1", "s": ["\\left[x\\sin x+\\cos x\\right]_{0}^{\\frac{\\pi}{2}}=\\frac{\\pi}{2}-1"], "h": "Same as the first example.", "ht": "เหมือนตัวอย่างแรก", "v": 0.5707963267948967}, {"q": "\\int_{0}^{1}x^{2}e^{x}\\,dx", "al": "e-2", "s": ["\\text{Parts twice: }\\int x^{2}e^{x}dx=e^{x}\\left(x^{2}-2x+2\\right)", "\\left[e^{x}\\left(x^{2}-2x+2\\right)\\right]_{0}^{1}=e-2"], "h": "Use parts twice with $u=x^{2}$, then $u=x$.", "ht": "ทำสองครั้ง: $u=x^{2}$ แล้ว $u=x$", "v": 0.7182818284590452}, {"q": "\\int_{0}^{\\frac{\\pi}{2}}e^{x}\\cos x\\,dx", "al": "\\frac{e^{\\frac{\\pi}{2}}-1}{2}", "s": ["\\text{Cyclic: }\\int e^{x}\\cos x\\,dx=\\frac{e^{x}(\\sin x+\\cos x)}{2}", "\\frac{e^{\\frac{\\pi}{2}}(1+0)-(0+1)}{2}"], "h": "Cyclic: parts twice, then solve for $I$.", "ht": "วนกลับ: ทำสองครั้งแล้วแก้หา $I$", "v": 1.905238690482676}]}, {"id": "pf", "u": "C", "n": "Partial fractions", "nt": "เศษส่วนย่อย", "thm": [{"en": "<b>Theorem.</b> Let $P$, $Q$ be real polynomials with $\\deg P&lt;\\deg Q$ and <span class=\"mdisp\">$\\displaystyle Q(x)=c\\prod_{i}(x-a_i)^{m_i}\\prod_{j}\\left(x^{2}+b_jx+c_j\\right)^{n_j},$</span> with distinct $a_i$ and distinct irreducible quadratics ($b_j^{2}&lt;4c_j$). Then there are unique real constants with <span class=\"mdisp\">$\\displaystyle \\frac{P}{Q}=\\sum_{i}\\sum_{k=1}^{m_i}\\frac{A_{ik}}{(x-a_i)^{k}}+\\sum_{j}\\sum_{k=1}^{n_j}\\frac{B_{jk}x+C_{jk}}{\\left(x^{2}+b_jx+c_j\\right)^{k}}.$</span>", "th": "<b>ทฤษฎีบท</b> ให้ $P$, $Q$ เป็นพหุนามจริงที่ $\\deg P&lt;\\deg Q$ และ <span class=\"mdisp\">$\\displaystyle Q(x)=c\\prod_{i}(x-a_i)^{m_i}\\prod_{j}\\left(x^{2}+b_jx+c_j\\right)^{n_j}$</span> โดย $a_i$ ต่างกันและพหุนามกำลังสองลดทอนไม่ได้ต่างกัน ($b_j^{2}&lt;4c_j$) แล้วมีค่าคงตัวจริงเพียงชุดเดียวที่ <span class=\"mdisp\">$\\displaystyle \\frac{P}{Q}=\\sum_{i}\\sum_{k=1}^{m_i}\\frac{A_{ik}}{(x-a_i)^{k}}+\\sum_{j}\\sum_{k=1}^{n_j}\\frac{B_{jk}x+C_{jk}}{\\left(x^{2}+b_jx+c_j\\right)^{k}}$</span>"}, {"en": "If $\\deg P\\ge\\deg Q$, divide first: $P=SQ+R$ with $\\deg R&lt;\\deg Q$, so $\\dfrac PQ=S+\\dfrac RQ$.", "th": "ถ้า $\\deg P\\ge\\deg Q$ ให้หารก่อน: $P=SQ+R$ โดย $\\deg R&lt;\\deg Q$ ดังนั้น $\\dfrac PQ=S+\\dfrac RQ$"}], "proof": [{"en": "<b>Lemma (Bézout).</b> If polynomials $Q_1$, $Q_2$ have no common non-constant factor, the Euclidean algorithm gives polynomials $s$, $t$ with", "th": "<b>บทตั้ง (Bézout)</b> ถ้าพหุนาม $Q_1$, $Q_2$ ไม่มีตัวประกอบร่วมที่ไม่ใช่ค่าคงตัว ขั้นตอนวิธีแบบยุคลิดให้พหุนาม $s$, $t$ ที่", "m": "s\\,Q_1+t\\,Q_2=1."}, {"en": "<b>Splitting.</b> Then $\\dfrac{P}{Q_1Q_2}=\\dfrac{P(sQ_1+tQ_2)}{Q_1Q_2}=\\dfrac{Pt}{Q_1}+\\dfrac{Ps}{Q_2}$. Divide: $Pt=\\alpha Q_1+A$, $Ps=\\beta Q_2+B$ with $\\deg A&lt;\\deg Q_1$, $\\deg B&lt;\\deg Q_2$:", "th": "<b>การแยก</b> จะได้ $\\dfrac{P}{Q_1Q_2}=\\dfrac{P(sQ_1+tQ_2)}{Q_1Q_2}=\\dfrac{Pt}{Q_1}+\\dfrac{Ps}{Q_2}$ หาร: $Pt=\\alpha Q_1+A$, $Ps=\\beta Q_2+B$ โดย $\\deg A&lt;\\deg Q_1$, $\\deg B&lt;\\deg Q_2$:", "m": "\\frac{P}{Q_1Q_2}=\\frac{A}{Q_1}+\\frac{B}{Q_2}+(\\alpha+\\beta)."}, {"en": "As $x\\to\\infty$ every fraction here tends to $0$ (degree of top less than bottom), so the polynomial $\\alpha+\\beta$ tends to $0$, hence is the zero polynomial.", "th": "เมื่อ $x\\to\\infty$ ทุกเศษส่วนในที่นี้เข้าใกล้ $0$ (ดีกรีตัวเศษน้อยกว่าตัวส่วน) ดังนั้นพหุนาม $\\alpha+\\beta$ เข้าใกล้ $0$ จึงเป็นพหุนามศูนย์", "m": ""}, {"en": "<b>Repeat</b> this on the distinct prime-power factors $(x-a_i)^{m_i}$ and $(x^{2}+b_jx+c_j)^{n_j}$, which are pairwise coprime.", "th": "<b>ทำซ้ำ</b> กับตัวประกอบกำลังเฉพาะ $(x-a_i)^{m_i}$ และ $(x^{2}+b_jx+c_j)^{n_j}$ ที่เป็นจำนวนเฉพาะสัมพัทธ์กันทีละคู่", "m": ""}, {"en": "<b>One prime power.</b> For $\\dfrac{A}{(x-a)^{m}}$ with $\\deg A&lt;m$, expand $A$ in powers of $x-a$ (Taylor's formula for polynomials):", "th": "<b>กำลังเฉพาะตัวเดียว</b> สำหรับ $\\dfrac{A}{(x-a)^{m}}$ ที่ $\\deg A&lt;m$ กระจาย $A$ ในกำลังของ $x-a$ (สูตรเทย์เลอร์ของพหุนาม):", "m": "A(x)=\\sum_{k=0}^{m-1}d_k(x-a)^{k}\\ \\Rightarrow\\ \\frac{A}{(x-a)^{m}}=\\sum_{k=0}^{m-1}\\frac{d_k}{(x-a)^{m-k}}."}, {"en": "For a quadratic power, divide $A$ repeatedly by $q=x^{2}+bx+c$: $A=\\sum_k r_k q^{k}$ with each $\\deg r_k\\le1$, giving terms $\\dfrac{r_k}{q^{n-k}}$.", "th": "สำหรับกำลังของพหุนามกำลังสอง หาร $A$ ด้วย $q=x^{2}+bx+c$ ซ้ำ ๆ: $A=\\sum_k r_k q^{k}$ โดย $\\deg r_k\\le1$ ได้พจน์ $\\dfrac{r_k}{q^{n-k}}$", "m": ""}, {"en": "<b>Uniqueness.</b> The difference of two decompositions is a decomposition of $0$. Multiply by $(x-a_i)^{m_i}$ and let $x\\to a_i$: the top coefficient $A_{im_i}$ must be $0$; repeat downwards. For a quadratic factor do the same at one of its complex roots $z$ (with $B,C$ real, $Bz+C=0$ forces $B=C=0$ since $z\\notin\\mathbb{R}$). $\\blacksquare$", "th": "<b>ความเป็นหนึ่งเดียว</b> ผลต่างของการแยกสองแบบคือการแยกของ $0$ คูณด้วย $(x-a_i)^{m_i}$ แล้วให้ $x\\to a_i$: สัมประสิทธิ์บนสุด $A_{im_i}$ ต้องเป็น $0$ ทำซ้ำลงมา สำหรับตัวประกอบกำลังสองทำเช่นเดียวกันที่รากเชิงซ้อน $z$ ตัวหนึ่ง ($B,C$ จริงและ $Bz+C=0$ บังคับให้ $B=C=0$ เพราะ $z\\notin\\mathbb{R}$) $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int\\frac{5x+1}{(x-1)(x+2)}\\,dx", "al": "2\\ln|x-1|+3\\ln|x+2|+C", "s": ["\\frac{5x+1}{(x-1)(x+2)}=\\frac{A}{x-1}+\\frac{B}{x+2}", "x=1:\\ A=\\tfrac63=2;\\quad x=-2:\\ B=\\tfrac{-9}{-3}=3", "2\\ln|x-1|+3\\ln|x+2|+C"]}, {"q": "\\int_{1}^{2}\\frac{1}{x^{2}(x+1)}\\,dx", "al": "\\ln\\frac34+\\frac12", "s": ["\\frac{1}{x^{2}(x+1)}=-\\frac1x+\\frac{1}{x^{2}}+\\frac{1}{x+1}", "\\left[-\\ln x-\\tfrac1x+\\ln(x+1)\\right]_{1}^{2}=\\ln3-2\\ln2+\\frac12"]}], "pr": [{"q": "\\int_{0}^{1}\\frac{1}{(x+1)(x+2)}\\,dx", "al": "\\ln\\frac43", "s": ["\\frac{1}{x+1}-\\frac{1}{x+2}", "\\left[\\ln\\frac{x+1}{x+2}\\right]_{0}^{1}=\\ln\\tfrac23-\\ln\\tfrac12=\\ln\\frac43"], "h": "Cover-up: put $x=-1$, then $x=-2$.", "ht": "ปิดตัวประกอบ: แทน $x=-1$ แล้ว $x=-2$", "v": 0.2876820724517809}, {"q": "\\int_{2}^{4}\\frac{x+5}{x^{2}-1}\\,dx", "al": "\\ln\\frac{243}{25}", "s": ["\\frac{x+5}{(x-1)(x+1)}=\\frac{3}{x-1}-\\frac{2}{x+1}", "\\left[3\\ln(x-1)-2\\ln(x+1)\\right]_{2}^{4}=3\\ln3-2\\ln\\tfrac53=\\ln\\frac{243}{25}"], "h": "Factorise $x^{2}-1$ first.", "ht": "แยกตัวประกอบ $x^{2}-1$ ก่อน", "v": 2.2741856184723477}, {"q": "\\int_{1}^{2}\\frac{x^{2}+1}{x(x+1)}\\,dx", "al": "1+\\ln\\frac89", "s": ["\\frac{x^{2}+1}{x^{2}+x}=1+\\frac{1-x}{x(x+1)}=1+\\frac1x-\\frac{2}{x+1}", "\\left[x+\\ln x-2\\ln(x+1)\\right]_{1}^{2}=1+\\ln2-2\\ln\\tfrac32=1+\\ln\\frac89"], "h": "Improper: divide first.", "ht": "เศษเกิน: หารก่อน", "v": 0.8822169643436165}, {"q": "\\int_{0}^{1}\\frac{x}{(x+1)^{2}}\\,dx", "al": "\\ln2-\\frac12", "s": ["\\frac{x}{(x+1)^{2}}=\\frac{1}{x+1}-\\frac{1}{(x+1)^{2}}", "\\left[\\ln(x+1)+\\tfrac{1}{x+1}\\right]_{0}^{1}=\\ln2+\\tfrac12-1"], "h": "Repeated factor: $\\frac{A}{x+1}+\\frac{B}{(x+1)^{2}}$.", "ht": "ตัวประกอบซ้ำ: $\\frac{A}{x+1}+\\frac{B}{(x+1)^{2}}$", "v": 0.19314718055994531}, {"q": "\\int\\frac{3x+5}{(x+1)(x+3)}\\,dx", "al": "\\ln|x+1|+2\\ln|x+3|+C", "s": ["x=-1:\\ A=\\tfrac22=1;\\quad x=-3:\\ B=\\tfrac{-4}{-2}=2", "\\ln|x+1|+2\\ln|x+3|+C"], "h": "Cover-up at $x=-1$ and $x=-3$.", "ht": "ปิดตัวประกอบที่ $x=-1$ และ $x=-3$", "c": 1, "p": [[0.2, 1.8, 1.6582280766035324], [0.46, 1.22, 0.816203838120518], [0.8, 1.54, 0.7002293067701593]]}]}, {"id": "trap", "u": "C", "n": "The trapezium rule and its error", "nt": "กฎสี่เหลี่ยมคางหมูและความคลาดเคลื่อน", "thm": [{"en": "<b>Theorem.</b> Let $f$ be twice continuously differentiable on $[a,b]$, $h=\\frac{b-a}{n}$, $x_i=a+ih$, and <span class=\"mdisp\">$\\displaystyle T_n=\\frac h2\\Big[f(x_0)+2\\big(f(x_1)+\\dots+f(x_{n-1})\\big)+f(x_n)\\Big].$</span> Then for some $\\xi\\in(a,b)$, <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f(x)\\,dx=T_n-\\frac{(b-a)h^{2}}{12}f''(\\xi).$</span>", "th": "<b>ทฤษฎีบท</b> ให้ $f$ หาอนุพันธ์อันดับสองได้ต่อเนื่องบน $[a,b]$, $h=\\frac{b-a}{n}$, $x_i=a+ih$ และ <span class=\"mdisp\">$\\displaystyle T_n=\\frac h2\\Big[f(x_0)+2\\big(f(x_1)+\\dots+f(x_{n-1})\\big)+f(x_n)\\Big]$</span> แล้วมี $\\xi\\in(a,b)$ ที่ <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f(x)\\,dx=T_n-\\frac{(b-a)h^{2}}{12}f''(\\xi)$</span>"}, {"en": "So if $f''&gt;0$ (convex) the rule <b>overestimates</b>, and $|\\text{error}|\\le\\dfrac{(b-a)h^{2}}{12}\\max|f''|$.", "th": "ดังนั้นถ้า $f''&gt;0$ (เว้าขึ้น) กฎนี้ให้ค่า<b>เกิน</b> และ $|\\text{error}|\\le\\dfrac{(b-a)h^{2}}{12}\\max|f''|$"}], "proof": [{"en": "One strip, moved to $[0,h]$: let $g$ be $C^{2}$ on $[0,h]$ and $K(x)=\\tfrac12x(x-h)$, so $K(0)=K(h)=0$, $K'=x-\\tfrac h2$, $K''=1$. Integrate by parts twice:", "th": "แถบเดียว เลื่อนไปที่ $[0,h]$: ให้ $g$ เป็น $C^{2}$ บน $[0,h]$ และ $K(x)=\\tfrac12x(x-h)$ จะได้ $K(0)=K(h)=0$, $K'=x-\\tfrac h2$, $K''=1$ อินทิเกรตทีละส่วนสองครั้ง:", "m": "\\int_{0}^{h}Kg''\\,dx=\\Big[Kg'\\Big]_{0}^{h}-\\int_{0}^{h}\\left(x-\\tfrac h2\\right)g'\\,dx=-\\Big[\\left(x-\\tfrac h2\\right)g\\Big]_{0}^{h}+\\int_{0}^{h}g\\,dx."}, {"en": "The bracket equals $\\tfrac h2\\big(g(0)+g(h)\\big)$, so", "th": "วงเล็บเท่ากับ $\\tfrac h2\\big(g(0)+g(h)\\big)$ ดังนั้น", "m": "\\int_{0}^{h}g\\,dx=\\frac h2\\big(g(0)+g(h)\\big)+\\int_{0}^{h}K(x)g''(x)\\,dx."}, {"en": "$K\\le0$ on $[0,h]$ and $g''$ is continuous, so the weighted mean value theorem for integrals (proved like lesson 4, using $m\\,K\\ge Kg''\\ge M\\,K$) gives $\\eta\\in[0,h]$ with", "th": "$K\\le0$ บน $[0,h]$ และ $g''$ ต่อเนื่อง ทฤษฎีบทค่าเฉลี่ยถ่วงน้ำหนักสำหรับอินทิกรัล (พิสูจน์แบบบทที่ 4 โดยใช้ $m\\,K\\ge Kg''\\ge M\\,K$) ให้ $\\eta\\in[0,h]$ ที่", "m": "\\int_{0}^{h}Kg''\\,dx=g''(\\eta)\\int_{0}^{h}\\tfrac12x(x-h)\\,dx=-\\frac{h^{3}}{12}g''(\\eta)."}, {"en": "Add over the $n$ strips:", "th": "รวมทั้ง $n$ แถบ:", "m": "\\int_{a}^{b}f=T_n-\\frac{h^{3}}{12}\\sum_{i=1}^{n}f''(\\eta_i)=T_n-\\frac{nh^{3}}{12}\\cdot\\frac1n\\sum_{i=1}^{n}f''(\\eta_i)."}, {"en": "The average $\\frac1n\\sum f''(\\eta_i)$ lies between $\\min f''$ and $\\max f''$, so by the intermediate value theorem it equals $f''(\\xi)$ for some $\\xi$. Finally $nh^{3}=(b-a)h^{2}$. $\\blacksquare$", "th": "ค่าเฉลี่ย $\\frac1n\\sum f''(\\eta_i)$ อยู่ระหว่าง $\\min f''$ และ $\\max f''$ จากทฤษฎีบทค่าระหว่างกลางจึงเท่ากับ $f''(\\xi)$ สำหรับบาง $\\xi$ และ $nh^{3}=(b-a)h^{2}$ $\\blacksquare$", "m": ""}], "ex": [{"q": "T_2\\text{ for }\\int_{0}^{1}x^{2}\\,dx", "al": "\\frac38", "s": ["h=\\tfrac12:\\ T_2=\\tfrac14\\left[0+2\\cdot\\tfrac14+1\\right]=\\frac38", "\\text{Error: }-\\tfrac{1\\cdot\\frac14}{12}\\cdot2=-\\tfrac{1}{24},\\ \\text{and }\\tfrac38-\\tfrac1{24}=\\tfrac13\\ \\checkmark"]}, {"q": "T_4\\text{ for }\\int_{0}^{1}x^{2}\\,dx", "al": "\\frac{11}{32}", "s": ["h=\\tfrac14:\\ \\tfrac18\\left[0+2\\left(\\tfrac1{16}+\\tfrac14+\\tfrac9{16}\\right)+1\\right]=\\frac{11}{32}", "\\text{Overestimate by }\\tfrac{1}{96}\\text{ since }f''=2&gt;0"]}], "pr": [{"q": "\\text{Trapezium rule, 2 strips: }\\int_{1}^{3}\\frac1x\\,dx", "al": "\\frac76", "s": ["h=1:\\ \\tfrac12\\left[1+2\\cdot\\tfrac12+\\tfrac13\\right]=\\frac76"], "h": "$h=1$; the $x$-values are $1,2,3$.", "ht": "$h=1$ ค่า $x$ คือ $1,2,3$", "v": 1.1666666666666667}, {"q": "\\text{Trapezium rule, 4 strips: }\\int_{0}^{2}e^{x}\\,dx\\ \\text{(4 d.p.)}", "al": "\\tfrac14\\left[1+2\\left(e^{\\frac12}+e+e^{\\frac32}\\right)+e^{2}\\right]\\approx6.5216", "s": ["h=\\tfrac12:\\ \\tfrac14\\left[e^{0}+2\\left(e^{\\frac12}+e^{1}+e^{\\frac32}\\right)+e^{2}\\right]", "\\approx6.5216"], "h": "$h=\\tfrac12$; the $x$-values are $0,\\tfrac12,1,\\tfrac32,2$.", "ht": "$h=\\tfrac12$ ค่า $x$ คือ $0,\\tfrac12,1,\\tfrac32,2$", "v": 6.521610109481282, "tol": 2e-05}, {"q": "\\text{For }\\int_{0}^{2}x^{3}\\,dx\\text{ with 2 strips, find }T_2-\\text{exact}", "al": "1", "s": ["T_2=\\tfrac12\\left[0+2\\cdot1+8\\right]=5", "\\int_{0}^{2}x^{3}dx=4,\\ \\text{so }T_2-4=1"], "h": "Work out $T_2$ and the exact value separately.", "ht": "คำนวณ $T_2$ และค่าจริงแยกกัน", "v": 1.0}, {"q": "\\text{Error bound }\\tfrac{(b-a)h^{2}}{12}\\max|f''|\\le10^{-4}\\text{ for }\\int_{0}^{1}e^{x}dx.\\ \\text{Smallest }n?", "al": "48", "s": ["f''=e^{x}\\le e,\\ h=\\tfrac1n:\\ \\frac{e}{12n^{2}}\\le10^{-4}", "n^{2}\\ge\\frac{e}{0.0012}\\approx2265.2\\Rightarrow n\\ge47.6", "n=48"], "h": "Solve $\\frac{e}{12n^{2}}\\le10^{-4}$ for $n$.", "ht": "แก้ $\\frac{e}{12n^{2}}\\le10^{-4}$ หา $n$", "v": 48.0}, {"q": "\\text{Trapezium rule, 4 strips: }\\int_{0}^{1}x^{3}\\,dx", "al": "\\frac{17}{64}", "s": ["h=\\tfrac14:\\ \\tfrac18\\left[0+2\\left(\\tfrac1{64}+\\tfrac8{64}+\\tfrac{27}{64}\\right)+1\\right]", "=\\tfrac18\\cdot\\tfrac{136}{64}=\\frac{17}{64}"], "h": "$h=\\tfrac14$: cube $\\tfrac14,\\tfrac12,\\tfrac34$.", "ht": "$h=\\tfrac14$: ยกกำลังสาม $\\tfrac14,\\tfrac12,\\tfrac34$", "v": 0.265625}]}, {"id": "invtrig", "u": "D", "n": "Inverse trig forms", "nt": "รูปตรีโกณผกผัน", "thm": [{"en": "<b>Theorem.</b> For $a&gt;0$: <span class=\"mdisp\">$\\displaystyle \\int\\frac{dx}{a^{2}+x^{2}}=\\frac1a\\arctan\\frac xa+C\\ \\ \\text{on }\\mathbb{R},\\qquad \\int\\frac{dx}{\\sqrt{a^{2}-x^{2}}}=\\arcsin\\frac xa+C\\ \\ \\text{on }(-a,a).$</span>", "th": "<b>ทฤษฎีบท</b> สำหรับ $a&gt;0$: <span class=\"mdisp\">$\\displaystyle \\int\\frac{dx}{a^{2}+x^{2}}=\\frac1a\\arctan\\frac xa+C\\ \\ \\text{บน }\\mathbb{R},\\qquad \\int\\frac{dx}{\\sqrt{a^{2}-x^{2}}}=\\arcsin\\frac xa+C\\ \\ \\text{บน }(-a,a)$</span>"}, {"en": "<b>Completing the square.</b> If $4c-b^{2}&gt;0$ then $x^{2}+bx+c=\\left(x+\\tfrac b2\\right)^{2}+k^{2}$ with $k=\\tfrac12\\sqrt{4c-b^{2}}$, so $\\displaystyle\\int\\frac{dx}{x^{2}+bx+c}=\\frac1k\\arctan\\frac{x+\\frac b2}{k}+C$.", "th": "<b>ทำเป็นกำลังสองสมบูรณ์</b> ถ้า $4c-b^{2}&gt;0$ แล้ว $x^{2}+bx+c=\\left(x+\\tfrac b2\\right)^{2}+k^{2}$ โดย $k=\\tfrac12\\sqrt{4c-b^{2}}$ ดังนั้น $\\displaystyle\\int\\frac{dx}{x^{2}+bx+c}=\\frac1k\\arctan\\frac{x+\\frac b2}{k}+C$"}], "proof": [{"en": "<b>Inverse function theorem.</b> If $f$ is differentiable and strictly monotone on an open interval with $f'\\neq0$, then $f^{-1}$ is differentiable and", "th": "<b>ทฤษฎีบทฟังก์ชันผกผัน</b> ถ้า $f$ หาอนุพันธ์ได้และเป็นฟังก์ชันทางเดียวแท้บนช่วงเปิดโดย $f'\\neq0$ แล้ว $f^{-1}$ หาอนุพันธ์ได้และ", "m": "\\left(f^{-1}\\right)'(y)=\\frac{1}{f'\\big(f^{-1}(y)\\big)}."}, {"en": "$\\tan:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to\\mathbb{R}$ has $\\tan'=\\sec^{2}&gt;0$. With $y=\\arctan x$, so $\\tan y=x$:", "th": "$\\tan:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to\\mathbb{R}$ มี $\\tan'=\\sec^{2}&gt;0$ ให้ $y=\\arctan x$ คือ $\\tan y=x$:", "m": "\\arctan'(x)=\\frac{1}{\\sec^{2}y}=\\frac{1}{1+\\tan^{2}y}=\\frac{1}{1+x^{2}}."}, {"en": "$\\sin:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to(-1,1)$ has $\\sin'=\\cos&gt;0$. With $y=\\arcsin x$, $\\cos y&gt;0$, so $\\cos y=+\\sqrt{1-\\sin^{2}y}$:", "th": "$\\sin:\\left(-\\tfrac\\pi2,\\tfrac\\pi2\\right)\\to(-1,1)$ มี $\\sin'=\\cos&gt;0$ ให้ $y=\\arcsin x$ จะได้ $\\cos y&gt;0$ ดังนั้น $\\cos y=+\\sqrt{1-\\sin^{2}y}$:", "m": "\\arcsin'(x)=\\frac{1}{\\cos y}=\\frac{1}{\\sqrt{1-x^{2}}}."}, {"en": "Chain rule with $\\frac xa$ ($a&gt;0$, so $\\sqrt{a^{2}}=a$):", "th": "กฎลูกโซ่กับ $\\frac xa$ ($a&gt;0$ ดังนั้น $\\sqrt{a^{2}}=a$):", "m": "\\frac{d}{dx}\\frac1a\\arctan\\frac xa=\\frac{1}{a^{2}}\\cdot\\frac{1}{1+\\frac{x^{2}}{a^{2}}}=\\frac{1}{a^{2}+x^{2}},\\qquad \\frac{d}{dx}\\arcsin\\frac xa=\\frac{1}{a\\sqrt{1-\\frac{x^{2}}{a^{2}}}}=\\frac{1}{\\sqrt{a^{2}-x^{2}}}."}, {"en": "Completing the square is algebra, then apply the first result with the shift $x\\mapsto x+\\frac b2$ (lesson 5). $\\blacksquare$", "th": "การทำกำลังสองสมบูรณ์เป็นพีชคณิต แล้วใช้ผลแรกกับการเลื่อน $x\\mapsto x+\\frac b2$ (บทที่ 5) $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{3}\\frac{dx}{9+x^{2}}", "al": "\\frac{\\pi}{12}", "s": ["a=3:\\ \\left[\\tfrac13\\arctan\\tfrac x3\\right]_{0}^{3}=\\tfrac13\\cdot\\tfrac\\pi4=\\frac{\\pi}{12}"]}, {"q": "\\int\\frac{dx}{x^{2}+2x+5}", "al": "\\frac12\\arctan\\frac{x+1}{2}+C", "s": ["x^{2}+2x+5=(x+1)^{2}+4", "\\frac12\\arctan\\frac{x+1}{2}+C"]}], "pr": [{"q": "\\int_{0}^{2}\\frac{dx}{4+x^{2}}", "al": "\\frac{\\pi}{8}", "s": ["\\left[\\tfrac12\\arctan\\tfrac x2\\right]_{0}^{2}=\\tfrac12\\cdot\\tfrac\\pi4=\\frac\\pi8"], "h": "$a=2$.", "ht": "$a=2$", "v": 0.39269908169872414}, {"q": "\\int_{0}^{1}\\frac{dx}{\\sqrt{4-x^{2}}}", "al": "\\frac{\\pi}{6}", "s": ["\\left[\\arcsin\\tfrac x2\\right]_{0}^{1}=\\arcsin\\tfrac12=\\frac\\pi6"], "h": "$a=2$, arcsin form.", "ht": "$a=2$ รูป arcsin", "v": 0.5235987755982989}, {"q": "\\int_{-1}^{1}\\frac{dx}{x^{2}+2x+2}", "al": "\\arctan2", "s": ["x^{2}+2x+2=(x+1)^{2}+1", "\\left[\\arctan(x+1)\\right]_{-1}^{1}=\\arctan2-0"], "h": "Complete the square.", "ht": "ทำเป็นกำลังสองสมบูรณ์", "v": 1.1071487177940904}, {"q": "\\int_{0}^{\\frac32}\\frac{dx}{\\sqrt{9-4x^{2}}}", "al": "\\frac{\\pi}{4}", "s": ["\\frac{1}{\\sqrt{9-4x^{2}}}=\\frac{1}{2\\sqrt{\\frac94-x^{2}}}", "\\left[\\tfrac12\\arcsin\\tfrac{2x}{3}\\right]_{0}^{\\frac32}=\\tfrac12\\cdot\\tfrac\\pi2=\\frac\\pi4"], "h": "Take out the $4$: $\\sqrt{9-4x^{2}}=2\\sqrt{\\frac94-x^{2}}$.", "ht": "ดึง $4$ ออก: $\\sqrt{9-4x^{2}}=2\\sqrt{\\frac94-x^{2}}$", "v": 0.7853981633974483}, {"q": "\\int\\frac{2x+3}{x^{2}+1}\\,dx", "al": "\\ln\\left(x^{2}+1\\right)+3\\arctan x+C", "s": ["\\frac{2x}{x^{2}+1}+\\frac{3}{x^{2}+1}", "\\ln\\left(x^{2}+1\\right)+3\\arctan x+C"], "h": "Split into an $f'/f$ part and an $\\arctan$ part.", "ht": "แยกเป็นส่วน $f'/f$ และส่วน $\\arctan$", "c": 1, "p": [[0.2, 1.8, 4.004249343748622], [0.46, 1.22, 2.078806177726769], [0.8, 1.54, 1.6811015221640557]]}]}, {"id": "hyp", "u": "D", "n": "Hyperbolic functions", "nt": "ฟังก์ชันไฮเพอร์โบลิก", "thm": [{"en": "<b>Definitions.</b> $\\sinh x=\\frac{e^{x}-e^{-x}}{2}$, $\\cosh x=\\frac{e^{x}+e^{-x}}{2}$, $\\tanh x=\\frac{\\sinh x}{\\cosh x}$; $\\cosh^{2}x-\\sinh^{2}x=1$.", "th": "<b>นิยาม</b> $\\sinh x=\\frac{e^{x}-e^{-x}}{2}$, $\\cosh x=\\frac{e^{x}+e^{-x}}{2}$, $\\tanh x=\\frac{\\sinh x}{\\cosh x}$ และ $\\cosh^{2}x-\\sinh^{2}x=1$"}, {"en": "<b>Theorem.</b> $\\int\\cosh x\\,dx=\\sinh x+C$, $\\int\\sinh x\\,dx=\\cosh x+C$, $\\int\\operatorname{sech}^{2}x\\,dx=\\tanh x+C$, and for $a&gt;0$: <span class=\"mdisp\">$\\displaystyle \\int\\frac{dx}{\\sqrt{x^{2}+a^{2}}}=\\operatorname{arsinh}\\frac xa+C,\\qquad \\int\\frac{dx}{\\sqrt{x^{2}-a^{2}}}=\\operatorname{arcosh}\\frac xa+C\\ (x&gt;a),$</span> where $\\operatorname{arsinh}x=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$ and $\\operatorname{arcosh}x=\\ln\\left(x+\\sqrt{x^{2}-1}\\right)$ $(x\\ge1)$.", "th": "<b>ทฤษฎีบท</b> $\\int\\cosh x\\,dx=\\sinh x+C$, $\\int\\sinh x\\,dx=\\cosh x+C$, $\\int\\operatorname{sech}^{2}x\\,dx=\\tanh x+C$ และสำหรับ $a&gt;0$: <span class=\"mdisp\">$\\displaystyle \\int\\frac{dx}{\\sqrt{x^{2}+a^{2}}}=\\operatorname{arsinh}\\frac xa+C,\\qquad \\int\\frac{dx}{\\sqrt{x^{2}-a^{2}}}=\\operatorname{arcosh}\\frac xa+C\\ (x&gt;a)$</span> โดย $\\operatorname{arsinh}x=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$ และ $\\operatorname{arcosh}x=\\ln\\left(x+\\sqrt{x^{2}-1}\\right)$ $(x\\ge1)$"}], "proof": [{"en": "Differentiate the definitions: $(\\sinh x)'=\\cosh x$, $(\\cosh x)'=\\sinh x$, and by the quotient rule $(\\tanh x)'=\\frac{\\cosh^{2}x-\\sinh^{2}x}{\\cosh^{2}x}=\\operatorname{sech}^{2}x$.", "th": "หาอนุพันธ์จากนิยาม: $(\\sinh x)'=\\cosh x$, $(\\cosh x)'=\\sinh x$ และจากกฎผลหาร $(\\tanh x)'=\\frac{\\cosh^{2}x-\\sinh^{2}x}{\\cosh^{2}x}=\\operatorname{sech}^{2}x$", "m": ""}, {"en": "$\\sinh$ is strictly increasing ($\\cosh&gt;0$) from $\\mathbb{R}$ onto $\\mathbb{R}$. Solve $x=\\sinh y$: multiply by $2e^{y}$,", "th": "$\\sinh$ เพิ่มแท้ ($\\cosh&gt;0$) จาก $\\mathbb{R}$ ทั่วถึง $\\mathbb{R}$ แก้ $x=\\sinh y$: คูณด้วย $2e^{y}$", "m": "e^{2y}-2xe^{y}-1=0\\ \\Rightarrow\\ e^{y}=x\\pm\\sqrt{x^{2}+1}."}, {"en": "Since $e^{y}&gt;0$ and $x-\\sqrt{x^{2}+1}&lt;0$, we must take $+$: $y=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$.", "th": "เนื่องจาก $e^{y}&gt;0$ และ $x-\\sqrt{x^{2}+1}&lt;0$ จึงต้องเลือก $+$: $y=\\ln\\left(x+\\sqrt{x^{2}+1}\\right)$", "m": ""}, {"en": "$\\cosh$ is strictly increasing from $[0,\\infty)$ onto $[1,\\infty)$. Solving $x=\\cosh y$ gives $e^{y}=x\\pm\\sqrt{x^{2}-1}$; the two roots multiply to $1$, so the $-$ root is $\\le1$, and $y\\ge0$ needs $e^{y}\\ge1$: take $+$.", "th": "$\\cosh$ เพิ่มแท้จาก $[0,\\infty)$ ทั่วถึง $[1,\\infty)$ แก้ $x=\\cosh y$ ได้ $e^{y}=x\\pm\\sqrt{x^{2}-1}$ สองรากคูณกันได้ $1$ รากที่เป็น $-$ จึง $\\le1$ และ $y\\ge0$ ต้องการ $e^{y}\\ge1$: เลือก $+$", "m": ""}, {"en": "Inverse function theorem (lesson 13), using $\\cosh y=+\\sqrt{1+\\sinh^{2}y}$ (as $\\cosh&gt;0$) and $\\sinh y=+\\sqrt{\\cosh^{2}y-1}$ for $y&gt;0$:", "th": "ทฤษฎีบทฟังก์ชันผกผัน (บทที่ 13) โดย $\\cosh y=+\\sqrt{1+\\sinh^{2}y}$ (เพราะ $\\cosh&gt;0$) และ $\\sinh y=+\\sqrt{\\cosh^{2}y-1}$ เมื่อ $y&gt;0$:", "m": "\\operatorname{arsinh}'x=\\frac{1}{\\cosh y}=\\frac{1}{\\sqrt{1+x^{2}}},\\qquad \\operatorname{arcosh}'x=\\frac{1}{\\sinh y}=\\frac{1}{\\sqrt{x^{2}-1}}\\ (x&gt;1)."}, {"en": "The chain rule with $\\frac xa$ gives the $a$-versions, exactly as in lesson 13. $\\blacksquare$", "th": "กฎลูกโซ่กับ $\\frac xa$ ให้รูปที่มี $a$ เหมือนบทที่ 13 $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{\\ln2}\\cosh x\\,dx", "al": "\\frac34", "s": ["\\sinh(\\ln2)=\\frac{2-\\frac12}{2}=\\frac34"]}, {"q": "\\int_{0}^{4}\\frac{dx}{\\sqrt{x^{2}+9}}", "al": "\\ln3", "s": ["\\operatorname{arsinh}\\tfrac43=\\ln\\left(\\tfrac43+\\sqrt{\\tfrac{16}{9}+1}\\right)=\\ln\\left(\\tfrac43+\\tfrac53\\right)=\\ln3"]}], "pr": [{"q": "\\int_{0}^{\\ln3}\\sinh x\\,dx", "al": "\\frac23", "s": ["\\cosh(\\ln3)-\\cosh0=\\frac{3+\\frac13}{2}-1=\\frac23"], "h": "$\\cosh(\\ln3)=\\frac{3+3^{-1}}{2}$.", "ht": "$\\cosh(\\ln3)=\\frac{3+3^{-1}}{2}$", "v": 0.6666666666666666}, {"q": "\\int_{0}^{\\frac34}\\frac{dx}{\\sqrt{1+x^{2}}}", "al": "\\ln2", "s": ["\\operatorname{arsinh}\\tfrac34=\\ln\\left(\\tfrac34+\\tfrac54\\right)=\\ln2"], "h": "Use the log form of $\\operatorname{arsinh}$.", "ht": "ใช้รูปลอการิทึมของ $\\operatorname{arsinh}$", "v": 0.6931471805599453}, {"q": "\\int_{3}^{5}\\frac{dx}{\\sqrt{x^{2}-9}}", "al": "\\ln3", "s": ["\\operatorname{arcosh}\\tfrac53-\\operatorname{arcosh}1=\\ln\\left(\\tfrac53+\\tfrac43\\right)-0=\\ln3"], "h": "$\\operatorname{arcosh}$ form with $a=3$ (improper but convergent at $x=3$).", "ht": "รูป $\\operatorname{arcosh}$ โดย $a=3$ (ไม่ตรงแบบแต่ลู่เข้าที่ $x=3$)", "v": 1.0986122886681098}, {"q": "\\int_{0}^{\\ln2}\\tanh x\\,dx", "al": "\\ln\\frac54", "s": ["\\tanh=\\frac{\\sinh}{\\cosh}=\\frac{f'}{f}", "\\left[\\ln\\cosh x\\right]_{0}^{\\ln2}=\\ln\\frac{2+\\frac12}{2}=\\ln\\frac54"], "h": "$f'/f$ with $f=\\cosh x$.", "ht": "$f'/f$ โดย $f=\\cosh x$", "v": 0.22314355131420976}, {"q": "\\int_{0}^{2}\\frac{dx}{\\sqrt{x^{2}+4x+8}}", "al": "\\ln\\frac{2+\\sqrt5}{1+\\sqrt2}", "s": ["x^{2}+4x+8=(x+2)^{2}+4", "\\left[\\operatorname{arsinh}\\tfrac{x+2}{2}\\right]_{0}^{2}=\\operatorname{arsinh}2-\\operatorname{arsinh}1", "=\\ln\\frac{2+\\sqrt5}{1+\\sqrt2}"], "h": "Complete the square, then $\\operatorname{arsinh}$.", "ht": "ทำกำลังสองสมบูรณ์ แล้วใช้ $\\operatorname{arsinh}$", "v": 0.5622618881592674}]}, {"id": "tsub", "u": "D", "n": "Trig and hyperbolic substitutions", "nt": "การแทนค่าด้วยตรีโกณและไฮเพอร์โบลิก", "thm": [{"en": "<b>Theorem.</b> For $a&gt;0$: <span class=\"mdisp\">$\\displaystyle \\int\\sqrt{a^{2}-x^{2}}\\,dx=\\frac12\\left(x\\sqrt{a^{2}-x^{2}}+a^{2}\\arcsin\\frac xa\\right)+C\\quad\\text{on }[-a,a],$</span> <span class=\"mdisp\">$\\displaystyle \\int\\sqrt{x^{2}+a^{2}}\\,dx=\\frac12\\left(x\\sqrt{x^{2}+a^{2}}+a^{2}\\operatorname{arsinh}\\frac xa\\right)+C.$</span>", "th": "<b>ทฤษฎีบท</b> สำหรับ $a&gt;0$: <span class=\"mdisp\">$\\displaystyle \\int\\sqrt{a^{2}-x^{2}}\\,dx=\\frac12\\left(x\\sqrt{a^{2}-x^{2}}+a^{2}\\arcsin\\frac xa\\right)+C\\quad\\text{บน }[-a,a]$</span> <span class=\"mdisp\">$\\displaystyle \\int\\sqrt{x^{2}+a^{2}}\\,dx=\\frac12\\left(x\\sqrt{x^{2}+a^{2}}+a^{2}\\operatorname{arsinh}\\frac xa\\right)+C$</span>"}, {"en": "Guide: $\\sqrt{a^{2}-x^{2}}\\to x=a\\sin\\theta$; $\\ a^{2}+x^{2}\\to x=a\\tan\\theta$ or $a\\sinh u$; $\\ \\sqrt{x^{2}-a^{2}}\\to x=a\\cosh u$.", "th": "แนวทาง: $\\sqrt{a^{2}-x^{2}}\\to x=a\\sin\\theta$; $\\ a^{2}+x^{2}\\to x=a\\tan\\theta$ หรือ $a\\sinh u$; $\\ \\sqrt{x^{2}-a^{2}}\\to x=a\\cosh u$"}], "proof": [{"en": "Inverse substitution (lesson 9): $\\varphi(\\theta)=a\\sin\\theta$ is $C^{1}$ and a bijection from $\\left[-\\tfrac\\pi2,\\tfrac\\pi2\\right]$ onto $[-a,a]$, with $\\varphi'(\\theta)=a\\cos\\theta$.", "th": "การแทนค่าผกผัน (บทที่ 9): $\\varphi(\\theta)=a\\sin\\theta$ เป็น $C^{1}$ และเป็นฟังก์ชันหนึ่งต่อหนึ่งทั่วถึงจาก $\\left[-\\tfrac\\pi2,\\tfrac\\pi2\\right]$ ไป $[-a,a]$ โดย $\\varphi'(\\theta)=a\\cos\\theta$", "m": ""}, {"en": "On this range $\\cos\\theta\\ge0$, so the square root has no sign problem:", "th": "ในช่วงนี้ $\\cos\\theta\\ge0$ รากที่สองจึงไม่มีปัญหาเรื่องเครื่องหมาย:", "m": "\\sqrt{a^{2}-a^{2}\\sin^{2}\\theta}=a|\\cos\\theta|=a\\cos\\theta."}, {"en": "Hence, using lesson 8,", "th": "ดังนั้นจากบทที่ 8", "m": "\\int\\sqrt{a^{2}-x^{2}}\\,dx=\\int a^{2}\\cos^{2}\\theta\\,d\\theta=\\frac{a^{2}}{2}\\left(\\theta+\\sin\\theta\\cos\\theta\\right)+C."}, {"en": "Back-substitute $\\theta=\\arcsin\\frac xa$, $\\sin\\theta=\\frac xa$, $\\cos\\theta=\\frac{\\sqrt{a^{2}-x^{2}}}{a}$ to get the formula (check: differentiate it).", "th": "แทนกลับ $\\theta=\\arcsin\\frac xa$, $\\sin\\theta=\\frac xa$, $\\cos\\theta=\\frac{\\sqrt{a^{2}-x^{2}}}{a}$ ได้สูตร (ตรวจโดยหาอนุพันธ์)", "m": ""}, {"en": "Second formula: $x=a\\sinh u$ is a $C^{1}$ bijection $\\mathbb{R}\\to\\mathbb{R}$, $\\sqrt{x^{2}+a^{2}}=a\\cosh u$ (as $\\cosh&gt;0$), so", "th": "สูตรที่สอง: $x=a\\sinh u$ เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง $\\mathbb{R}\\to\\mathbb{R}$ และ $\\sqrt{x^{2}+a^{2}}=a\\cosh u$ (เพราะ $\\cosh&gt;0$) ดังนั้น", "m": "\\int a^{2}\\cosh^{2}u\\,du=\\frac{a^{2}}{2}\\left(u+\\sinh u\\cosh u\\right)+C,\\ \\text{then }u=\\operatorname{arsinh}\\tfrac xa.\\ \\blacksquare"}], "ex": [{"q": "\\int_{0}^{2}\\sqrt{4-x^{2}}\\,dx", "al": "\\pi", "s": ["\\tfrac12\\left(0+4\\cdot\\tfrac\\pi2\\right)-0=\\pi", "\\text{(a quarter of a circle of radius }2)"]}, {"q": "\\int_{0}^{1}\\frac{x^{2}}{\\sqrt{1-x^{2}}}\\,dx", "al": "\\frac{\\pi}{4}", "s": ["x=\\sin\\theta:\\ \\int_{0}^{\\frac\\pi2}\\frac{\\sin^{2}\\theta}{\\cos\\theta}\\cos\\theta\\,d\\theta", "=\\int_{0}^{\\frac\\pi2}\\sin^{2}\\theta\\,d\\theta=\\frac\\pi4"]}], "pr": [{"q": "\\int_{0}^{3}\\sqrt{9-x^{2}}\\,dx", "al": "\\frac{9\\pi}{4}", "s": ["\\tfrac12\\left(0+9\\cdot\\tfrac\\pi2\\right)=\\frac{9\\pi}{4}"], "h": "$a=3$, or: a quarter circle.", "ht": "$a=3$ หรือคิดเป็นหนึ่งในสี่วงกลม", "v": 7.0685834705770345}, {"q": "\\int_{0}^{1}\\sqrt{4-x^{2}}\\,dx", "al": "\\frac{\\sqrt3}{2}+\\frac{\\pi}{3}", "s": ["\\tfrac12\\left(1\\cdot\\sqrt3+4\\arcsin\\tfrac12\\right)=\\frac{\\sqrt3}{2}+\\frac{\\pi}{3}"], "h": "Use the formula with $a=2$, $x=1$.", "ht": "ใช้สูตรโดย $a=2$, $x=1$", "v": 1.9132229549810364}, {"q": "\\int_{0}^{1}\\frac{dx}{\\left(1+x^{2}\\right)^{\\frac32}}", "al": "\\frac{\\sqrt2}{2}", "s": ["x=\\tan\\theta,\\ dx=\\sec^{2}\\theta\\,d\\theta:\\ \\int_{0}^{\\frac\\pi4}\\cos\\theta\\,d\\theta", "=\\sin\\tfrac\\pi4=\\frac{\\sqrt2}{2}"], "h": "Let $x=\\tan\\theta$: $1+\\tan^{2}\\theta=\\sec^{2}\\theta$.", "ht": "ให้ $x=\\tan\\theta$: $1+\\tan^{2}\\theta=\\sec^{2}\\theta$", "v": 0.7071067811865476}, {"q": "\\int_{0}^{\\frac12}\\frac{x^{2}}{\\sqrt{1-x^{2}}}\\,dx", "al": "\\frac{\\pi}{12}-\\frac{\\sqrt3}{8}", "s": ["x=\\sin\\theta:\\ \\int_{0}^{\\frac\\pi6}\\sin^{2}\\theta\\,d\\theta", "=\\left[\\tfrac\\theta2-\\tfrac{\\sin2\\theta}{4}\\right]_{0}^{\\frac\\pi6}=\\frac{\\pi}{12}-\\frac{\\sqrt3}{8}"], "h": "Let $x=\\sin\\theta$; the upper limit becomes $\\frac\\pi6$.", "ht": "ให้ $x=\\sin\\theta$ ขอบบนเป็น $\\frac\\pi6$", "v": 0.04529303685303977}, {"q": "\\int_{0}^{1}\\sqrt{x^{2}+1}\\,dx", "al": "\\frac{\\sqrt2+\\ln\\left(1+\\sqrt2\\right)}{2}", "s": ["\\tfrac12\\left(1\\cdot\\sqrt2+\\operatorname{arsinh}1\\right)", "=\\frac{\\sqrt2+\\ln\\left(1+\\sqrt2\\right)}{2}"], "h": "Second formula with $a=1$.", "ht": "สูตรที่สองโดย $a=1$", "v": 1.147793574696319}]}, {"id": "red", "u": "D", "n": "Reduction formulae", "nt": "สูตรลดทอน", "thm": [{"en": "<b>Theorem.</b> Let $I_n=\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{n}x\\,dx$. Then $I_0=\\frac\\pi2$, $I_1=1$ and <span class=\"mdisp\">$\\displaystyle I_n=\\frac{n-1}{n}I_{n-2}\\quad(n\\ge2).$</span> Also $J_n=\\displaystyle\\int_{0}^{1}x^{n}e^{x}\\,dx$ satisfies $J_0=e-1$ and $J_n=e-nJ_{n-1}$ $(n\\ge1)$.", "th": "<b>ทฤษฎีบท</b> ให้ $I_n=\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{n}x\\,dx$ แล้ว $I_0=\\frac\\pi2$, $I_1=1$ และ <span class=\"mdisp\">$\\displaystyle I_n=\\frac{n-1}{n}I_{n-2}\\quad(n\\ge2)$</span> และ $J_n=\\displaystyle\\int_{0}^{1}x^{n}e^{x}\\,dx$ มี $J_0=e-1$ และ $J_n=e-nJ_{n-1}$ $(n\\ge1)$"}, {"en": "Consequently $I_{2m}=\\dfrac{(2m-1)(2m-3)\\cdots1}{(2m)(2m-2)\\cdots2}\\cdot\\dfrac\\pi2$ and $I_{2m+1}=\\dfrac{(2m)(2m-2)\\cdots2}{(2m+1)(2m-1)\\cdots3}$ (Wallis).", "th": "ดังนั้น $I_{2m}=\\dfrac{(2m-1)(2m-3)\\cdots1}{(2m)(2m-2)\\cdots2}\\cdot\\dfrac\\pi2$ และ $I_{2m+1}=\\dfrac{(2m)(2m-2)\\cdots2}{(2m+1)(2m-1)\\cdots3}$ (วอลลิส)"}], "proof": [{"en": "For $n\\ge2$ integrate by parts (lesson 10) with $u=\\sin^{n-1}x$, $v'=\\sin x$, so $u'=(n-1)\\sin^{n-2}x\\cos x$, $v=-\\cos x$:", "th": "สำหรับ $n\\ge2$ อินทิเกรตทีละส่วน (บทที่ 10) โดย $u=\\sin^{n-1}x$, $v'=\\sin x$ ดังนั้น $u'=(n-1)\\sin^{n-2}x\\cos x$, $v=-\\cos x$:", "m": "I_n=\\Big[-\\sin^{n-1}x\\cos x\\Big]_{0}^{\\frac\\pi2}+(n-1)\\int_{0}^{\\frac\\pi2}\\sin^{n-2}x\\cos^{2}x\\,dx."}, {"en": "The bracket is $0$ at both ends (as $n-1\\ge1$). Use $\\cos^{2}x=1-\\sin^{2}x$:", "th": "วงเล็บเป็น $0$ ทั้งสองปลาย (เพราะ $n-1\\ge1$) ใช้ $\\cos^{2}x=1-\\sin^{2}x$:", "m": "I_n=(n-1)\\left(I_{n-2}-I_n\\right)\\ \\Rightarrow\\ nI_n=(n-1)I_{n-2}."}, {"en": "$I_0=\\int_{0}^{\\pi/2}1\\,dx=\\frac\\pi2$ and $I_1=[-\\cos x]_{0}^{\\pi/2}=1$; the Wallis products follow by induction on $m$.", "th": "$I_0=\\int_{0}^{\\pi/2}1\\,dx=\\frac\\pi2$ และ $I_1=[-\\cos x]_{0}^{\\pi/2}=1$ ผลคูณวอลลิสได้จากอุปนัยบน $m$", "m": ""}, {"en": "For $J_n$: parts with $u=x^{n}$, $v'=e^{x}$:", "th": "สำหรับ $J_n$: ทีละส่วนโดย $u=x^{n}$, $v'=e^{x}$:", "m": "J_n=\\Big[x^{n}e^{x}\\Big]_{0}^{1}-n\\int_{0}^{1}x^{n-1}e^{x}\\,dx=e-nJ_{n-1}.\\ \\blacksquare"}], "ex": [{"q": "\\int_{0}^{\\frac\\pi2}\\sin^{4}x\\,dx", "al": "\\frac{3\\pi}{16}", "s": ["I_4=\\tfrac34I_2=\\tfrac34\\cdot\\tfrac12I_0=\\tfrac38\\cdot\\tfrac\\pi2=\\frac{3\\pi}{16}"]}, {"q": "\\int_{0}^{1}x^{2}e^{x}\\,dx", "al": "e-2", "s": ["J_1=e-J_0=1,\\quad J_2=e-2J_1=e-2"]}], "pr": [{"q": "\\int_{0}^{\\frac\\pi2}\\sin^{5}x\\,dx", "al": "\\frac{8}{15}", "s": ["I_5=\\tfrac45I_3=\\tfrac45\\cdot\\tfrac23I_1=\\frac{8}{15}"], "h": "$I_5=\\frac45I_3$, $I_3=\\frac23I_1$.", "ht": "$I_5=\\frac45I_3$, $I_3=\\frac23I_1$", "v": 0.5333333333333333}, {"q": "\\int_{0}^{\\frac\\pi2}\\sin^{6}x\\,dx", "al": "\\frac{5\\pi}{32}", "s": ["I_6=\\tfrac56\\cdot\\tfrac34\\cdot\\tfrac12\\cdot\\tfrac\\pi2=\\frac{5\\pi}{32}"], "h": "Go down to $I_0=\\frac\\pi2$.", "ht": "ลดลงไปถึง $I_0=\\frac\\pi2$", "v": 0.4908738521234052}, {"q": "\\int_{0}^{\\frac\\pi2}\\cos^{4}x\\,dx", "al": "\\frac{3\\pi}{16}", "s": ["x=\\tfrac\\pi2-u\\text{ turns }\\cos^{4}x\\text{ into }\\sin^{4}u", "=I_4=\\frac{3\\pi}{16}"], "h": "Substitute $x=\\frac\\pi2-u$: it becomes $I_4$.", "ht": "แทน $x=\\frac\\pi2-u$ จะกลายเป็น $I_4$", "v": 0.5890486225480862}, {"q": "\\int_{0}^{1}x^{3}e^{x}\\,dx", "al": "6-2e", "s": ["J_3=e-3J_2=e-3(e-2)=6-2e"], "h": "Use $J_2=e-2$ from the example.", "ht": "ใช้ $J_2=e-2$ จากตัวอย่าง", "v": 0.5634363430819095}, {"q": "\\int_{0}^{\\frac\\pi2}\\sin^{7}x\\,dx", "al": "\\frac{16}{35}", "s": ["I_7=\\tfrac67\\cdot\\tfrac45\\cdot\\tfrac23\\cdot1=\\frac{16}{35}"], "h": "Odd power: end at $I_1=1$.", "ht": "กำลังคี่: จบที่ $I_1=1$", "v": 0.45714285714285713}]}, {"id": "sym", "u": "E", "n": "Odd, even and periodic functions", "nt": "ฟังก์ชันคี่ คู่ และเป็นคาบ", "thm": [{"en": "<b>Theorem.</b> Let $f$ be continuous on $[-a,a]$. If $f$ is odd ($f(-x)=-f(x)$) then $\\displaystyle\\int_{-a}^{a}f=0$; if $f$ is even ($f(-x)=f(x)$) then $\\displaystyle\\int_{-a}^{a}f=2\\int_{0}^{a}f$.", "th": "<b>ทฤษฎีบท</b> ให้ $f$ ต่อเนื่องบน $[-a,a]$ ถ้า $f$ เป็นฟังก์ชันคี่ ($f(-x)=-f(x)$) แล้ว $\\displaystyle\\int_{-a}^{a}f=0$ ถ้า $f$ เป็นฟังก์ชันคู่ ($f(-x)=f(x)$) แล้ว $\\displaystyle\\int_{-a}^{a}f=2\\int_{0}^{a}f$"}, {"en": "<b>Theorem.</b> If $f$ is continuous on $\\mathbb{R}$ with period $T$, then $\\displaystyle\\int_{a}^{a+T}f=\\int_{0}^{T}f$ for every $a$, so $\\displaystyle\\int_{0}^{nT}f=n\\int_{0}^{T}f$.", "th": "<b>ทฤษฎีบท</b> ถ้า $f$ ต่อเนื่องบน $\\mathbb{R}$ และมีคาบ $T$ แล้ว $\\displaystyle\\int_{a}^{a+T}f=\\int_{0}^{T}f$ ทุก $a$ ดังนั้น $\\displaystyle\\int_{0}^{nT}f=n\\int_{0}^{T}f$"}], "proof": [{"en": "Split at $0$ and substitute $x=-u$ in the left piece (lesson 9):", "th": "แยกที่ $0$ แล้วแทน $x=-u$ ในส่วนซ้าย (บทที่ 9):", "m": "\\int_{-a}^{0}f(x)\\,dx=\\int_{a}^{0}f(-u)(-du)=\\int_{0}^{a}f(-u)\\,du."}, {"en": "So", "th": "ดังนั้น", "m": "\\int_{-a}^{a}f=\\int_{0}^{a}\\big(f(-u)+f(u)\\big)\\,du,"}, {"en": "which is $0$ when $f$ is odd and $2\\int_{0}^{a}f$ when $f$ is even.", "th": "ซึ่งเป็น $0$ เมื่อ $f$ คี่ และเป็น $2\\int_{0}^{a}f$ เมื่อ $f$ คู่", "m": ""}, {"en": "Periodic: let $G(a)=\\int_{a}^{a+T}f$. By FTC (1) (lesson 4) and periodicity,", "th": "เป็นคาบ: ให้ $G(a)=\\int_{a}^{a+T}f$ จาก FTC (1) (บทที่ 4) และความเป็นคาบ", "m": "G'(a)=f(a+T)-f(a)=0,"}, {"en": "so $G$ is constant: $G(a)=G(0)=\\int_{0}^{T}f$. Splitting $[0,nT]$ into $n$ periods gives the last part. $\\blacksquare$", "th": "$G$ จึงเป็นค่าคงตัว: $G(a)=G(0)=\\int_{0}^{T}f$ แยก $[0,nT]$ เป็น $n$ คาบได้ส่วนสุดท้าย $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{-\\pi}^{\\pi}\\left(x^{2}+\\sin x\\right)dx", "al": "\\frac{2\\pi^{3}}{3}", "s": ["\\sin x\\text{ is odd: }0", "2\\int_{0}^{\\pi}x^{2}\\,dx=\\frac{2\\pi^{3}}{3}"]}, {"q": "\\int_{0}^{10\\pi}|\\sin x|\\,dx", "al": "20", "s": ["|\\sin x|\\text{ has period }\\pi", "10\\int_{0}^{\\pi}\\sin x\\,dx=10\\cdot2=20"]}], "pr": [{"q": "\\int_{-2}^{2}\\left(x^{3}-4x+1\\right)dx", "al": "4", "s": ["x^{3}-4x\\text{ is odd}", "\\int_{-2}^{2}1\\,dx=4"], "h": "Remove the odd part first.", "ht": "ตัดส่วนที่เป็นฟังก์ชันคี่ก่อน", "v": 4.0}, {"q": "\\int_{-1}^{1}\\left(x^{2}+x^{5}e^{x^{2}}\\right)dx", "al": "\\frac23", "s": ["x^{5}e^{x^{2}}\\text{ is odd}", "2\\int_{0}^{1}x^{2}\\,dx=\\frac23"], "h": "$x^{5}$ is odd and $e^{x^{2}}$ is even: the product is odd.", "ht": "$x^{5}$ คี่ และ $e^{x^{2}}$ คู่ ผลคูณจึงคี่", "v": 0.6666666666666666}, {"q": "\\int_{-\\frac\\pi4}^{\\frac\\pi4}\\left(\\sec^{2}x+x\\tan^{2}x\\right)dx", "al": "2", "s": ["x\\tan^{2}x\\text{ is odd}", "\\left[\\tan x\\right]_{-\\frac\\pi4}^{\\frac\\pi4}=1-(-1)=2"], "h": "Is $x\\tan^{2}x$ odd or even?", "ht": "$x\\tan^{2}x$ เป็นคี่หรือคู่", "v": 2.0}, {"q": "\\int_{0}^{6\\pi}|\\cos x|\\,dx", "al": "12", "s": ["|\\cos x|\\text{ has period }\\pi\\text{ and }\\int_{0}^{\\pi}|\\cos x|\\,dx=2", "6\\cdot2=12"], "h": "Period $\\pi$: find one period's integral.", "ht": "คาบ $\\pi$: หาอินทิกรัลหนึ่งคาบ", "v": 12.0}, {"q": "\\int_{0}^{4\\pi}\\sin^{2}x\\,dx", "al": "2\\pi", "s": ["\\sin^{2}x\\text{ has period }\\pi,\\ \\int_{0}^{\\pi}\\sin^{2}x\\,dx=\\frac\\pi2", "4\\cdot\\frac\\pi2=2\\pi"], "h": "$\\sin^{2}x$ has period $\\pi$.", "ht": "$\\sin^{2}x$ มีคาบ $\\pi$", "v": 6.283185307179586}]}, {"id": "king", "u": "E", "n": "King's rule", "nt": "King's rule", "thm": [{"en": "<b>Theorem (King's rule).</b> If $f$ is continuous on $[a,b]$, then <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f(x)\\,dx=\\int_{a}^{b}f(a+b-x)\\,dx.$</span>", "th": "<b>ทฤษฎีบท (King's rule)</b> ถ้า $f$ ต่อเนื่องบน $[a,b]$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{a}^{b}f(x)\\,dx=\\int_{a}^{b}f(a+b-x)\\,dx$</span>"}, {"en": "<b>Corollaries.</b> (i) If $f(x)+f(a+b-x)=c$ (a constant), then $\\int_{a}^{b}f=\\frac{c(b-a)}{2}$. (ii) If $g(a+b-x)=g(x)$, then $\\int_{a}^{b}x\\,g(x)\\,dx=\\frac{a+b}{2}\\int_{a}^{b}g(x)\\,dx$.", "th": "<b>บทแทรก</b> (i) ถ้า $f(x)+f(a+b-x)=c$ (ค่าคงตัว) แล้ว $\\int_{a}^{b}f=\\frac{c(b-a)}{2}$ (ii) ถ้า $g(a+b-x)=g(x)$ แล้ว $\\int_{a}^{b}x\\,g(x)\\,dx=\\frac{a+b}{2}\\int_{a}^{b}g(x)\\,dx$"}], "proof": [{"en": "Substitute $u=a+b-x$ (lesson 9): $du=-dx$, and $x=a\\mapsto u=b$, $x=b\\mapsto u=a$:", "th": "แทน $u=a+b-x$ (บทที่ 9): $du=-dx$ และ $x=a\\mapsto u=b$, $x=b\\mapsto u=a$:", "m": "\\int_{a}^{b}f(a+b-x)\\,dx=\\int_{b}^{a}f(u)\\,(-du)=\\int_{a}^{b}f(u)\\,du."}, {"en": "(i) Call the integral $I$. Adding the two forms of $I$:", "th": "(i) ให้อินทิกรัลเป็น $I$ บวกสองรูปของ $I$:", "m": "2I=\\int_{a}^{b}\\big(f(x)+f(a+b-x)\\big)\\,dx=c(b-a)."}, {"en": "(ii) Apply the rule to $x\\,g(x)$ and use $g(a+b-x)=g(x)$:", "th": "(ii) ใช้กฎกับ $x\\,g(x)$ และ $g(a+b-x)=g(x)$:", "m": "I=\\int_{a}^{b}(a+b-x)g(x)\\,dx\\ \\Rightarrow\\ 2I=(a+b)\\int_{a}^{b}g.\\ \\blacksquare"}], "ex": [{"q": "\\int_{1}^{3}\\frac{x^{2}}{x^{2}+(4-x)^{2}}\\,dx", "al": "1", "s": ["a+b=4:\\ f(x)+f(4-x)=\\frac{x^{2}+(4-x)^{2}}{x^{2}+(4-x)^{2}}=1", "I=\\frac{1\\cdot(3-1)}{2}=1"]}, {"q": "\\int_{0}^{\\pi}x\\sin x\\,dx", "al": "\\pi", "s": ["g=\\sin x,\\ g(\\pi-x)=g(x)", "\\frac\\pi2\\int_{0}^{\\pi}\\sin x\\,dx=\\frac\\pi2\\cdot2=\\pi"]}], "pr": [{"q": "\\int_{0}^{\\frac\\pi2}\\frac{\\cos^{3}x}{\\sin^{3}x+\\cos^{3}x}\\,dx", "al": "\\frac{\\pi}{4}", "s": ["x\\to\\tfrac\\pi2-x\\text{ swaps }\\sin\\text{ and }\\cos", "f(x)+f\\left(\\tfrac\\pi2-x\\right)=1\\Rightarrow I=\\frac\\pi4"], "h": "King's rule swaps $\\sin$ and $\\cos$ here.", "ht": "King's rule สลับ $\\sin$ กับ $\\cos$", "v": 0.7853981633974483}, {"q": "\\int_{2}^{5}\\frac{\\sqrt x}{\\sqrt x+\\sqrt{7-x}}\\,dx", "al": "\\frac32", "s": ["a+b=7:\\ f(x)+f(7-x)=1", "I=\\frac{5-2}{2}=\\frac32"], "h": "$a+b=7$.", "ht": "$a+b=7$", "v": 1.5}, {"q": "\\int_{0}^{\\pi}x\\sin^{2}x\\,dx", "al": "\\frac{\\pi^{2}}{4}", "s": ["g=\\sin^{2}x\\text{ is symmetric about }\\tfrac\\pi2", "\\frac\\pi2\\int_{0}^{\\pi}\\sin^{2}x\\,dx=\\frac\\pi2\\cdot\\frac\\pi2"], "h": "Corollary (ii) with $g=\\sin^{2}x$.", "ht": "บทแทรก (ii) โดย $g=\\sin^{2}x$", "v": 2.4674011002723395}, {"q": "\\int_{0}^{\\frac\\pi2}\\ln(\\tan x)\\,dx", "al": "0", "s": ["\\ln\\tan\\left(\\tfrac\\pi2-x\\right)=\\ln\\cot x=-\\ln\\tan x", "I=-I\\Rightarrow I=0\\ \\text{(the integral converges)}"], "h": "What is $\\tan\\left(\\frac\\pi2-x\\right)$?", "ht": "$\\tan\\left(\\frac\\pi2-x\\right)$ เท่ากับอะไร", "v": -6.1502487250273326e-30}, {"q": "\\int_{0}^{1}x(1-x)^{9}\\,dx", "al": "\\frac{1}{110}", "s": ["x\\to1-x:\\ \\int_{0}^{1}(1-x)x^{9}\\,dx", "=\\frac{1}{10}-\\frac{1}{11}=\\frac{1}{110}"], "h": "King's rule moves the power onto $x$.", "ht": "King's rule ย้ายเลขชี้กำลังมาที่ $x$", "v": 0.00909090909090909}]}, {"id": "esym", "u": "E", "n": "The 1/(1+eˣ) trick", "nt": "ทริค 1/(1+eˣ)", "thm": [{"en": "<b>Theorem.</b> Let $f$ be continuous and even on $[-a,a]$, and $g$ continuous with $g&gt;0$ and $g(-x)=\\dfrac{1}{g(x)}$. Then <span class=\"mdisp\">$\\displaystyle \\int_{-a}^{a}\\frac{f(x)}{1+g(x)}\\,dx=\\int_{0}^{a}f(x)\\,dx.$</span>", "th": "<b>ทฤษฎีบท</b> ให้ $f$ ต่อเนื่องและเป็นฟังก์ชันคู่บน $[-a,a]$ และ $g$ ต่อเนื่อง $g&gt;0$ และ $g(-x)=\\dfrac{1}{g(x)}$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{-a}^{a}\\frac{f(x)}{1+g(x)}\\,dx=\\int_{0}^{a}f(x)\\,dx$</span>"}, {"en": "Typical $g$: $e^{x}$, $b^{x}$ ($b&gt;0$), or $e^{h(x)}$ with $h$ odd, e.g. $e^{\\sin x}$.", "th": "ตัวอย่าง $g$: $e^{x}$, $b^{x}$ ($b&gt;0$) หรือ $e^{h(x)}$ ที่ $h$ เป็นฟังก์ชันคี่ เช่น $e^{\\sin x}$"}], "proof": [{"en": "Let $I$ be the integral. Substitute $x=-u$ (lesson 9) and use that $f$ is even:", "th": "ให้ $I$ เป็นอินทิกรัล แทน $x=-u$ (บทที่ 9) และใช้ว่า $f$ เป็นฟังก์ชันคู่:", "m": "I=\\int_{-a}^{a}\\frac{f(u)}{1+g(-u)}\\,du=\\int_{-a}^{a}\\frac{f(u)}{1+\\frac{1}{g(u)}}\\,du=\\int_{-a}^{a}\\frac{f(u)\\,g(u)}{g(u)+1}\\,du."}, {"en": "Add this to the original form of $I$:", "th": "บวกกับรูปเดิมของ $I$:", "m": "2I=\\int_{-a}^{a}f(u)\\,\\frac{1+g(u)}{1+g(u)}\\,du=\\int_{-a}^{a}f=2\\int_{0}^{a}f\\quad\\text{(lesson 17)}.\\ \\blacksquare"}], "ex": [{"q": "\\int_{-1}^{1}\\frac{x^{2}}{1+e^{x}}\\,dx", "al": "\\frac13", "s": ["f=x^{2}\\text{ even},\\ g=e^{x}", "\\int_{0}^{1}x^{2}\\,dx=\\frac13"]}, {"q": "\\int_{-\\pi}^{\\pi}\\frac{\\cos^{2}x}{1+2^{x}}\\,dx", "al": "\\frac{\\pi}{2}", "s": ["g=2^{x},\\ 2^{-x}=\\frac{1}{2^{x}}", "\\int_{0}^{\\pi}\\cos^{2}x\\,dx=\\frac\\pi2"]}], "pr": [{"q": "\\int_{-2}^{2}\\frac{x^{4}}{1+e^{x}}\\,dx", "al": "\\frac{32}{5}", "s": ["\\int_{0}^{2}x^{4}\\,dx=\\frac{32}{5}"], "h": "$f=x^{4}$ is even.", "ht": "$f=x^{4}$ เป็นฟังก์ชันคู่", "v": 6.4}, {"q": "\\int_{-\\frac\\pi2}^{\\frac\\pi2}\\frac{\\cos x}{1+e^{x}}\\,dx", "al": "1", "s": ["\\int_{0}^{\\frac\\pi2}\\cos x\\,dx=1"], "h": "$\\cos x$ is even.", "ht": "$\\cos x$ เป็นฟังก์ชันคู่", "v": 1.0}, {"q": "\\int_{-1}^{1}\\frac{dx}{\\left(1+e^{x}\\right)\\left(1+x^{2}\\right)}", "al": "\\frac{\\pi}{4}", "s": ["f=\\frac{1}{1+x^{2}}\\text{ even}", "\\int_{0}^{1}\\frac{dx}{1+x^{2}}=\\frac\\pi4"], "h": "Take $f(x)=\\frac{1}{1+x^{2}}$.", "ht": "ให้ $f(x)=\\frac{1}{1+x^{2}}$", "v": 0.7853981633974483}, {"q": "\\int_{-\\pi}^{\\pi}\\frac{dx}{1+e^{\\sin x}}", "al": "\\pi", "s": ["g=e^{\\sin x},\\ g(-x)=e^{-\\sin x}=\\frac1{g(x)}", "\\int_{0}^{\\pi}1\\,dx=\\pi"], "h": "$\\sin x$ is odd, so $g=e^{\\sin x}$ works.", "ht": "$\\sin x$ เป็นฟังก์ชันคี่ $g=e^{\\sin x}$ จึงใช้ได้", "v": 3.141592653589793}, {"q": "\\int_{-3}^{3}\\frac{x^{2}}{1+3^{x}}\\,dx", "al": "9", "s": ["g=3^{x}:\\ \\int_{0}^{3}x^{2}\\,dx=9"], "h": "$g=3^{x}$.", "ht": "$g=3^{x}$", "v": 9.0}]}, {"id": "recip", "u": "E", "n": "The substitution x → 1/x", "nt": "การแทน x → 1/x", "thm": [{"en": "<b>Theorem.</b> Let $f$ be continuous on $(0,\\infty)$ and suppose $\\displaystyle\\int_{0}^{\\infty}f(x)\\,dx$ converges. Then <span class=\"mdisp\">$\\displaystyle \\int_{0}^{\\infty}f(x)\\,dx=\\int_{0}^{\\infty}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du.$</span> Likewise, for $c&gt;1$ and $f$ continuous on $\\left[\\frac1c,c\\right]$: $\\displaystyle\\int_{1/c}^{c}f(x)\\,dx=\\int_{1/c}^{c}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du$.", "th": "<b>ทฤษฎีบท</b> ให้ $f$ ต่อเนื่องบน $(0,\\infty)$ และ $\\displaystyle\\int_{0}^{\\infty}f(x)\\,dx$ ลู่เข้า แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{0}^{\\infty}f(x)\\,dx=\\int_{0}^{\\infty}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du$</span> ในทำนองเดียวกัน สำหรับ $c&gt;1$ และ $f$ ต่อเนื่องบน $\\left[\\frac1c,c\\right]$: $\\displaystyle\\int_{1/c}^{c}f(x)\\,dx=\\int_{1/c}^{c}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du$"}, {"en": "Use: if the new integrand is $-f$, then $I=0$; otherwise add the two forms, $2I=\\int\\left(f(x)+\\frac{f(1/x)}{x^{2}}\\right)dx$.", "th": "การใช้: ถ้าฟังก์ชันใหม่เป็น $-f$ แล้ว $I=0$ มิฉะนั้นบวกสองรูป $2I=\\int\\left(f(x)+\\frac{f(1/x)}{x^{2}}\\right)dx$"}], "proof": [{"en": "By definition of the improper integral,", "th": "จากนิยามของอินทิกรัลไม่ตรงแบบ", "m": "\\int_{0}^{\\infty}f=\\lim_{\\varepsilon\\to0^{+},\\,R\\to\\infty}\\int_{\\varepsilon}^{R}f(x)\\,dx."}, {"en": "On $[\\varepsilon,R]$ with $0&lt;\\varepsilon&lt;R$, substitute $x=\\frac1u$, a $C^{1}$ bijection from $\\left[\\frac1R,\\frac1\\varepsilon\\right]$, $dx=-\\frac{du}{u^{2}}$:", "th": "บน $[\\varepsilon,R]$ โดย $0&lt;\\varepsilon&lt;R$ แทน $x=\\frac1u$ ซึ่งเป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึงจาก $\\left[\\frac1R,\\frac1\\varepsilon\\right]$ และ $dx=-\\frac{du}{u^{2}}$:", "m": "\\int_{\\varepsilon}^{R}f(x)\\,dx=\\int_{1/\\varepsilon}^{1/R}f\\left(\\tfrac1u\\right)\\left(-\\frac{du}{u^{2}}\\right)=\\int_{1/R}^{1/\\varepsilon}\\frac{f\\left(\\frac1u\\right)}{u^{2}}\\,du."}, {"en": "As $\\varepsilon\\to0^{+}$ and $R\\to\\infty$, the left side converges by assumption; the right side is the same number, and its limits $\\frac1R\\to0^{+}$, $\\frac1\\varepsilon\\to\\infty$. So the right improper integral converges to the same value.", "th": "เมื่อ $\\varepsilon\\to0^{+}$ และ $R\\to\\infty$ ด้านซ้ายลู่เข้าตามสมมติฐาน ด้านขวาเป็นจำนวนเดียวกัน และขอบเขต $\\frac1R\\to0^{+}$, $\\frac1\\varepsilon\\to\\infty$ อินทิกรัลด้านขวาจึงลู่เข้าค่าเดียวกัน", "m": ""}, {"en": "For $\\left[\\frac1c,c\\right]$ the same substitution maps the interval onto itself (no limits needed). $\\blacksquare$", "th": "สำหรับ $\\left[\\frac1c,c\\right]$ การแทนเดียวกันส่งช่วงไปยังตัวเอง (ไม่ต้องใช้ลิมิต) $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{\\infty}\\frac{dx}{\\left(1+x^{2}\\right)\\left(1+x^{3}\\right)}", "al": "\\frac{\\pi}{4}", "s": ["x\\to\\tfrac1u:\\ I=\\int_{0}^{\\infty}\\frac{u^{3}\\,du}{\\left(1+u^{2}\\right)\\left(1+u^{3}\\right)}", "2I=\\int_{0}^{\\infty}\\frac{1+u^{3}}{\\left(1+u^{2}\\right)\\left(1+u^{3}\\right)}du=\\frac\\pi2", "I=\\frac\\pi4"]}, {"q": "\\int_{\\frac13}^{3}\\frac{\\arctan x}{x}\\,dx", "al": "\\frac\\pi2\\ln3", "s": ["x\\to\\tfrac1u:\\ I=\\int_{1/3}^{3}\\frac{\\arctan\\frac1u}{u}\\,du", "\\arctan x+\\arctan\\tfrac1x=\\tfrac\\pi2\\ (x&gt;0):\\ 2I=\\frac\\pi2\\int_{1/3}^{3}\\frac{dx}{x}=\\frac\\pi2\\ln9", "I=\\frac\\pi2\\ln3"]}], "pr": [{"q": "\\int_{0}^{\\infty}\\frac{dx}{\\left(1+x^{2}\\right)\\left(1+x^{10}\\right)}", "al": "\\frac{\\pi}{4}", "s": ["x\\to\\tfrac1u\\text{ gives }\\frac{u^{10}}{\\left(1+u^{2}\\right)\\left(1+u^{10}\\right)}", "2I=\\int_{0}^{\\infty}\\frac{dx}{1+x^{2}}=\\frac\\pi2"], "h": "Same trick as the first example: the power doesn't matter.", "ht": "ทริคเดียวกับตัวอย่างแรก เลขชี้กำลังไม่สำคัญ", "v": 0.7853981633974483}, {"q": "\\int_{0}^{\\infty}\\frac{\\ln x}{(1+x)^{2}}\\,dx", "al": "0", "s": ["x\\to\\tfrac1u:\\ \\frac{\\ln\\frac1u}{\\left(1+\\frac1u\\right)^{2}u^{2}}=-\\frac{\\ln u}{(u+1)^{2}}", "I=-I\\Rightarrow I=0"], "h": "Simplify $\\frac{f(1/u)}{u^{2}}$.", "ht": "จัดรูป $\\frac{f(1/u)}{u^{2}}$", "v": -1.88079096131566e-37}, {"q": "\\int_{0}^{\\infty}\\frac{1+x^{2}}{1+x^{4}}\\,dx", "al": "\\frac{\\pi}{\\sqrt2}", "s": ["\\text{Divide by }x^{2}:\\ \\frac{1+\\frac{1}{x^{2}}}{\\left(x-\\frac1x\\right)^{2}+2}", "u=x-\\tfrac1x\\ (\\text{maps }(0,\\infty)\\text{ onto }\\mathbb{R}):\\ \\int_{-\\infty}^{\\infty}\\frac{du}{u^{2}+2}=\\frac{\\pi}{\\sqrt2}"], "h": "Divide top and bottom by $x^{2}$, then $u=x-\\frac1x$.", "ht": "หารบนล่างด้วย $x^{2}$ แล้วให้ $u=x-\\frac1x$", "v": 2.221441469079183}, {"q": "\\int_{\\frac12}^{2}\\frac{\\ln x}{1+x^{2}}\\,dx", "al": "0", "s": ["x\\to\\tfrac1u\\text{ maps }\\left[\\tfrac12,2\\right]\\text{ to itself and gives }-\\frac{\\ln u}{1+u^{2}}", "I=-I\\Rightarrow I=0"], "h": "The interval $\\left[\\frac12,2\\right]$ is of the form $\\left[\\frac1c,c\\right]$.", "ht": "ช่วง $\\left[\\frac12,2\\right]$ อยู่ในรูป $\\left[\\frac1c,c\\right]$", "v": 3.390432315559383e-35}, {"q": "\\int_{\\frac12}^{2}\\frac{\\arctan x}{x}\\,dx", "al": "\\frac\\pi2\\ln2", "s": ["2I=\\frac\\pi2\\int_{1/2}^{2}\\frac{dx}{x}=\\frac\\pi2\\ln4", "I=\\frac\\pi2\\ln2"], "h": "Like the second example, with $c=2$.", "ht": "เหมือนตัวอย่างที่สอง โดย $c=2$", "v": 1.088793045151801}]}, {"id": "weier", "u": "E", "n": "The Weierstrass substitution", "nt": "การแทนค่าแบบไวแยร์สตราส", "thm": [{"en": "<b>Theorem.</b> On $(-\\pi,\\pi)$ the substitution $t=\\tan\\frac x2$ is a $C^{1}$ bijection onto $\\mathbb{R}$, and <span class=\"mdisp\">$\\displaystyle \\sin x=\\frac{2t}{1+t^{2}},\\qquad \\cos x=\\frac{1-t^{2}}{1+t^{2}},\\qquad dx=\\frac{2\\,dt}{1+t^{2}}.$</span> So every integral of a rational function of $\\sin x$ and $\\cos x$ becomes the integral of a rational function of $t$ (then lesson 11).", "th": "<b>ทฤษฎีบท</b> บน $(-\\pi,\\pi)$ การแทน $t=\\tan\\frac x2$ เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง $\\mathbb{R}$ และ <span class=\"mdisp\">$\\displaystyle \\sin x=\\frac{2t}{1+t^{2}},\\qquad \\cos x=\\frac{1-t^{2}}{1+t^{2}},\\qquad dx=\\frac{2\\,dt}{1+t^{2}}$</span> ดังนั้นอินทิกรัลของฟังก์ชันตรรกยะของ $\\sin x$ และ $\\cos x$ จะกลายเป็นอินทิกรัลของฟังก์ชันตรรกยะของ $t$ (แล้วใช้บทที่ 11)"}], "proof": [{"en": "For $x\\in(-\\pi,\\pi)$, $\\frac x2\\in\\left(-\\frac\\pi2,\\frac\\pi2\\right)$, where $\\tan$ is a strictly increasing $C^{1}$ bijection onto $\\mathbb{R}$; its inverse is $x=2\\arctan t$.", "th": "เมื่อ $x\\in(-\\pi,\\pi)$ จะได้ $\\frac x2\\in\\left(-\\frac\\pi2,\\frac\\pi2\\right)$ ซึ่ง $\\tan$ เพิ่มแท้ เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง $\\mathbb{R}$ ตัวผกผันคือ $x=2\\arctan t$", "m": ""}, {"en": "Double-angle formulas with $\\cos^{2}\\frac x2=\\frac{1}{\\sec^{2}\\frac x2}=\\frac{1}{1+t^{2}}$:", "th": "สูตรมุมสองเท่ากับ $\\cos^{2}\\frac x2=\\frac{1}{\\sec^{2}\\frac x2}=\\frac{1}{1+t^{2}}$:", "m": "\\sin x=2\\tan\\tfrac x2\\cos^{2}\\tfrac x2=\\frac{2t}{1+t^{2}},\\qquad \\cos x=\\cos^{2}\\tfrac x2\\left(1-\\tan^{2}\\tfrac x2\\right)=\\frac{1-t^{2}}{1+t^{2}}."}, {"en": "From $x=2\\arctan t$ (lesson 13): $\\dfrac{dx}{dt}=\\dfrac{2}{1+t^{2}}$. The inverse-substitution form of lesson 9 now applies. $\\blacksquare$", "th": "จาก $x=2\\arctan t$ (บทที่ 13): $\\dfrac{dx}{dt}=\\dfrac{2}{1+t^{2}}$ จึงใช้การแทนค่าผกผันของบทที่ 9 ได้ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{\\frac\\pi2}\\frac{dx}{1+\\sin x}", "al": "1", "s": ["1+\\sin x=\\frac{(1+t)^{2}}{1+t^{2}},\\ t:0\\to1", "\\int_{0}^{1}\\frac{2\\,dt}{(1+t)^{2}}=\\left[-\\frac{2}{1+t}\\right]_{0}^{1}=1"]}, {"q": "\\int_{0}^{\\frac\\pi2}\\frac{dx}{2+\\cos x}", "al": "\\frac{\\pi}{3\\sqrt3}", "s": ["2+\\cos x=\\frac{3+t^{2}}{1+t^{2}}", "\\int_{0}^{1}\\frac{2\\,dt}{3+t^{2}}=\\frac{2}{\\sqrt3}\\arctan\\frac{1}{\\sqrt3}=\\frac{\\pi}{3\\sqrt3}"]}], "pr": [{"q": "\\int_{0}^{\\frac\\pi2}\\frac{dx}{1+\\cos x}", "al": "1", "s": ["1+\\cos x=\\frac{2}{1+t^{2}}", "\\int_{0}^{1}dt=1"], "h": "$1+\\cos x$ simplifies to $\\frac{2}{1+t^{2}}$.", "ht": "$1+\\cos x$ ลดรูปเป็น $\\frac{2}{1+t^{2}}$", "v": 1.0}, {"q": "\\int_{0}^{\\frac\\pi2}\\frac{dx}{1+\\sin x+\\cos x}", "al": "\\ln2", "s": ["1+\\sin x+\\cos x=\\frac{2+2t}{1+t^{2}}", "\\int_{0}^{1}\\frac{dt}{1+t}=\\ln2"], "h": "Put everything over $1+t^{2}$.", "ht": "ทำทุกพจน์ให้มีส่วน $1+t^{2}$", "v": 0.6931471805599453}, {"q": "\\int_{0}^{\\frac\\pi2}\\frac{dx}{3+5\\cos x}", "al": "\\frac{\\ln3}{4}", "s": ["3+5\\cos x=\\frac{8-2t^{2}}{1+t^{2}}", "\\int_{0}^{1}\\frac{dt}{4-t^{2}}=\\left[\\tfrac14\\ln\\frac{2+t}{2-t}\\right]_{0}^{1}=\\frac{\\ln3}{4}"], "h": "You get $\\int\\frac{dt}{4-t^{2}}$: partial fractions.", "ht": "ได้ $\\int\\frac{dt}{4-t^{2}}$ ใช้เศษส่วนย่อย", "v": 0.27465307216702745}, {"q": "\\int_{0}^{\\pi}\\frac{dx}{2+\\cos x}", "al": "\\frac{\\pi}{\\sqrt3}", "s": ["t:0\\to\\infty\\ \\text{(an improper limit)}", "\\int_{0}^{\\infty}\\frac{2\\,dt}{3+t^{2}}=\\frac{2}{\\sqrt3}\\cdot\\frac\\pi2=\\frac{\\pi}{\\sqrt3}"], "h": "As $x\\to\\pi^{-}$, $t\\to\\infty$.", "ht": "เมื่อ $x\\to\\pi^{-}$ จะได้ $t\\to\\infty$", "v": 1.8137993642342178}, {"q": "\\int_{0}^{\\frac\\pi2}\\frac{dx}{5+4\\sin x}", "al": "\\frac23\\arctan\\frac13", "s": ["5+4\\sin x=\\frac{5t^{2}+8t+5}{1+t^{2}}", "\\int_{0}^{1}\\frac{2\\,dt}{5t^{2}+8t+5}=\\frac23\\left[\\arctan\\frac{5t+4}{3}\\right]_{0}^{1}", "=\\frac23\\left(\\arctan3-\\arctan\\tfrac43\\right)=\\frac23\\arctan\\frac13"], "h": "Complete the square in $5t^{2}+8t+5$.", "ht": "ทำกำลังสองสมบูรณ์ใน $5t^{2}+8t+5$", "v": 0.21450036959776148}]}, {"id": "feyn", "u": "F", "n": "Feynman's trick", "nt": "Feynman's trick", "thm": [{"en": "<b>Theorem (Leibniz integral rule).</b> Let $f$ and $\\dfrac{\\partial f}{\\partial t}$ be continuous on the rectangle $[a,b]\\times[c,d]$. Then $I(t)=\\displaystyle\\int_{a}^{b}f(x,t)\\,dx$ is differentiable on $[c,d]$ and <span class=\"mdisp\">$\\displaystyle I'(t)=\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx.$</span>", "th": "<b>ทฤษฎีบท (กฎอินทิกรัลของไลบ์นิซ)</b> ให้ $f$ และ $\\dfrac{\\partial f}{\\partial t}$ ต่อเนื่องบนสี่เหลี่ยม $[a,b]\\times[c,d]$ แล้ว $I(t)=\\displaystyle\\int_{a}^{b}f(x,t)\\,dx$ หาอนุพันธ์ได้บน $[c,d]$ และ <span class=\"mdisp\">$\\displaystyle I'(t)=\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx$</span>"}, {"en": "<b>Improper integrals</b> (e.g. over $[0,\\infty)$, or with a singular endpoint): the same conclusion holds if there is $g$ with $\\displaystyle\\int g&lt;\\infty$ and $\\left|\\frac{\\partial f}{\\partial t}(x,t)\\right|\\le g(x)$ for all $t$ in the interval (a consequence of the <b>dominated convergence theorem</b>, which we quote).", "th": "<b>อินทิกรัลไม่ตรงแบบ</b> (เช่นบน $[0,\\infty)$ หรือมีจุดเอกฐานที่ปลาย): ข้อสรุปเดียวกันเป็นจริงถ้ามี $g$ ที่ $\\displaystyle\\int g&lt;\\infty$ และ $\\left|\\frac{\\partial f}{\\partial t}(x,t)\\right|\\le g(x)$ ทุก $t$ ในช่วง (ผลจาก<b>ทฤษฎีบทการลู่เข้าแบบถูกครอบงำ</b> ซึ่งเราอ้างถึง)"}], "proof": [{"en": "Fix $t$ and $h\\neq0$ with $t+h\\in[c,d]$. For each $x$, the mean value theorem in the variable $t$ gives $\\theta=\\theta(x,h)\\in(0,1)$ with", "th": "กำหนด $t$ และ $h\\neq0$ ที่ $t+h\\in[c,d]$ สำหรับแต่ละ $x$ ทฤษฎีบทค่าเฉลี่ยในตัวแปร $t$ ให้ $\\theta=\\theta(x,h)\\in(0,1)$ ที่", "m": "\\frac{f(x,t+h)-f(x,t)}{h}=\\frac{\\partial f}{\\partial t}(x,t+\\theta h)."}, {"en": "$\\frac{\\partial f}{\\partial t}$ is continuous on a closed bounded rectangle, so it is <b>uniformly continuous</b>: for every $\\varepsilon&gt;0$ there is $\\delta&gt;0$ such that $|s-t|&lt;\\delta$ implies, for <i>all</i> $x$,", "th": "$\\frac{\\partial f}{\\partial t}$ ต่อเนื่องบนสี่เหลี่ยมปิดและมีขอบเขต จึง<b>ต่อเนื่องเอกรูป</b>: ทุก $\\varepsilon&gt;0$ มี $\\delta&gt;0$ ที่ $|s-t|&lt;\\delta$ ทำให้ สำหรับ<i>ทุก</i> $x$", "m": "\\left|\\frac{\\partial f}{\\partial t}(x,s)-\\frac{\\partial f}{\\partial t}(x,t)\\right|&lt;\\varepsilon."}, {"en": "The difference quotient is continuous in $x$, so integrable. For $0&lt;|h|&lt;\\delta$ (so $|\\theta h|&lt;\\delta$):", "th": "ผลหารผลต่างต่อเนื่องใน $x$ จึงอินทิเกรตได้ สำหรับ $0&lt;|h|&lt;\\delta$ (ดังนั้น $|\\theta h|&lt;\\delta$):", "m": "\\left|\\frac{I(t+h)-I(t)}{h}-\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx\\right|\\le\\int_{a}^{b}\\left|\\frac{\\partial f}{\\partial t}(x,t+\\theta h)-\\frac{\\partial f}{\\partial t}(x,t)\\right|dx\\le\\varepsilon(b-a)."}, {"en": "$\\varepsilon$ was arbitrary, so the limit as $h\\to0$ exists and equals $\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx$. $\\blacksquare$", "th": "$\\varepsilon$ เป็นค่าใดก็ได้ ลิมิตเมื่อ $h\\to0$ จึงมีค่าและเท่ากับ $\\int_{a}^{b}\\frac{\\partial f}{\\partial t}(x,t)\\,dx$ $\\blacksquare$", "m": ""}, {"en": "<b>Method.</b> Put a parameter $t$ into the integral so that $\\frac{\\partial f}{\\partial t}$ is easy, find $I'(t)$, integrate in $t$, and fix the constant with an easy value of $t$ (check the conditions above).", "th": "<b>วิธีใช้</b> ใส่พารามิเตอร์ $t$ ลงในอินทิกรัลให้ $\\frac{\\partial f}{\\partial t}$ ง่าย หา $I'(t)$ อินทิเกรตเทียบ $t$ แล้วหาค่าคงตัวจากค่า $t$ ที่ง่าย (ตรวจเงื่อนไขข้างต้น)", "m": ""}], "ex": [{"q": "\\int_{0}^{1}\\frac{x^{2}-1}{\\ln x}\\,dx", "al": "\\ln3", "s": ["I(t)=\\int_{0}^{1}\\frac{x^{t}-1}{\\ln x}dx,\\ \\ \\frac{\\partial}{\\partial t}\\frac{x^{t}-1}{\\ln x}=x^{t}", "I'(t)=\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1},\\ I(0)=0", "I(t)=\\ln(t+1),\\ I(2)=\\ln3"]}, {"q": "\\int_{0}^{1}x^{2}\\ln x\\,dx", "al": "-\\frac19", "s": ["\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}\\ (t&gt;-1)", "\\frac{d}{dt}:\\ \\int_{0}^{1}x^{t}\\ln x\\,dx=-\\frac{1}{(t+1)^{2}}", "t=2:\\ -\\frac19"]}], "pr": [{"q": "\\int_{0}^{1}x^{3}\\ln x\\,dx", "al": "-\\frac{1}{16}", "s": ["\\int_{0}^{1}x^{t}\\ln x\\,dx=-\\frac{1}{(t+1)^{2}}", "t=3:\\ -\\frac{1}{16}"], "h": "Differentiate $\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}$ with respect to $t$.", "ht": "หาอนุพันธ์ $\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}$ เทียบ $t$", "v": -0.0625}, {"q": "\\int_{0}^{1}\\frac{x^{5}-1}{\\ln x}\\,dx", "al": "\\ln6", "s": ["I(t)=\\ln(t+1)", "I(5)=\\ln6"], "h": "Same $I(t)$ as the first example.", "ht": "ใช้ $I(t)$ เดียวกับตัวอย่างแรก", "v": 1.791759469228055}, {"q": "\\int_{0}^{\\infty}xe^{-3x}\\,dx", "al": "\\frac19", "s": ["\\int_{0}^{\\infty}e^{-tx}dx=\\frac1t\\ (t&gt;0)", "-\\frac{d}{dt}:\\ \\int_{0}^{\\infty}xe^{-tx}dx=\\frac{1}{t^{2}},\\ t=3"], "h": "Start from $\\int_{0}^{\\infty}e^{-tx}dx=\\frac1t$.", "ht": "เริ่มจาก $\\int_{0}^{\\infty}e^{-tx}dx=\\frac1t$", "v": 0.1111111111111111}, {"q": "\\int_{0}^{1}x^{2}(\\ln x)^{2}\\,dx", "al": "\\frac{2}{27}", "s": ["\\frac{d^{2}}{dt^{2}}\\frac{1}{t+1}=\\frac{2}{(t+1)^{3}}=\\int_{0}^{1}x^{t}(\\ln x)^{2}dx", "t=2:\\ \\frac{2}{27}"], "h": "Differentiate twice.", "ht": "หาอนุพันธ์สองครั้ง", "v": 0.07407407407407407}, {"q": "\\int_{0}^{\\frac\\pi2}\\ln\\left(4\\cos^{2}x+\\sin^{2}x\\right)dx", "al": "\\pi\\ln\\frac32", "s": ["I(a)=\\int_{0}^{\\frac\\pi2}\\ln\\left(a^{2}\\cos^{2}x+\\sin^{2}x\\right)dx,\\ a&gt;0", "I'(a)=\\int_{0}^{\\frac\\pi2}\\frac{2a\\cos^{2}x}{a^{2}\\cos^{2}x+\\sin^{2}x}dx=\\frac{\\pi}{a+1}\\ \\ (t=\\tan x)", "I(1)=0\\Rightarrow I(a)=\\pi\\ln\\frac{a+1}{2},\\ \\ I(2)=\\pi\\ln\\frac32"], "h": "Put $a^{2}$ in front of $\\cos^{2}x$; $I(1)=0$.", "ht": "ใส่ $a^{2}$ หน้า $\\cos^{2}x$ และ $I(1)=0$", "v": 1.2738062049196006}]}, {"id": "series", "u": "F", "n": "Integrating a series term by term", "nt": "อินทิเกรตอนุกรมทีละพจน์", "thm": [{"en": "<b>Theorem.</b> (i) If each $f_n$ is continuous on $[a,b]$ and $\\sum f_n$ converges <b>uniformly</b> on $[a,b]$, then $\\displaystyle\\int_{a}^{b}\\sum_{n}f_n=\\sum_{n}\\int_{a}^{b}f_n$. (ii) If $f_n\\ge0$ on $(a,b)$ (bounded or not), then $\\displaystyle\\int_{a}^{b}\\sum f_n=\\sum\\int_{a}^{b}f_n$, both sides possibly $+\\infty$ (<b>monotone convergence theorem</b>, quoted).", "th": "<b>ทฤษฎีบท</b> (i) ถ้า $f_n$ แต่ละตัวต่อเนื่องบน $[a,b]$ และ $\\sum f_n$ ลู่เข้า<b>เอกรูป</b>บน $[a,b]$ แล้ว $\\displaystyle\\int_{a}^{b}\\sum_{n}f_n=\\sum_{n}\\int_{a}^{b}f_n$ (ii) ถ้า $f_n\\ge0$ บน $(a,b)$ (มีขอบเขตหรือไม่ก็ได้) แล้ว $\\displaystyle\\int_{a}^{b}\\sum f_n=\\sum\\int_{a}^{b}f_n$ ทั้งสองข้างอาจเป็น $+\\infty$ (<b>ทฤษฎีบทการลู่เข้าแบบทางเดียว</b> ซึ่งเราอ้างถึง)"}, {"en": "We also quote the <b>Basel result</b> (Euler): $\\displaystyle\\sum_{n=1}^{\\infty}\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}$ (one proof uses Fourier series), and the <b>geometric series</b> $\\dfrac{1}{1-x}=\\sum_{n\\ge0}x^{n}$ for $|x|&lt;1$.", "th": "เราอ้างถึง<b>ผลของบาเซิล</b> (ออยเลอร์): $\\displaystyle\\sum_{n=1}^{\\infty}\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}$ (พิสูจน์ได้ด้วยอนุกรมฟูริเยร์) และ<b>อนุกรมเรขาคณิต</b> $\\dfrac{1}{1-x}=\\sum_{n\\ge0}x^{n}$ เมื่อ $|x|&lt;1$"}], "proof": [{"en": "(i) Let $S=\\sum f_n$ and $S_N=\\sum_{n\\le N}f_n$. A uniform limit of continuous functions is continuous, so $S$ is integrable, and by linearity $\\int S_N=\\sum_{n\\le N}\\int f_n$.", "th": "(i) ให้ $S=\\sum f_n$ และ $S_N=\\sum_{n\\le N}f_n$ ลิมิตเอกรูปของฟังก์ชันต่อเนื่องเป็นฟังก์ชันต่อเนื่อง $S$ จึงอินทิเกรตได้ และจากความเป็นเชิงเส้น $\\int S_N=\\sum_{n\\le N}\\int f_n$", "m": ""}, {"en": "Uniform convergence means $\\sup_{[a,b]}|S-S_N|\\to0$, so", "th": "การลู่เข้าเอกรูปหมายถึง $\\sup_{[a,b]}|S-S_N|\\to0$ ดังนั้น", "m": "\\left|\\int_{a}^{b}S-\\sum_{n\\le N}\\int_{a}^{b}f_n\\right|=\\left|\\int_{a}^{b}(S-S_N)\\right|\\le(b-a)\\sup_{[a,b]}|S-S_N|\\to0."}, {"en": "(ii) is the monotone convergence theorem applied to the increasing partial sums $S_N\\ge0$; we quote it.", "th": "(ii) คือทฤษฎีบทการลู่เข้าแบบทางเดียวกับผลบวกย่อย $S_N\\ge0$ ที่เพิ่มขึ้น เราอ้างถึง", "m": ""}, {"en": "<b>Consequence.</b> From Basel, splitting even and odd $n$:", "th": "<b>ผลที่ตามมา</b> จากผลของบาเซิล แยก $n$ คู่และคี่:", "m": "\\sum_{n\\ge1}\\frac{(-1)^{n-1}}{n^{2}}=\\sum\\frac{1}{n^{2}}-2\\sum\\frac{1}{(2n)^{2}}=\\left(1-\\tfrac12\\right)\\frac{\\pi^{2}}{6}=\\frac{\\pi^{2}}{12}.\\ \\blacksquare"}, {"en": "<b>Note on alternating series.</b> When the terms change sign on an open interval, use (i) on $[0,r]$ with $r&lt;1$ and let $r\\to1^{-}$, or quote dominated convergence.", "th": "<b>หมายเหตุเรื่องอนุกรมสลับ</b> เมื่อพจน์เปลี่ยนเครื่องหมายบนช่วงเปิด ใช้ (i) บน $[0,r]$ โดย $r&lt;1$ แล้วให้ $r\\to1^{-}$ หรืออ้างทฤษฎีบทการลู่เข้าแบบถูกครอบงำ", "m": ""}], "ex": [{"q": "\\int_{0}^{1}\\frac{\\ln(1-x)}{x}\\,dx", "al": "-\\frac{\\pi^{2}}{6}", "s": ["-\\frac{\\ln(1-x)}{x}=\\sum_{n\\ge1}\\frac{x^{n-1}}{n}\\ \\ (\\text{terms}\\ge0:\\text{ theorem (ii)})", "\\int_{0}^{1}=\\sum\\frac{1}{n}\\cdot\\frac{1}{n}=\\frac{\\pi^{2}}{6}", "\\text{so the integral is }-\\frac{\\pi^{2}}{6}"]}, {"q": "\\int_{0}^{\\infty}\\frac{x}{e^{x}-1}\\,dx", "al": "\\frac{\\pi^{2}}{6}", "s": ["\\frac{x}{e^{x}-1}=\\sum_{n\\ge1}xe^{-nx}\\ (x&gt;0,\\ \\text{terms}\\ge0)", "\\int_{0}^{\\infty}xe^{-nx}dx=\\frac{1}{n^{2}}", "\\sum\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}"]}], "pr": [{"q": "\\int_{0}^{1}\\frac{\\ln\\left(1-x^{2}\\right)}{x}\\,dx", "al": "-\\frac{\\pi^{2}}{12}", "s": ["-\\frac{\\ln(1-x^{2})}{x}=\\sum_{n\\ge1}\\frac{x^{2n-1}}{n}", "\\int_{0}^{1}=\\sum\\frac{1}{n\\cdot2n}=\\frac12\\cdot\\frac{\\pi^{2}}{6}", "I=-\\frac{\\pi^{2}}{12}"], "h": "$\\ln(1-u)=-\\sum\\frac{u^{n}}{n}$ with $u=x^{2}$.", "ht": "$\\ln(1-u)=-\\sum\\frac{u^{n}}{n}$ โดย $u=x^{2}$", "v": -0.8224670334241132}, {"q": "\\int_{0}^{\\infty}\\frac{x}{e^{2x}-1}\\,dx", "al": "\\frac{\\pi^{2}}{24}", "s": ["u=2x:\\ \\frac14\\int_{0}^{\\infty}\\frac{u}{e^{u}-1}du", "=\\frac14\\cdot\\frac{\\pi^{2}}{6}=\\frac{\\pi^{2}}{24}"], "h": "Substitute $u=2x$ and use the second example.", "ht": "แทน $u=2x$ แล้วใช้ตัวอย่างที่สอง", "v": 0.4112335167120566}, {"q": "\\int_{0}^{1}\\frac{\\ln x}{1-x}\\,dx", "al": "-\\frac{\\pi^{2}}{6}", "s": ["\\frac{-\\ln x}{1-x}=\\sum_{n\\ge0}(-\\ln x)x^{n}\\ (\\text{terms}\\ge0)", "\\int_{0}^{1}x^{n}(-\\ln x)\\,dx=\\frac{1}{(n+1)^{2}}", "I=-\\frac{\\pi^{2}}{6}"], "h": "Expand $\\frac{1}{1-x}$; $\\int_{0}^{1}x^{n}\\ln x\\,dx=-\\frac{1}{(n+1)^{2}}$.", "ht": "กระจาย $\\frac{1}{1-x}$ และ $\\int_{0}^{1}x^{n}\\ln x\\,dx=-\\frac{1}{(n+1)^{2}}$", "v": -1.6449340668482264}, {"q": "\\int_{0}^{\\infty}\\frac{x}{e^{x}+1}\\,dx", "al": "\\frac{\\pi^{2}}{12}", "s": ["\\frac{x}{e^{x}+1}=\\sum_{n\\ge1}(-1)^{n-1}xe^{-nx}", "\\sum\\frac{(-1)^{n-1}}{n^{2}}=\\frac{\\pi^{2}}{12}"], "h": "Alternating version of the second example.", "ht": "แบบสลับเครื่องหมายของตัวอย่างที่สอง", "v": 0.8224670334241132}, {"q": "\\int_{0}^{\\infty}\\ln\\left(1+e^{-x}\\right)dx", "al": "\\frac{\\pi^{2}}{12}", "s": ["\\ln(1+u)=\\sum_{n\\ge1}\\frac{(-1)^{n-1}u^{n}}{n},\\ u=e^{-x}", "\\int_{0}^{\\infty}e^{-nx}dx=\\frac1n:\\ \\sum\\frac{(-1)^{n-1}}{n^{2}}=\\frac{\\pi^{2}}{12}"], "h": "Expand $\\ln(1+u)$ with $u=e^{-x}$.", "ht": "กระจาย $\\ln(1+u)$ โดย $u=e^{-x}$", "v": 0.8224670334241132}]}, {"id": "frul", "u": "F", "n": "Frullani's integral", "nt": "อินทิกรัลของฟรุลลานี", "thm": [{"en": "<b>Theorem (Frullani).</b> Let $f$ be continuous on $[0,\\infty)$ with a finite limit $f(\\infty)=\\displaystyle\\lim_{x\\to\\infty}f(x)$, and let $a,b&gt;0$. Then <span class=\"mdisp\">$\\displaystyle \\int_{0}^{\\infty}\\frac{f(ax)-f(bx)}{x}\\,dx=\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba.$</span>", "th": "<b>ทฤษฎีบท (ฟรุลลานี)</b> ให้ $f$ ต่อเนื่องบน $[0,\\infty)$ และมีลิมิตจำกัด $f(\\infty)=\\displaystyle\\lim_{x\\to\\infty}f(x)$ และ $a,b&gt;0$ แล้ว <span class=\"mdisp\">$\\displaystyle \\int_{0}^{\\infty}\\frac{f(ax)-f(bx)}{x}\\,dx=\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba$</span>"}], "proof": [{"en": "Take $0&lt;\\varepsilon&lt;R$. Substitute $u=ax$ in the first part and $u=bx$ in the second (each $\\frac{dx}{x}=\\frac{du}{u}$):", "th": "ให้ $0&lt;\\varepsilon&lt;R$ แทน $u=ax$ ในส่วนแรกและ $u=bx$ ในส่วนที่สอง (ทั้งคู่ $\\frac{dx}{x}=\\frac{du}{u}$):", "m": "\\int_{\\varepsilon}^{R}\\frac{f(ax)-f(bx)}{x}\\,dx=\\int_{a\\varepsilon}^{aR}\\frac{f(u)}{u}\\,du-\\int_{b\\varepsilon}^{bR}\\frac{f(u)}{u}\\,du."}, {"en": "The overlapping part cancels, leaving", "th": "ส่วนที่ซ้อนทับกันหักล้างกัน เหลือ", "m": "=\\int_{a\\varepsilon}^{b\\varepsilon}\\frac{f(u)}{u}\\,du-\\int_{aR}^{bR}\\frac{f(u)}{u}\\,du."}, {"en": "Weighted mean value theorem for integrals (weight $\\frac1u&gt;0$; lesson 12): there are $c_\\varepsilon$ between $a\\varepsilon$ and $b\\varepsilon$, and $C_R$ between $aR$ and $bR$, with", "th": "ทฤษฎีบทค่าเฉลี่ยถ่วงน้ำหนัก (น้ำหนัก $\\frac1u&gt;0$; บทที่ 12): มี $c_\\varepsilon$ ระหว่าง $a\\varepsilon$ กับ $b\\varepsilon$ และ $C_R$ ระหว่าง $aR$ กับ $bR$ ที่", "m": "\\int_{a\\varepsilon}^{b\\varepsilon}\\frac{f(u)}{u}du=f(c_\\varepsilon)\\ln\\frac ba,\\qquad \\int_{aR}^{bR}\\frac{f(u)}{u}du=f(C_R)\\ln\\frac ba."}, {"en": "As $\\varepsilon\\to0^{+}$, $c_\\varepsilon\\to0$ so $f(c_\\varepsilon)\\to f(0)$ (continuity); as $R\\to\\infty$, $C_R\\to\\infty$ so $f(C_R)\\to f(\\infty)$. Both limits exist, so the improper integral converges to $\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba$. $\\blacksquare$", "th": "เมื่อ $\\varepsilon\\to0^{+}$ จะได้ $c_\\varepsilon\\to0$ ดังนั้น $f(c_\\varepsilon)\\to f(0)$ (ความต่อเนื่อง) เมื่อ $R\\to\\infty$ จะได้ $C_R\\to\\infty$ ดังนั้น $f(C_R)\\to f(\\infty)$ ลิมิตทั้งสองมีค่า อินทิกรัลจึงลู่เข้าสู่ $\\big(f(0)-f(\\infty)\\big)\\ln\\frac ba$ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{\\infty}\\frac{e^{-x}-e^{-3x}}{x}\\,dx", "al": "\\ln3", "s": ["f=e^{-x},\\ f(0)=1,\\ f(\\infty)=0,\\ a=1,\\ b=3", "(1-0)\\ln3=\\ln3"]}, {"q": "\\int_{0}^{\\infty}\\frac{\\arctan3x-\\arctan x}{x}\\,dx", "al": "\\frac\\pi2\\ln3", "s": ["f=\\arctan,\\ f(0)=0,\\ f(\\infty)=\\tfrac\\pi2,\\ a=3,\\ b=1", "\\left(0-\\tfrac\\pi2\\right)\\ln\\tfrac13=\\frac\\pi2\\ln3"]}], "pr": [{"q": "\\int_{0}^{\\infty}\\frac{e^{-2x}-e^{-5x}}{x}\\,dx", "al": "\\ln\\frac52", "s": ["f=e^{-x},\\ a=2,\\ b=5:\\ (1-0)\\ln\\frac52"], "h": "$f(x)=e^{-x}$, $a=2$, $b=5$.", "ht": "$f(x)=e^{-x}$, $a=2$, $b=5$", "v": 0.9162907318741551}, {"q": "\\int_{0}^{\\infty}\\frac{\\arctan2x-\\arctan x}{x}\\,dx", "al": "\\frac\\pi2\\ln2", "s": ["\\left(0-\\tfrac\\pi2\\right)\\ln\\tfrac12=\\frac\\pi2\\ln2"], "h": "Like the second example with $a=2$.", "ht": "เหมือนตัวอย่างที่สองโดย $a=2$", "v": 1.088793045151801}, {"q": "\\int_{0}^{\\infty}\\frac{1}{x}\\left(\\frac{1}{1+2x}-\\frac{1}{1+3x}\\right)dx", "al": "\\ln\\frac32", "s": ["f(x)=\\frac{1}{1+x},\\ f(0)=1,\\ f(\\infty)=0", "a=2,\\ b=3:\\ \\ln\\frac32"], "h": "$f(x)=\\frac{1}{1+x}$.", "ht": "$f(x)=\\frac{1}{1+x}$", "v": 0.4054651081081644}, {"q": "\\int_{0}^{\\infty}\\frac{e^{-x}-e^{-\\frac x2}}{x}\\,dx", "al": "-\\ln2", "s": ["a=1,\\ b=\\tfrac12:\\ (1-0)\\ln\\tfrac12=-\\ln2"], "h": "$b=\\frac12$, so $\\ln\\frac ba&lt;0$.", "ht": "$b=\\frac12$ ดังนั้น $\\ln\\frac ba&lt;0$", "v": -0.6931471805599453}, {"q": "\\int_{0}^{\\infty}\\frac{\\tanh3x-\\tanh x}{x}\\,dx", "al": "\\ln3", "s": ["f=\\tanh,\\ f(0)=0,\\ f(\\infty)=1,\\ a=3,\\ b=1", "(0-1)\\ln\\tfrac13=\\ln3"], "h": "$\\tanh x\\to1$ as $x\\to\\infty$.", "ht": "$\\tanh x\\to1$ เมื่อ $x\\to\\infty$", "v": 1.0986122886681098}]}, {"id": "gauss", "u": "F", "n": "The Gaussian integral", "nt": "อินทิกรัลเกาส์เซียน", "thm": [{"en": "<b>Theorem.</b> <span class=\"mdisp\">$\\displaystyle \\int_{-\\infty}^{\\infty}e^{-x^{2}}\\,dx=\\sqrt\\pi,\\qquad\\text{and for }a&gt;0,\\ \\int_{-\\infty}^{\\infty}e^{-ax^{2}}\\,dx=\\sqrt{\\frac\\pi a}.$</span>", "th": "<b>ทฤษฎีบท</b> <span class=\"mdisp\">$\\displaystyle \\int_{-\\infty}^{\\infty}e^{-x^{2}}\\,dx=\\sqrt\\pi\\qquad\\text{และสำหรับ }a&gt;0,\\ \\int_{-\\infty}^{\\infty}e^{-ax^{2}}\\,dx=\\sqrt{\\frac\\pi a}$</span>"}, {"en": "We quote the <b>change of variables to polar coordinates</b> for double integrals: $\\iint_{D}g(x,y)\\,dx\\,dy=\\iint g(r\\cos\\theta,r\\sin\\theta)\\,r\\,dr\\,d\\theta$ for continuous $g$ on a bounded region $D$.", "th": "เราอ้างถึง<b>การเปลี่ยนตัวแปรเป็นพิกัดเชิงขั้ว</b>สำหรับอินทิกรัลสองชั้น: $\\iint_{D}g(x,y)\\,dx\\,dy=\\iint g(r\\cos\\theta,r\\sin\\theta)\\,r\\,dr\\,d\\theta$ สำหรับ $g$ ต่อเนื่องบนบริเวณ $D$ ที่มีขอบเขต"}], "proof": [{"en": "<b>Convergence.</b> $0&lt;e^{-x^{2}}\\le e^{-x}$ for $x\\ge1$ and $\\int_{1}^{\\infty}e^{-x}dx=e^{-1}$, so $I=\\int_{0}^{\\infty}e^{-x^{2}}dx$ converges (comparison test).", "th": "<b>การลู่เข้า</b> $0&lt;e^{-x^{2}}\\le e^{-x}$ เมื่อ $x\\ge1$ และ $\\int_{1}^{\\infty}e^{-x}dx=e^{-1}$ ดังนั้น $I=\\int_{0}^{\\infty}e^{-x^{2}}dx$ ลู่เข้า (การทดสอบโดยการเปรียบเทียบ)", "m": ""}, {"en": "Let $I_R=\\int_{0}^{R}e^{-x^{2}}dx$. Over the square $S_R=[0,R]^{2}$ the integrand factorises:", "th": "ให้ $I_R=\\int_{0}^{R}e^{-x^{2}}dx$ บนสี่เหลี่ยมจัตุรัส $S_R=[0,R]^{2}$ ฟังก์ชันแยกตัวประกอบได้:", "m": "\\iint_{S_R}e^{-(x^{2}+y^{2})}\\,dx\\,dy=\\int_{0}^{R}e^{-x^{2}}dx\\int_{0}^{R}e^{-y^{2}}dy=I_R^{2}."}, {"en": "Let $D_R$ be the quarter disc of radius $R$ in the first quadrant. In polar coordinates,", "th": "ให้ $D_R$ เป็นหนึ่งในสี่ของวงกลมรัศมี $R$ ในจตุภาคที่หนึ่ง ในพิกัดเชิงขั้ว", "m": "\\iint_{D_R}e^{-(x^{2}+y^{2})}dx\\,dy=\\int_{0}^{\\frac\\pi2}\\int_{0}^{R}e^{-r^{2}}r\\,dr\\,d\\theta=\\frac\\pi4\\left(1-e^{-R^{2}}\\right)."}, {"en": "$D_R\\subset S_R\\subset D_{R\\sqrt2}$ and the integrand is positive, so", "th": "$D_R\\subset S_R\\subset D_{R\\sqrt2}$ และฟังก์ชันเป็นบวก ดังนั้น", "m": "\\frac\\pi4\\left(1-e^{-R^{2}}\\right)\\le I_R^{2}\\le\\frac\\pi4\\left(1-e^{-2R^{2}}\\right)."}, {"en": "Let $R\\to\\infty$: by the squeeze theorem $I^{2}=\\frac\\pi4$, and $I&gt;0$, so $I=\\frac{\\sqrt\\pi}{2}$. The integrand is even, so $\\int_{-\\infty}^{\\infty}=\\sqrt\\pi$. For $a&gt;0$ substitute $x=\\frac{u}{\\sqrt a}$. $\\blacksquare$", "th": "ให้ $R\\to\\infty$: จากทฤษฎีบทการบีบ $I^{2}=\\frac\\pi4$ และ $I&gt;0$ ดังนั้น $I=\\frac{\\sqrt\\pi}{2}$ ฟังก์ชันเป็นคู่จึง $\\int_{-\\infty}^{\\infty}=\\sqrt\\pi$ สำหรับ $a&gt;0$ แทน $x=\\frac{u}{\\sqrt a}$ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{\\infty}e^{-x^{2}}\\,dx", "al": "\\frac{\\sqrt\\pi}{2}", "s": ["\\text{Half of }\\sqrt\\pi\\text{ (even function)}"]}, {"q": "\\int_{0}^{\\infty}x^{2}e^{-x^{2}}\\,dx", "al": "\\frac{\\sqrt\\pi}{4}", "s": ["u=x,\\ v'=xe^{-x^{2}},\\ v=-\\tfrac12e^{-x^{2}}", "\\left[-\\tfrac x2e^{-x^{2}}\\right]_{0}^{\\infty}+\\tfrac12\\int_{0}^{\\infty}e^{-x^{2}}dx=0+\\tfrac12\\cdot\\tfrac{\\sqrt\\pi}{2}=\\frac{\\sqrt\\pi}{4}"]}], "pr": [{"q": "\\int_{-\\infty}^{\\infty}e^{-x^{2}}\\,dx", "al": "\\sqrt\\pi", "s": ["\\sqrt\\pi\\ \\text{(the theorem)}"], "h": "This is the theorem itself.", "ht": "นี่คือทฤษฎีบทโดยตรง", "v": 1.772453850905516}, {"q": "\\int_{0}^{\\infty}e^{-4x^{2}}\\,dx", "al": "\\frac{\\sqrt\\pi}{4}", "s": ["\\tfrac12\\sqrt{\\tfrac\\pi4}=\\frac{\\sqrt\\pi}{4}"], "h": "$a=4$, then halve.", "ht": "$a=4$ แล้วหารครึ่ง", "v": 0.443113462726379}, {"q": "\\int_{-\\infty}^{\\infty}e^{-x^{2}+2x}\\,dx", "al": "e\\sqrt\\pi", "s": ["-x^{2}+2x=-(x-1)^{2}+1", "e\\int_{-\\infty}^{\\infty}e^{-(x-1)^{2}}dx=e\\sqrt\\pi"], "h": "Complete the square in the exponent.", "ht": "ทำกำลังสองสมบูรณ์ในเลขชี้กำลัง", "v": 4.818029094698722}, {"q": "\\int_{-\\infty}^{\\infty}x^{2}e^{-x^{2}}\\,dx", "al": "\\frac{\\sqrt\\pi}{2}", "s": ["\\text{Even: }2\\cdot\\frac{\\sqrt\\pi}{4}=\\frac{\\sqrt\\pi}{2}"], "h": "Use the second example and symmetry.", "ht": "ใช้ตัวอย่างที่สองและความสมมาตร", "v": 0.886226925452758}, {"q": "\\int_{0}^{\\infty}\\frac{e^{-x}}{\\sqrt x}\\,dx", "al": "\\sqrt\\pi", "s": ["x=u^{2},\\ dx=2u\\,du:\\ \\int_{0}^{\\infty}\\frac{e^{-u^{2}}}{u}2u\\,du", "=2\\int_{0}^{\\infty}e^{-u^{2}}du=\\sqrt\\pi"], "h": "Let $x=u^{2}$.", "ht": "ให้ $x=u^{2}$", "v": 1.772453850905516}]}, {"id": "gamma", "u": "F", "n": "Gamma and Beta functions", "nt": "ฟังก์ชันแกมมาและบีตา", "thm": [{"en": "<b>Definitions.</b> For $s&gt;0$: $\\Gamma(s)=\\displaystyle\\int_{0}^{\\infty}x^{s-1}e^{-x}\\,dx$. For $m,n&gt;0$: $B(m,n)=\\displaystyle\\int_{0}^{1}x^{m-1}(1-x)^{n-1}\\,dx$.", "th": "<b>นิยาม</b> สำหรับ $s&gt;0$: $\\Gamma(s)=\\displaystyle\\int_{0}^{\\infty}x^{s-1}e^{-x}\\,dx$ สำหรับ $m,n&gt;0$: $B(m,n)=\\displaystyle\\int_{0}^{1}x^{m-1}(1-x)^{n-1}\\,dx$"}, {"en": "<b>Theorem.</b> (i) $\\Gamma(s)$ converges for $s&gt;0$; (ii) $\\Gamma(s+1)=s\\,\\Gamma(s)$, so $\\Gamma(n+1)=n!$; (iii) $\\Gamma\\left(\\tfrac12\\right)=\\sqrt\\pi$; (iv) <span class=\"mdisp\">$\\displaystyle B(m,n)=\\frac{\\Gamma(m)\\Gamma(n)}{\\Gamma(m+n)};$</span> (v) $\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta=\\tfrac12B(m,n)$.", "th": "<b>ทฤษฎีบท</b> (i) $\\Gamma(s)$ ลู่เข้าเมื่อ $s&gt;0$ (ii) $\\Gamma(s+1)=s\\,\\Gamma(s)$ ดังนั้น $\\Gamma(n+1)=n!$ (iii) $\\Gamma\\left(\\tfrac12\\right)=\\sqrt\\pi$ (iv) <span class=\"mdisp\">$\\displaystyle B(m,n)=\\frac{\\Gamma(m)\\Gamma(n)}{\\Gamma(m+n)}$</span> (v) $\\displaystyle\\int_{0}^{\\frac\\pi2}\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta=\\tfrac12B(m,n)$"}], "proof": [{"en": "(i) On $(0,1]$: $x^{s-1}e^{-x}\\le x^{s-1}$ and $\\int_{0}^{1}x^{s-1}dx$ is finite (it equals $\\frac1s$). On $[1,\\infty)$: $x^{s-1}e^{-x/2}$ is bounded (it tends to $0$), say by $M$, so $x^{s-1}e^{-x}\\le Me^{-x/2}$, which is integrable. Comparison gives convergence.", "th": "(i) บน $(0,1]$: $x^{s-1}e^{-x}\\le x^{s-1}$ และ $\\int_{0}^{1}x^{s-1}dx$ มีค่าจำกัด (เท่ากับ $\\frac1s$) บน $[1,\\infty)$: $x^{s-1}e^{-x/2}$ มีขอบเขต (เข้าใกล้ $0$) เช่นโดย $M$ ดังนั้น $x^{s-1}e^{-x}\\le Me^{-x/2}$ ซึ่งอินทิเกรตได้ จากการเปรียบเทียบจึงลู่เข้า", "m": ""}, {"en": "(ii) Parts on $[\\varepsilon,R]$ with $u=x^{s}$, $v'=e^{-x}$, then let $\\varepsilon\\to0$, $R\\to\\infty$ (the boundary terms $\\to0$ as $s&gt;0$):", "th": "(ii) ทีละส่วนบน $[\\varepsilon,R]$ โดย $u=x^{s}$, $v'=e^{-x}$ แล้วให้ $\\varepsilon\\to0$, $R\\to\\infty$ (พจน์ขอบ $\\to0$ เพราะ $s&gt;0$):", "m": "\\Gamma(s+1)=\\Big[-x^{s}e^{-x}\\Big]_{0}^{\\infty}+s\\int_{0}^{\\infty}x^{s-1}e^{-x}dx=s\\,\\Gamma(s)."}, {"en": "With $\\Gamma(1)=\\int_{0}^{\\infty}e^{-x}dx=1$, induction gives $\\Gamma(n+1)=n!$. (iii) Put $x=u^{2}$: $\\Gamma\\left(\\tfrac12\\right)=\\int_{0}^{\\infty}\\frac{e^{-u^{2}}}{u}2u\\,du=2\\cdot\\frac{\\sqrt\\pi}{2}$ (lesson 25).", "th": "เนื่องจาก $\\Gamma(1)=\\int_{0}^{\\infty}e^{-x}dx=1$ อุปนัยให้ $\\Gamma(n+1)=n!$ (iii) แทน $x=u^{2}$: $\\Gamma\\left(\\tfrac12\\right)=\\int_{0}^{\\infty}\\frac{e^{-u^{2}}}{u}2u\\,du=2\\cdot\\frac{\\sqrt\\pi}{2}$ (บทที่ 25)", "m": ""}, {"en": "(iv) The integrand below is non-negative, so by <b>Tonelli's theorem</b> (quoted) we may write the product as a double integral over $(0,\\infty)^{2}$:", "th": "(iv) ฟังก์ชันข้างล่างไม่เป็นลบ จาก<b>ทฤษฎีบทของโทเนลลี</b> (อ้างถึง) เขียนผลคูณเป็นอินทิกรัลสองชั้นบน $(0,\\infty)^{2}$ ได้:", "m": "\\Gamma(m)\\Gamma(n)=\\iint x^{m-1}y^{n-1}e^{-(x+y)}\\,dx\\,dy."}, {"en": "Change variables $x=uv$, $y=u(1-v)$ with $u\\in(0,\\infty)$, $v\\in(0,1)$: a $C^{1}$ bijection with Jacobian $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=u$ (quoted change-of-variables theorem). Then", "th": "เปลี่ยนตัวแปร $x=uv$, $y=u(1-v)$ โดย $u\\in(0,\\infty)$, $v\\in(0,1)$: เป็น $C^{1}$ หนึ่งต่อหนึ่งทั่วถึง มีจาโคเบียน $\\left|\\frac{\\partial(x,y)}{\\partial(u,v)}\\right|=u$ (อ้างทฤษฎีบทการเปลี่ยนตัวแปร) จะได้", "m": "\\Gamma(m)\\Gamma(n)=\\int_{0}^{\\infty}u^{m+n-1}e^{-u}du\\int_{0}^{1}v^{m-1}(1-v)^{n-1}dv=\\Gamma(m+n)\\,B(m,n)."}, {"en": "(v) Substitute $x=\\sin^{2}\\theta$, $dx=2\\sin\\theta\\cos\\theta\\,d\\theta$ in $B(m,n)$: $x^{m-1}(1-x)^{n-1}dx=2\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta$. $\\blacksquare$", "th": "(v) แทน $x=\\sin^{2}\\theta$, $dx=2\\sin\\theta\\cos\\theta\\,d\\theta$ ใน $B(m,n)$: $x^{m-1}(1-x)^{n-1}dx=2\\sin^{2m-1}\\theta\\cos^{2n-1}\\theta\\,d\\theta$ $\\blacksquare$", "m": ""}], "ex": [{"q": "\\int_{0}^{\\infty}x^{5}e^{-x}\\,dx", "al": "120", "s": ["\\Gamma(6)=5!=120"]}, {"q": "\\int_{0}^{1}x^{3}(1-x)^{2}\\,dx", "al": "\\frac{1}{60}", "s": ["B(4,3)=\\frac{\\Gamma(4)\\Gamma(3)}{\\Gamma(7)}=\\frac{3!\\,2!}{6!}=\\frac{12}{720}=\\frac{1}{60}"]}], "pr": [{"q": "\\int_{0}^{\\infty}x^{4}e^{-x}\\,dx", "al": "24", "s": ["\\Gamma(5)=4!=24"], "h": "$\\Gamma(n+1)=n!$.", "ht": "$\\Gamma(n+1)=n!$", "v": 24.0}, {"q": "\\int_{0}^{\\infty}x^{3}e^{-2x}\\,dx", "al": "\\frac38", "s": ["u=2x:\\ \\frac{1}{2^{4}}\\int_{0}^{\\infty}u^{3}e^{-u}du=\\frac{3!}{16}=\\frac38"], "h": "Let $u=2x$.", "ht": "ให้ $u=2x$", "v": 0.375}, {"q": "\\int_{0}^{1}x^{2}(1-x)^{3}\\,dx", "al": "\\frac{1}{60}", "s": ["B(3,4)=\\frac{2!\\,3!}{6!}=\\frac{1}{60}"], "h": "$m=3$, $n=4$.", "ht": "$m=3$, $n=4$", "v": 0.016666666666666666}, {"q": "\\int_{0}^{\\infty}\\sqrt x\\,e^{-x}\\,dx", "al": "\\frac{\\sqrt\\pi}{2}", "s": ["\\Gamma\\left(\\tfrac32\\right)=\\tfrac12\\Gamma\\left(\\tfrac12\\right)=\\frac{\\sqrt\\pi}{2}"], "h": "$\\Gamma\\left(\\frac32\\right)=\\frac12\\Gamma\\left(\\frac12\\right)$.", "ht": "$\\Gamma\\left(\\frac32\\right)=\\frac12\\Gamma\\left(\\frac12\\right)$", "v": 0.886226925452758}, {"q": "\\int_{0}^{\\frac\\pi2}\\sin^{3}\\theta\\cos^{5}\\theta\\,d\\theta", "al": "\\frac{1}{24}", "s": ["2m-1=3,\\ 2n-1=5:\\ m=2,\\ n=3", "\\tfrac12B(2,3)=\\tfrac12\\cdot\\frac{1!\\,2!}{4!}=\\frac{1}{24}"], "h": "Use (v): $2m-1=3$, $2n-1=5$.", "ht": "ใช้ (v): $2m-1=3$, $2n-1=5$", "v": 0.041666666666666664}]}];
var BEE_LV = [{"n": "Warm-up", "t": 60, "d": "Powers, $e^{x}$, $\\dfrac{1}{x}$, $\\sin x$ and $\\cos x$: the basics, fast.", "card": ["Reverse the power rule: $\\displaystyle\\int x^{n}dx=\\frac{x^{n+1}}{n+1}+C$ for $n\\neq-1$, and $\\displaystyle\\int\\frac{1}{x}dx=\\ln|x|+C$.", "For $(ax+b)^{n}$, $e^{ax}$, $\\sin(ax)$: integrate as usual, then divide by $a$.", "Definite integrals: find $F$, then work out $F(b)-F(a)$. No $+C$ needed."], "nt": "อุ่นเครื่อง", "dt": "เลขยกกำลัง $e^{x}$, $\\dfrac{1}{x}$, $\\sin x$ และ $\\cos x$: พื้นฐานแบบเร็ว", "ct": ["กลับกฎเลขยกกำลัง: $\\displaystyle\\int x^{n}dx=\\frac{x^{n+1}}{n+1}+C$ เมื่อ $n\\neq-1$ และ $\\displaystyle\\int\\frac{1}{x}dx=\\ln|x|+C$", "สำหรับ $(ax+b)^{n}$, $e^{ax}$, $\\sin(ax)$: อินทิเกรตตามปกติแล้วหารด้วย $a$", "อินทิกรัลจำกัดเขต: หา $F$ แล้วคำนวณ $F(b)-F(a)$ ไม่ต้องมี $+C$"]}, {"n": "Exam", "t": 90, "d": "IAL P4 and FP3 methods: parts, substitution, partial fractions, inverse trig.", "card": ["By parts: $\\displaystyle\\int u\\,v'\\,dx=uv-\\int u'\\,v\\,dx$. Choose $u$ to get simpler when differentiated ($x$, $\\ln x$).", "Spot $\\dfrac{f'(x)}{f(x)}$: the answer is $\\ln|f(x)|$.", "Standard forms: $\\displaystyle\\int\\frac{dx}{1+x^{2}}=\\arctan x$, $\\displaystyle\\int\\frac{dx}{\\sqrt{1+x^{2}}}=\\operatorname{arsinh}x$."], "nt": "ข้อสอบ", "dt": "วิธีใน IAL P4 และ FP3: by parts, การแทนค่า, เศษส่วนย่อย, ฟังก์ชันตรีโกณผกผัน", "ct": ["By parts: $\\displaystyle\\int u\\,v'\\,dx=uv-\\int u'\\,v\\,dx$ เลือก $u$ ที่ดิฟแล้วง่ายลง ($x$, $\\ln x$)", "สังเกตรูป $\\dfrac{f'(x)}{f(x)}$: คำตอบคือ $\\ln|f(x)|$", "รูปมาตรฐาน: $\\displaystyle\\int\\frac{dx}{1+x^{2}}=\\arctan x$, $\\displaystyle\\int\\frac{dx}{\\sqrt{1+x^{2}}}=\\operatorname{arsinh}x$"]}, {"n": "Tricks", "t": 120, "d": "King's rule and symmetry: the shortcuts Bee champions spot in seconds.", "card": ["<b>King's rule:</b> $\\displaystyle\\int_{a}^{b}f(x)\\,dx=\\int_{a}^{b}f(a+b-x)\\,dx$. Replace $x$ by $a+b-x$, add the two versions of $I$, and often everything cancels to $2I=\\int_{a}^{b}1\\,dx$.", "Example: $I=\\displaystyle\\int_{0}^{\\pi/2}\\frac{\\sin x}{\\sin x+\\cos x}dx$. King's rule swaps $\\sin$ and $\\cos$, so $2I=\\displaystyle\\int_{0}^{\\pi/2}1\\,dx=\\frac{\\pi}{2}$ and $I=\\dfrac{\\pi}{4}$.", "<b>Odd functions</b> on $[-a,a]$ integrate to $0$. For $\\dfrac{f(x)}{1+e^{x}}$ with $f$ even, $\\displaystyle\\int_{-a}^{a}\\frac{f(x)}{1+e^{x}}dx=\\int_{0}^{a}f(x)\\,dx$."], "nt": "ทริค", "dt": "King's rule และความสมมาตร: ทางลัดที่แชมป์ Bee มองออกในไม่กี่วินาที", "ct": ["<b>King's rule:</b> $\\displaystyle\\int_{a}^{b}f(x)\\,dx=\\int_{a}^{b}f(a+b-x)\\,dx$ แทน $x$ ด้วย $a+b-x$ แล้วบวก $I$ ทั้งสองแบบ บ่อยครั้งจะตัดกันเหลือ $2I=\\int_{a}^{b}1\\,dx$", "ตัวอย่าง: $I=\\displaystyle\\int_{0}^{\\pi/2}\\frac{\\sin x}{\\sin x+\\cos x}dx$ King's rule สลับ $\\sin$ กับ $\\cos$ จึงได้ $2I=\\displaystyle\\int_{0}^{\\pi/2}1\\,dx=\\frac{\\pi}{2}$ และ $I=\\dfrac{\\pi}{4}$", "<b>ฟังก์ชันคี่</b> บน $[-a,a]$ อินทิเกรตได้ $0$ สำหรับ $\\dfrac{f(x)}{1+e^{x}}$ เมื่อ $f$ เป็นฟังก์ชันคู่ $\\displaystyle\\int_{-a}^{a}\\frac{f(x)}{1+e^{x}}dx=\\int_{0}^{a}f(x)\\,dx$"]}, {"n": "Feynman", "t": 180, "d": "Feynman's trick: differentiate under the integral sign with a parameter.", "card": ["<b>Feynman's trick:</b> put a parameter $t$ into the integral, $I(t)=\\displaystyle\\int f(x,t)\\,dx$. Then $I'(t)=\\displaystyle\\int\\frac{\\partial f}{\\partial t}dx$, which is often much easier.", "Example: $I(t)=\\displaystyle\\int_{0}^{1}\\frac{x^{t}-1}{\\ln x}dx$. Differentiating, $I'(t)=\\displaystyle\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}$, so $I(t)=\\ln(t+1)$ (since $I(0)=0$). So $\\displaystyle\\int_{0}^{1}\\frac{x-1}{\\ln x}dx=\\ln2$.", "Find the constant with an easy value of $t$ (often $I(0)=0$ or $t\\to\\infty$)."], "nt": "Feynman", "dt": "Feynman's trick: ดิฟเฟอเรนชิเอตภายใต้เครื่องหมายอินทิกรัลด้วยพารามิเตอร์", "ct": ["<b>Feynman's trick:</b> ใส่พารามิเตอร์ $t$ ลงในอินทิกรัล $I(t)=\\displaystyle\\int f(x,t)\\,dx$ แล้ว $I'(t)=\\displaystyle\\int\\frac{\\partial f}{\\partial t}dx$ ซึ่งมักง่ายกว่ามาก", "ตัวอย่าง: $I(t)=\\displaystyle\\int_{0}^{1}\\frac{x^{t}-1}{\\ln x}dx$ ดิฟได้ $I'(t)=\\displaystyle\\int_{0}^{1}x^{t}dx=\\frac{1}{t+1}$ ดังนั้น $I(t)=\\ln(t+1)$ (เพราะ $I(0)=0$) จึงได้ $\\displaystyle\\int_{0}^{1}\\frac{x-1}{\\ln x}dx=\\ln2$", "หาค่าคงที่จากค่า $t$ ที่ง่าย (มักเป็น $I(0)=0$ หรือ $t\\to\\infty$)"]}, {"n": "Bee qualifier", "t": 120, "d": "Mixed integrals in the style of a Bee qualifying round: 2 minutes each.", "card": ["Read the whole integral first: is there symmetry, a hidden $f'/f$, or a substitution that makes it standard?", "For $\\displaystyle\\int_{0}^{\\infty}$, check the answer is finite, and try $x\\to\\dfrac{1}{x}$.", "Answers are often in $\\pi$, $\\ln2$ or $\\sqrt{2}$: type them as pi, ln(2), sqrt(2)."], "nt": "รอบคัดเลือก", "dt": "โจทย์ผสมแบบรอบคัดเลือกของ Bee: ข้อละ 2 นาที", "ct": ["อ่านอินทิกรัลทั้งหมดก่อน: มีความสมมาตร มี $f'/f$ ซ่อนอยู่ หรือมีการแทนค่าที่ทำให้เป็นรูปมาตรฐานไหม", "สำหรับ $\\displaystyle\\int_{0}^{\\infty}$ ตรวจว่าคำตอบมีค่าจำกัด แล้วลอง $x\\to\\dfrac{1}{x}$", "คำตอบมักมี $\\pi$, $\\ln2$ หรือ $\\sqrt{2}$: พิมพ์เป็น pi, ln(2), sqrt(2)"]}, {"n": "Bee final", "t": 300, "d": "The hardest: famous integrals with beautiful answers. 5 minutes each, like a Bee final.", "card": ["Series: expand, e.g. $\\dfrac{1}{1+x}=\\displaystyle\\sum(-1)^{n}x^{n}$, integrate term by term, and recognise $\\displaystyle\\sum\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}$.", "Combine tricks: King's rule plus symmetry, or a substitution followed by Feynman.", "If stuck, try $x\\to\\dfrac{1}{x}$, $x\\to\\tan\\theta$, or $x\\to1-x$."], "nt": "รอบชิง", "dt": "ยากที่สุด: อินทิกรัลชื่อดังที่คำตอบสวยงาม ข้อละ 5 นาทีแบบรอบชิง Bee", "ct": ["อนุกรม: กระจาย เช่น $\\dfrac{1}{1+x}=\\displaystyle\\sum(-1)^{n}x^{n}$ อินทิเกรตทีละพจน์ แล้วจำ $\\displaystyle\\sum\\frac{1}{n^{2}}=\\frac{\\pi^{2}}{6}$", "ผสมทริค: King's rule กับความสมมาตร หรือแทนค่าแล้วตามด้วย Feynman", "ถ้าติด ลอง $x\\to\\dfrac{1}{x}$, $x\\to\\tan\\theta$ หรือ $x\\to1-x$"]}];
